#include "qjs.h"

JSCtx *ctx;
static char *mem_base;
static size_t mem_off, mem_size;
void *js_malloc(size_t n) {
    n = (n + 15) & ~(size_t)15;
    if (mem_off + n > mem_size) {
        while (mem_off + n > mem_size) mem_size = mem_size ? mem_size * 2 : (1 << 20);
        mem_base = realloc(mem_base, mem_size);
        if (!mem_base) { fprintf(stderr, "qjs: out of memory\n"); exit(1); }
    }
    void *p = mem_base + mem_off;
    mem_off += n;
    memset(p, 0, n);
    return p;
}
void *js_realloc(void *p, size_t n) {
    if (!p) return js_malloc(n);
    /* bump allocator: allocate new and copy (we do not track old size; caller passes it) */
    void *q = js_malloc(n);
    memcpy(q, p, n);
    return q;
}
char *js_strdup(const char *s) { size_t l = strlen(s) + 1; char *r = js_malloc(l); memcpy(r, s, l); return r; }

#define STR_DEFAULT 0
