/* ------------------------------ objects ---------------------------------- */
JSObject *js_new_object(uint8_t cls) {
    JSObject *o = js_malloc(sizeof(JSObject));
    o->cls = cls;
    o->extensible = 1;
    o->proto = ctx->obj_proto;
    return o;
}
Prop *obj_find_prop(JSObject *o, JSValue key) {
    for (Prop *p = o->props; p; p = p->next)
        if (p->key.tag == key.tag && p->key.u.p == key.u.p) return p;
    return NULL;
}
Prop *obj_find_prop_str(JSObject *o, const char *name) {
    JSValue k = js_atom(name);
    return obj_find_prop(o, k);
}
Prop *obj_add_prop(JSObject *o, JSValue key, JSValue val, uint8_t flags) {
    Prop *p = js_malloc(sizeof(Prop));
    p->key = key; p->val = val; p->flags = flags;
    p->next = o->props;
    o->props = p;
    return p;
}
void js_define_prop(JSObject *o, const char *name, JSValue val, uint8_t flags) {
    JSValue k = js_atom(name);
    Prop *p = obj_find_prop(o, k);
    if (p) { p->val = val; p->flags = flags; return; }
    obj_add_prop(o, k, val, flags);
}
void js_define_method(JSObject *o, const char *name, JSCFunc fn, int len, void *opaque) {
    Func *f = js_malloc(sizeof(Func));
    f->hdr.cls = O_FUNCTION;
    f->hdr.proto = ctx->func_proto;
    f->hdr.extensible = 1;
    f->is_native = 1;
    f->cfunc = fn;
    f->name = name;
    f->length = len;
    f->opaque = opaque;
    f->is_ctor = 1;
    JSValue fv; fv.u.p = f; fv.tag = T_OBJ;
    js_define_prop(o, name, fv, P_W | P_C);
}
void js_define_getter(JSObject *o, const char *name, JSCFunc fn, void *opaque) {
    JSValue k = js_atom(name);
    Prop *p = obj_find_prop(o, k);
    if (!p) { p = obj_add_prop(o, k, js_undef(), P_ACC | P_E | P_C); }
    Func *f = js_malloc(sizeof(Func));
    f->hdr.cls = O_FUNCTION;
    f->hdr.proto = ctx->func_proto;
    f->is_native = 1; f->cfunc = fn; f->name = name; f->opaque = opaque; f->length = 0;
    f->is_method = 1;
    JSValue fv; fv.u.p = f; fv.tag = T_OBJ;
    p->getter = f;
}
void js_define_setter(JSObject *o, const char *name, JSCFunc fn, void *opaque) {
    JSValue k = js_atom(name);
    Prop *p = obj_find_prop(o, k);
    if (!p) { p = obj_add_prop(o, k, js_undef(), P_ACC | P_E | P_C); }
    Func *f = js_malloc(sizeof(Func));
    f->hdr.cls = O_FUNCTION;
    f->hdr.proto = ctx->func_proto;
    f->is_native = 1; f->cfunc = fn; f->name = name; f->opaque = opaque; f->length = 1;
    f->is_method = 1;
    JSValue fv; fv.u.p = f; fv.tag = T_OBJ;
    p->setter = f;
}

static JSValue type_name_of(JSValue v) {
    switch (v.tag) {
    case T_UNDEF: return js_atom("undefined");
    case T_NULL: return js_atom("null");
    case T_BOOL: return js_atom("boolean");
    case T_INT: case T_FLOAT: return js_atom("number");
    case T_STR: return js_atom("string");
    case T_SYM: return js_atom("symbol");
    case T_BIG: return js_atom("bigint");
    default: {
        JSObject *o = obj_of(v);
        if (o->cls == O_FUNCTION) return js_atom("function");
        return js_atom("object");
    }
    }
}

/* get the prototype used for property lookups of a primitive */
static JSObject *proto_for(JSValue v) {
    switch (v.tag) {
    case T_INT: case T_FLOAT: return ctx->num_proto;
    case T_STR: return ctx->str_proto;
    case T_BOOL: return ctx->bool_proto;
    case T_SYM: return ctx->sym_proto;
    case T_BIG: return ctx->bigint_proto;
    default: return obj_of(v)->proto;
    }
}

/* -------- property read -------- */
JSValue obj_get_prop(JSObject *o, JSValue key, int pos) {
    JSObject *p = o;
    int guard = 0;
    while (p && guard++ < 100) {
        Prop *pr = obj_find_prop(p, key);
        if (pr) {
            if (pr->flags & P_ACC) {
                if (pr->getter) return js_call((JSValue){ .u.p = pr->getter, .tag = T_OBJ }, (JSValue){ .u.p = o, .tag = T_OBJ }, 0, NULL, pos);
                return js_undef();
            }
            return pr->val;
        }
        p = p->proto;
    }
    return js_undef();
}
JSValue obj_get_prop_str(JSObject *o, const char *name, int pos) {
    return obj_get_prop(o, js_atom(name), pos);
}

static const char *obj_class_name(JSObject *o) {
    switch (o->cls) {
    case O_OBJECT: case O_GLOBAL: case O_MODULE_NS: case O_ARGUMENTS: case O_PROXY:
        return "Object";
    case O_ARRAY: return "Array";
    case O_FUNCTION: return "Function";
    case O_ERROR: return "Error";
    case O_NUMBER: return "Number";
    case O_STRING: return "String";
    case O_BOOLEAN: return "Boolean";
    case O_SYMBOL: return "Symbol";
    case O_FILE: return "FILE";
    case O_GENERATOR: return "Generator";
    case O_PROMISE: return "Promise";
    case O_MAP: return "Map";
    case O_SET: return "Set";
    case O_WEAKMAP: return "WeakMap";
    case O_WEAKSET: return "WeakSet";
    case O_DATE: return "Date";
    case O_REGEXP: return "RegExp";
    case O_ARRAYBUF: return "ArrayBuffer";
    case O_DATAVIEW: return "DataView";
    case O_TYPEDARRAY: return "TypedArray";
    case O_ITERATOR: return "Iterator";
    default: return "Object";
    }
}

static JSValue js_error_from_name(JSValue v) {
    /* a value describing the type for error messages */
    if (v.tag == T_UNDEF) return js_atom("undefined");
    if (v.tag == T_NULL) return js_atom("null");
    return js_undef();
}

JSValue js_get_prop_impl(JSValue v, JSValue key, int pos, int opt, int named) {
    if (v.tag == T_UNDEF || v.tag == T_NULL) {
        if (opt) return js_undef();
        JSValue tn = type_name_of(v);
        const char *tns = str_val(tn)->buf ? (const char *)str_val(tn)->buf : "";
        if (key.tag == T_STR && named)
            js_throw_error(ERR_TYPE, "cannot read property '%s' of %s", str_val(key)->buf, tns);
        else
            js_throw_error(ERR_TYPE, "cannot read property of %s", tns);
    }
    if (v.tag == T_STR) {
        JSString *s = str_val(v);
        if (key.tag == T_STR && str_equal(str_val(key), str_val(js_atom("length")))) return js_int(s->len);
        /* integer index */
        if (key.tag == T_INT || (key.tag == T_FLOAT && str_val(js_num_to_string(key.u.f))->buf[0] >= '0')) {
            double d = js_to_number(key);
            int64_t i = (int64_t)d;
            if (d == (double)i && i >= 0 && i < s->len) return js_substring(s, (int)i, (int)i + 1);
        }
    }
    JSObject *o = v.tag == T_OBJ ? obj_of(v) : NULL;
    if (!o) {
        JSObject *pr = proto_for(v);
        if (!pr) return js_undef();
        return obj_get_prop(pr, key, pos);
    }
    return obj_get_prop(o, key, pos);
}
JSValue js_get_prop(JSValue obj, JSValue key, int pos, int opt) {
    return js_get_prop_impl(obj, key, pos, opt, 0);
}
JSValue js_get_prop_named(JSValue obj, JSValue key, int pos) {
    return js_get_prop_impl(obj, key, pos, 0, 1);
}

/* find the property descriptor along the chain, stopping at own */
static Prop *chain_find_setter(JSObject *o, JSValue key, JSObject **holder) {
    for (JSObject *p = o; p; p = p->proto) {
        Prop *pr = obj_find_prop(p, key);
        if (pr) { if (holder) *holder = p; return pr; }
    }
    return NULL;
}

static void call_setter(JSObject *setter, JSValue this_val, JSValue val, int pos) {
    JSValue args[1]; args[0] = val;
    js_call((JSValue){ .u.p = setter, .tag = T_OBJ }, this_val, 1, args, pos);
}

int obj_set_prop_impl(JSObject *o, JSValue key, JSValue val, int throw_flag, int pos, int named, int create_new) {
    Prop *pr = obj_find_prop(o, key);
    if (pr) {
        if (pr->flags & P_ACC) {
            if (pr->setter) { call_setter(pr->setter, (JSValue){ .u.p = o, .tag = T_OBJ }, val, pos); return 1; }
            if (throw_flag) {
                if (key.tag == T_STR && named)
                    js_throw_error(ERR_TYPE, "cannot set property '%s' of an object with only a getter", str_val(key)->buf);
                else
                    js_throw_error(ERR_TYPE, "cannot set property of an object with only a getter");
            }
            return 0;
        }
        if (!(pr->flags & P_W)) {
            if (throw_flag) {
                if (key.tag == T_STR && named)
                    js_throw_error(ERR_TYPE, "cannot assign to read only property '%s' of object", str_val(key)->buf);
                else
                    js_throw_error(ERR_TYPE, "cannot assign to read only property of object");
            }
            return 0;
        }
        pr->val = val;
        return 1;
    }
    /* not own: look for setter on proto chain */
    JSObject *holder = NULL;
    Prop *cpr = chain_find_setter(o->proto, key, &holder);
    if (cpr && (cpr->flags & P_ACC)) {
        if (cpr->setter) { call_setter(cpr->setter, (JSValue){ .u.p = o, .tag = T_OBJ }, val, pos); return 1; }
        if (throw_flag) {
            if (key.tag == T_STR && named)
                js_throw_error(ERR_TYPE, "cannot set property '%s' of an object with only a getter", str_val(key)->buf);
            else
                js_throw_error(ERR_TYPE, "cannot set property of an object with only a getter");
        }
        return 0;
    }
    if (!create_new) return 0;
    if (!o->extensible) {
        if (throw_flag) {
            if (key.tag == T_STR && named)
                js_throw_error(ERR_TYPE, "cannot add property '%s', object is non-extensible", str_val(key)->buf);
            else
                js_throw_error(ERR_TYPE, "cannot add property, object is non-extensible");
        }
        return 0;
    }
    obj_add_prop(o, key, val, P_W | P_E | P_C);
    return 1;
}
int obj_set_prop(JSObject *o, JSValue key, JSValue val, int throw_flag, int pos) {
    return obj_set_prop_impl(o, key, val, throw_flag, pos, 0, 1);
}
JSValue js_set_prop(JSValue obj, JSValue key, JSValue val, int pos) {
    if (obj.tag == T_UNDEF || obj.tag == T_NULL) {
        JSValue tn = type_name_of(obj);
        const char *tns = (const char *)str_val(tn)->buf;
        if (key.tag == T_STR) js_throw_error(ERR_TYPE, "cannot set property '%s' of %s", str_val(key)->buf, tns);
        else js_throw_error(ERR_TYPE, "cannot set property of %s", tns);
    }
    if (obj.tag == T_STR || obj.tag == T_INT || obj.tag == T_FLOAT || obj.tag == T_BOOL ||
        obj.tag == T_SYM || obj.tag == T_BIG) {
        /* silent failure */
        return val;
    }
    JSValue k = js_to_property_key(key);
    obj_set_prop(obj_of(obj), k, val, 1, pos);
    return val;
}
int obj_del_prop(JSObject *o, JSValue key, int throw_flag, int pos) {
    Prop **pp = &o->props;
    while (*pp) {
        if ((*pp)->key.tag == key.tag && (*pp)->key.u.p == key.u.p) {
            if (!((*pp)->flags & P_C)) {
                if (throw_flag) {
                    if (key.tag == T_STR)
                        js_throw_error(ERR_TYPE, "cannot delete property '%s' of an object", str_val(key)->buf);
                    else
                        js_throw_error(ERR_TYPE, "cannot delete property of an object");
                }
                return 0;
            }
            *pp = (*pp)->next;
            return 1;
        }
        pp = &(*pp)->next;
    }
    return 1;
}
CEOF
