    case O_BOOLEAN: return js_atom("[object Boolean]");
    case O_SYMBOL: return js_atom("[object Symbol]");
    case O_ARGUMENTS: return js_atom("[object Arguments]");
    case O_GLOBAL: return js_atom("[object global]");
    case O_MODULE_NS: return js_atom("[object Module]");
    case O_FILE: return js_atom("[object Object]");
    case O_GENERATOR: return js_atom("[object Generator]");
    case O_PROMISE: return js_atom("[object Promise]");
    case O_MAP: return js_atom("[object Map]");
    case O_SET: return js_atom("[object Set]");
    case O_WEAKMAP: return js_atom("[object WeakMap]");
    case O_WEAKSET: return js_atom("[object WeakSet]");
    case O_DATE: return js_atom("[object Date]");
    case O_REGEXP: return js_atom("[object RegExp]");
    case O_ARRAYBUF: return js_atom("[object ArrayBuffer]");
    case O_DATAVIEW: return js_atom("[object DataView]");
    case O_TYPEDARRAY: return js_atom("[object Uint8Array]");
