        JSValue args[1];
        args[0] = js_string(hint == 1 ? "string" : hint == 2 ? "number" : "default");
        JSValue r = js_call(m, v, 1, args, 0);
        if (r.tag != T_OBJ) return r;
    }
    const char *names[2];
    int n = 0;
    if (hint == 1) { names[0] = "toString"; names[1] = "valueOf"; n = 2; }
    else if (hint == 2) { names[0] = "valueOf"; names[1] = "toString"; n = 2; }
    else { names[0] = "valueOf"; names[1] = "toString"; n = 2; }
    for (int i = 0; i < n; i++) {
        JSValue f = obj_get_prop(o, js_atom(names[i]), 0);
        if (f.tag == T_OBJ && obj_of(f)->cls == O_FUNCTION) {
            JSValue r = js_call(f, v, 0, NULL, 0);
