    case T_BOOL: return v.u.i ? js_atom("true") : js_atom("false");
    case T_INT: return js_int_to_string(v.u.i);
    case T_FLOAT: return js_num_to_string(v.u.f);
    case T_STR: return v;
    case T_BIG: return bi_to_string_v((JSBigInt *)v.u.p, 10);
    case T_SYM: js_throw_error(ERR_TYPE, "cannot convert symbol to string");
    default: {
        JSValue p = js_to_primitive(v, 1);
        if (p.tag == T_SYM) js_throw_error(ERR_TYPE, "cannot convert symbol to string");
        if (p.tag != T_STR) js_throw_error(ERR_TYPE, "cannot convert object to string");
        return p;
    }
    }
    return js_undef();
}
JSValue js_to_string_quiet(JSValue v) {
    switch (v.tag) {
    case T_UNDEF: return js_atom("undefined");
    case T_NULL: return js_atom("null");
    case T_BOOL: return v.u.i ? js_atom("true") : js_atom("false");
    case T_INT: return js_int_to_string(v.u.i);
    case T_FLOAT: return js_num_to_string(v.u.f);
    case T_STR: return v;
    case T_BIG: return bi_to_string_v((JSBigInt *)v.u.p, 10);
    default: {
        JSValue p = js_to_primitive(v, 1);
