    if (v.tag == T_STR) {
        JSString *s = str_val(v);
        for (int i = 0; i < s->len; i++) {
            char k[16];
            int n = snprintf(k, sizeof k, "%d", i);
            JSValue key = js_atom_buf((const uint8_t *)k, n, n);
            JSValue ch = js_substring(s, i, i + 1);
            obj_add_prop(o, key, ch, P_W | P_E | P_C);
        }
        JSValue lk = js_atom("length");
        obj_add_prop(o, lk, js_int(s->len), P_E | P_C);
    }
    return vo;
}
JSValue js_typeof(JSValue v) {
    switch (v.tag) {
    case T_UNDEF: return js_atom("undefined");
    case T_NULL: return js_atom("object");
    case T_BOOL: return js_atom("boolean");
    case T_INT: case T_FLOAT: return js_atom("number");
    case T_STR: return js_atom("string");
    case T_SYM: return js_atom("symbol");
    case T_BIG: return js_atom("bigint");
    default: return obj_of(v)->cls == O_FUNCTION ? js_atom("function") : js_atom("object");
    }
}
JSValue js_value_of_str(JSValue v) { return js_to_string_v(v); }
