        if (c == ' ' || c == '\t' || c == '\v' || c == '\f' || c == '\r') { p->pos++; continue; }
        if (c == '\n') { nl = 1; p->pos++; continue; }
        if (c == '/' && p->pos + 1 < p->len && p->src[p->pos + 1] == '/') {
            while (p->pos < p->len && p->src[p->pos] != '\n') p->pos++;
            continue;
        }
        if (c == '/' && p->pos + 1 < p->len && p->src[p->pos + 1] == '*') {
            p->pos += 2;
            while (p->pos < p->len && !(p->src[p->pos] == '*' && p->pos + 1 < p->len && p->src[p->pos + 1] == '/')) { if (p->src[p->pos] == '\n') nl = 1; p->pos++; }
            if (p->pos >= p->len) perr(p, "unexpected end of comment");
            p->pos += 2;
            continue;
        }
        break;
    }
    if (c == '<' && p->pos + 3 < p->len && p->src[p->pos+1] == '!' && p->src[p->pos+2] == '-' && p->src[p->pos+3] == '-') {
        while (p->pos < p->len && p->src[p->pos] != '\n') p->pos++;
        return next_token(p);
    }
    if (c == '-' && nl && p->pos + 2 < p->len && p->src[p->pos+1] == '-' && p->src[p->pos+2] == '>') {
        while (p->pos < p->len && p->src[p->pos] != '\n') p->pos++;
        return next_token(p);
    }
    p->tok.nl = nl;
    p->tok.pos = p->pos;
    p->tok.ident_kw = 0;
    if (isdigit(c)) { scan_number(p); return; }
    if (c == '.' && p->pos + 1 < p->len && isdigit(p->src[p->pos+1])) { scan_number(p); return; }
    if (is_id_start(c)) {
        int start = p->pos;
        while (p->pos < p->len) {
            uint32_t cp; int n = js_utf8_decode((const uint8_t *)p->src + p->pos, p->len - p->pos, &cp);
            if (n < 0) break;
            if (!is_id_part(cp)) break;
            p->pos += n;
        }
        int l = p->pos - start;
        int kw = kw_lookup(p->src + start, l);
        p->tok.type = kw ? kw : T_IDENT;
        p->tok.str = js_string_n(p->src + start, l);
        p->tok.ident_kw = kw ? 1 : 0;
        if (kw) p->tok.ident_kw = 1;
        return;
    }
    if (c == '"' || c == '\'') { scan_string(p, c); return; }
    if (c == '`') { scan_template(p); return; }
    if (c == '/' && regex_allowed(p)) { scan_regex(p); return; }
    /* multi-char operators */
    int t = 0;
    switch (c) {
    case '*': if (p->pos+1 < p->len && p->src[p->pos+1] == '*') { if (p->pos+2 < p->len && p->src[p->pos+2]=='=') { t = OP_POWA; p->pos += 3; } else { t = OP_POW; p->pos += 2; } } else if (p->pos+1 < p->len && p->src[p->pos+1]=='=') { t = OP_MULA; p->pos += 2; } else t = '*'; break;
    case '+': if (p->pos+1<p->len && p->src[p->pos+1]=='+') { t = OP_INCR; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_ADDA; p->pos += 2; } else t = '+'; break;
    case '-': if (p->pos+1<p->len && p->src[p->pos+1]=='-') { t = OP_DECR; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_SUBA; p->pos += 2; } else t = '-'; break;
    case '/': if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_DIVA; p->pos += 2; } else t = '/'; break;
    case '%': if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_MODA; p->pos += 2; } else t = '%'; break;
    case '&': if (p->pos+1<p->len && p->src[p->pos+1]=='&') { t = OP_ANDAND; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_ANDA; p->pos += 2; } else t = '&'; break;
    case '|': if (p->pos+1<p->len && p->src[p->pos+1]=='|') { t = OP_OROR; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_ORA; p->pos += 2; } else t = '|'; break;
    case '^': if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_XORA; p->pos += 2; } else t = '^'; break;
    case '=': if (p->pos+2<p->len && p->src[p->pos+1]=='=' && p->src[p->pos+2]=='=') { t = OP_STREQ; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_EQ; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='>') { t = OP_ARROW; p->pos += 2; }
              else t = '='; break;
    case '!': if (p->pos+2<p->len && p->src[p->pos+1]=='=' && p->src[p->pos+2]=='=') { t = OP_STRNE; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_NE; p->pos += 2; }
              else t = '!'; break;
    case '<': if (p->pos+2<p->len && p->src[p->pos+1]=='<' && p->src[p->pos+2]=='=') { t = OP_SHLA; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='<') { t = OP_SHL; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_LE; p->pos += 2; }
              else t = '<'; break;
    case '>': if (p->pos+3<p->len && p->src[p->pos+1]=='>' && p->src[p->pos+2]=='>' && p->src[p->pos+3]=='=') { t = OP_USHRA; p->pos += 4; }
              else if (p->pos+2<p->len && p->src[p->pos+1]=='>' && p->src[p->pos+2]=='>') { t = OP_USHR; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='>' && p->src[p->pos+2]=='=') { t = OP_SHRA; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='>') { t = OP_SHR; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_GE; p->pos += 2; }
              else t = '>'; break;
    case '?': if (p->pos+2<p->len && p->src[p->pos+1]=='?' && p->src[p->pos+2]=='=') { t = OP_NULLISH; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='?') { t = OP_NULLISH; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='.') { t = OP_QDOT; p->pos += 2; }
              else t = '?'; break;
    case '.': if (p->pos+2<p->len && p->src[p->pos+1]=='.' && p->src[p->pos+2]=='.') { t = OP_ELLIPSIS; p->pos += 3; }
              else t = '.'; break;
    default: t = c; p->pos++; break;
    }
    p->tok.type = t;
}
CEOF
echo ok"}

actions.command:
cat > src/parse.c <<'CEOF'
#include "internal.h"
#include <ctype.h>
#include <stdarg.h>

/* token types */
#define T_EOF_ 0
#define T_NUM 1
#define T_STR 2
#define T_BIG 3
#define T_REG 4
#define T_IDENT 5
#define T_TMPL 6      /* template literal (no substitution) */
#define T_TMPLSTART 7 /* `...${ */
#define T_TMPLMID 8   /* }...${ */
#define T_TMPLEND 9   /* }...` */
#define KW 300
enum {
    K_VAR = KW, K_LET, K_CONST, K_FUNCTION, K_IF, K_ELSE, K_DO, K_WHILE, K_FOR,
    K_BREAK, K_CONTINUE, K_RETURN, K_THROW, K_TRY, K_CATCH, K_FINALLY, K_SWITCH,
    K_CASE, K_DEFAULT, K_CLASS, K_EXTENDS, K_SUPER, K_NEW, K_DELETE, K_TYPEOF,
    K_VOID, K_IN, K_INSTANCEOF, K_THIS, K_NULL, K_TRUE, K_FALSE, K_YIELD, K_AWAIT,
    K_ASYNC, K_IMPORT, K_EXPORT, K_FROM, K_AS, K_OF, K_STATIC, K_GET, K_SET,
    K_DEBUGGER, K_WITH, K_TARGET, K_ENUM
};
/* operators >= 256 */
enum {
    OP_POW = 256, OP_POWA, OP_ADDA, OP_SUBA, OP_MULA, OP_DIVA, OP_MODA, OP_ANDA,
    OP_ORA, OP_XORA, OP_SHLA, OP_SHRA, OP_USHRA, OP_EQ, OP_STREQ, OP_NE, OP_STRNE,
    OP_LE, OP_GE, OP_ANDAND, OP_OROR, OP_NULLISH, OP_INCR, OP_DECR, OP_SHL, OP_SHR,
    OP_USHR, OP_ARROW, OP_ELLIPSIS, OP_QDOT
};

typedef struct {
    int type;
    JSValue str;
    double num;
    int is_big;
    int pos;
    int nl;
    int re_flags;
    const char *re_src;
    int re_len;
    int ident_kw;
} Tok;

typedef struct {
    const char *src;
    int len, pos;
    Tok tok;
    Tok save;
    int has_save;
    int in_module, strict;
    int allow_in, allow_yield, allow_await, allow_default;
    SrcInfo *si;
    const char *filename;
    int depth;
    int no_in;
    int repl_wrap;
} Parse;

static void perr(Parse *p, const char *fmt, ...);

/* ------------------------------- lexer ----------------------------------- */
static int is_id_start(uint32_t c) {
    return c == '$' || c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
        (c >= 0x80 && !(c >= 0xd800 && c < 0xe000)) || c == 0xa2 || c == 0xb5;
}
static int is_id_part(uint32_t c) { return is_id_start(c) || (c >= '0' && c <= '9'); }

static const struct { const char *s; int t; } keywords[] = {
    { "var", K_VAR }, { "let", K_LET }, { "const", K_CONST }, { "function", K_FUNCTION },
    { "if", K_IF }, { "else", K_ELSE }, { "do", K_DO }, { "while", K_WHILE }, { "for", K_FOR },
    { "break", K_BREAK }, { "continue", K_CONTINUE }, { "return", K_RETURN },
    { "throw", K_THROW }, { "try", K_TRY }, { "catch", K_CATCH }, { "finally", K_FINALLY },
    { "switch", K_SWITCH }, { "case", K_CASE }, { "default", K_DEFAULT }, { "class", K_CLASS },
    { "extends", K_EXTENDS }, { "super", K_SUPER }, { "new", K_NEW }, { "delete", K_DELETE },
    { "typeof", K_TYPEOF }, { "void", K_VOID }, { "in", K_IN }, { "instanceof", K_INSTANCEOF },
    { "this", K_THIS }, { "null", K_NULL }, { "true", K_TRUE }, { "false", K_FALSE },
    { "yield", K_YIELD }, { "await", K_AWAIT }, { "async", K_ASYNC }, { "import", K_IMPORT },
    { "export", K_EXPORT }, { "from", K_FROM }, { "as", K_AS }, { "of", K_OF },
    { "static", K_STATIC }, { "get", K_GET }, { "set", K_SET }, { "debugger", K_DEBUGGER },
    { "with", K_WITH }, { "enum", K_ENUM },
    { NULL, 0 }
};
static int kw_lookup(const char *s, int n) {
    char buf[32];
    if (n > 31) return 0;
    memcpy(buf, s, n); buf[n] = 0;
    for (int i = 0; keywords[i].s; i++)
        if (strcmp(keywords[i].s, buf) == 0) return keywords[i].t;
    return 0;
}

static void scan_string(Parse *p, int quote) {
    Buf b; buf_init(&b, 32);
    int start = p->pos;
    p->pos++; /* skip quote */
    int units = 0;
    uint16_t u16[1024];
    for (;;) {
        if (p->pos >= p->len) perr(p, "unexpected end of string");
        uint8_t c = p->src[p->pos];
        if (c == quote) { p->pos++; break; }
        if (c == '\n' || c == '\r') perr(p, "unexpected end of string");
        if (c != '\\') {
            uint32_t cp; int n = js_utf8_decode((const uint8_t *)p->src + p->pos, p->len - p->pos, &cp);
            if (n < 0) { cp = c; n = 1; }
            if (cp >= 0x10000) { u16[units++] = (uint16_t)(0xd800 + ((cp - 0x10000) >> 10)); u16[units++] = (uint16_t)(0xdc00 + ((cp - 0x10000) & 0x3ff)); }
            else u16[units++] = (uint16_t)cp;
            if (units > 1000) { for (int i = 0; i < units; i++) { uint8_t t[4]; int l = js_utf8_encode(t, u16[i]); buf_put(&b, t, l); } units = 0; }
            p->pos += n;
            continue;
        }
        p->pos++;
        if (p->pos >= p->len) perr(p, "unexpected end of string");
        uint8_t e = p->src[p->pos++];
        uint32_t cp = 0;
        switch (e) {
        case 'n': cp = '\n'; break;
        case 'r': cp = '\r'; break;
        case 't': cp = '\t'; break;
        case 'b': cp = '\b'; break;
        case 'v': cp = 0x0b; break;
        case 'f': cp = 0x0c; break;
        case '0': if (p->pos < p->len && p->src[p->pos] >= '0' && p->src[p->pos] <= '9') { p->pos--; cp = 0; } else cp = 0; break;
        case '\n': while (p->pos < p->len && (p->src[p->pos] == '\r')) p->pos++; continue;
        case '\r': continue;
        case 'x': {
            if (p->pos + 2 > p->len) perr(p, "invalid escape sequence");
            int v = 0;
            for (int i = 0; i < 2; i++) { uint8_t c2 = p->src[p->pos + i]; int d = isxdigit(c2) ? (isdigit(c2) ? c2 - '0' : tolower(c2) - 'a' + 10) : -1; if (d < 0) perr(p, "invalid escape sequence"); v = v * 16 + d; }
            p->pos += 2; cp = v; break;
        }
        case 'u': {
            if (p->pos < p->len && p->src[p->pos] == '{') {
                p->pos++;
                int v = 0, any = 0;
                while (p->pos < p->len && p->src[p->pos] != '}') {
                    uint8_t c2 = p->src[p->pos];
                    int d = isxdigit(c2) ? (isdigit(c2) ? c2 - '0' : tolower(c2) - 'a' + 10) : -1;
                    if (d < 0) perr(p, "invalid unicode escape");
                    v = v * 16 + d; if (v > 0x10ffff) perr(p, "unicode escape out of range");
                    any = 1; p->pos++;
                }
                if (!any) perr(p, "invalid unicode escape");
                p->pos++;
                cp = v;
            } else {
                if (p->pos + 4 > p->len) perr(p, "invalid unicode escape");
                int v = 0;
                for (int i = 0; i < 4; i++) { uint8_t c2 = p->src[p->pos + i]; int d = isxdigit(c2) ? (isdigit(c2) ? c2 - '0' : tolower(c2) - 'a' + 10) : -1; if (d < 0) perr(p, "invalid unicode escape"); v = v * 16 + d; }
                p->pos += 4; cp = v;
            }
            break;
        }
        default:
            if (e >= '0' && e <= '7') {
                int v = e - '0';
                for (int i = 0; i < 2 && p->pos < p->len && p->src[p->pos] >= '0' && p->src[p->pos] <= '7'; i++) { v = v * 8 + (p->src[p->pos] - '0'); p->pos++; }
                if (p->strict && v != 0) perr(p, "octal escape sequences are not allowed in strict mode");
                cp = v;
            } else if (e >= 0x80) {
                uint32_t c2; int n = js_utf8_decode((const uint8_t *)p->src + p->pos - 1, p->len - p->pos + 1, &c2);
                if (n < 0) cp = e; else { p->pos += n - 1; cp = c2; }
            } else cp = e;
            break;
        }
        if (cp >= 0x10000) { u16[units++] = (uint16_t)(0xd800 + ((cp - 0x10000) >> 10)); u16[units++] = (uint16_t)(0xdc00 + ((cp - 0x10000) & 0x3ff)); }
        else u16[units++] = (uint16_t)cp;
        if (units > 1000) { for (int i = 0; i < units; i++) { uint8_t t[4]; int l = js_utf8_encode(t, u16[i]); buf_put(&b, t, l); } units = 0; }
    }
    for (int i = 0; i < units; i++) { uint8_t t[4]; int l = js_utf8_encode(t, u16[i]); buf_put(&b, t, l); }
    (void)start;
    p->tok.type = T_STR;
    int bl = b.len;
    /* count code units */
    int units2 = 0, i = 0;
    while (i < bl) { uint32_t cp; int n = js_utf8_decode(b.b + i, bl - i, &cp); if (n < 0) { n = 1; cp = b.b[i]; } units2 += cp >= 0x10000 ? 2 : 1; i += n; }
    p->tok.str = js_atom_buf(b.b, bl, units2);
}

static int scan_number(Parse *p) {
    int start = p->pos;
    double val = 0;
    int base = 10;
    int is_big = 0;
    if (p->pos + 1 < p->len && p->src[p->pos] == '0' &&
        (p->src[p->pos + 1] == 'x' || p->src[p->pos + 1] == 'X')) { base = 16; p->pos += 2; }
    else if (p->pos + 1 < p->len && p->src[p->pos] == '0' &&
        (p->src[p->pos + 1] == 'b' || p->src[p->pos + 1] == 'B')) { base = 2; p->pos += 2; }
    else if (p->pos + 1 < p->len && p->src[p->pos] == '0' &&
        (p->src[p->pos + 1] == 'o' || p->src[p->pos + 1] == 'O')) { base = 8; p->pos += 2; }
    else if (p->pos + 1 < p->len && p->src[p->pos] == '0' &&
        p->src[p->pos + 1] >= '0' && p->src[p->pos + 1] <= '9') { base = 8; p->pos++; }
    if (base != 10) {
        uint64_t hi = 0; int exp2 = 0, nd = 0;
        int big = 0;
        for (;;) {
            uint8_t c = p->pos < p->len ? p->src[p->pos] : 0;
            int d;
            if (c == '_') { p->pos++; continue; }
            if (c == 'n') { if (!nd) perr(p, "invalid number literal"); big = 1; p->pos++; break; }
            if (c >= '0' && c <= '9') d = c - '0';
            else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
            else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
            else break;
            if (d >= base) perr(p, "invalid number literal");
            if (!big && hi > (0x7fffffffffffffffULL - d) / (uint64_t)base) big = 1;
            if (!big) { hi = hi * base + d; nd++; }
            p->pos++;
        }
        if (!nd) perr(p, "invalid number literal");
        if (big) {
            /* build the digit string and parse as bigint */
            char tmp[2048]; int tl = 0;
            tmp[tl++] = '0';
            if (base == 16) tmp[tl++] = 'x'; else if (base == 8) tmp[tl++] = 'o'; else tmp[tl++] = 'b';
            for (int i = start + 2; i < p->pos; i++) if (p->src[i] != 'n' && p->src[i] != '_') tmp[tl++] = p->src[i];
            tmp[tl] = 0;
            int ok;
            JSBigInt *bb = bi_from_string(str_val(js_string_n(tmp, tl)), base == 16 ? 16 : base == 8 ? 8 : 2, &ok);
            if (!ok) perr(p, "invalid number literal");
            JSValue v; v.u.p = bb; v.tag = T_BIG;
            p->tok.type = T_BIG; p->tok.str = v; p->tok.pos = start;
            return 1;
        }
        val = ldexp((double)hi, exp2);
        p->tok.type = T_NUM; p->tok.num = val; p->tok.pos = start;
        return 1;
    }
    /* decimal */
    int hasdot = 0, hasexp = 0;
    int dstart = p->pos;
    for (;;) {
        uint8_t c = p->pos < p->len ? p->src[p->pos] : 0;
        if (c == '_') { p->pos++; continue; }
        if (c >= '0' && c <= '9') { p->pos++; continue; }
        if (c == '.' && !hasdot && !hasexp) { hasdot = 1; p->pos++; continue; }
        if ((c == 'e' || c == 'E') && !hasexp) {
            hasexp = 1; p->pos++;
            if (p->pos < p->len && (p->src[p->pos] == '+' || p->src[p->pos] == '-')) p->pos++;
            if (p->pos >= p->len || !isdigit((unsigned char)p->src[p->pos])) perr(p, "invalid number literal");
            continue;
        }
        if (c == 'n') {
            if (hasdot || hasexp) perr(p, "invalid number literal");
            if (p->pos == dstart) perr(p, "invalid number literal");
            is_big = 1; p->pos++; break;
        }
        break;
    }
    if (p->pos == dstart) perr(p, "invalid number literal");
    if (is_big) {
        char tmp[4096]; int tl = 0;
        for (int i = dstart; i < p->pos; i++) if (p->src[i] != '_') tmp[tl++] = p->src[i];
        tmp[tl] = 0;
        int ok;
        JSBigInt *bb = bi_from_string(str_val(js_string_n(tmp, tl)), 10, &ok);
        if (!ok) perr(p, "invalid number literal");
        JSValue v; v.u.p = bb; v.tag = T_BIG;
        p->tok.type = T_BIG; p->tok.str = v; p->tok.pos = start;
        return 1;
    }
    char tmp[512];
    int tl = p->pos - dstart;
    if (tl > 500) tl = 500;
    memcpy(tmp, p->src + dstart, tl);
    tmp[tl] = 0;
    for (int i = 0; i < tl; i++) if (tmp[i] == '_') { memmove(tmp + i, tmp + i + 1, tl - i); tl--; i--; }
    tmp[tl] = 0;
    val = strtod(tmp, NULL);
    /* check that the token ends properly */
    uint8_t c = p->pos < p->len ? p->src[p->pos] : 0;
    if (is_id_start(c)) perr(p, "invalid number literal");
    p->tok.type = T_NUM; p->tok.num = val; p->tok.pos = start;
    return 1;
}

static int regex_allowed(Parse *p) {
    /* determine if a '/' starts a regex based on the previous token */
    int t = p->tok.type;
    if (t == T_NUM || t == T_STR || t == T_BIG || t == T_IDENT || t == T_TMPL || t == T_TMPLEND) return 0;
    if (t == ')' || t == ']' || t == '}') return 0;
    if (t == K_THIS || t == K_TRUE || t == K_FALSE || t == K_NULL) return 0;
    if (t == K_SUPER) return 0;
    return 1;
}

static void scan_regex(Parse *p) {
    int start = p->pos;
    p->pos++; /* skip / */
    int in_class = 0;
    for (;;) {
        if (p->pos >= p->len) perr(p, "unterminated regular expression");
        uint8_t c = p->src[p->pos];
        if (c == '\\') { p->pos += 2; continue; }
        if (c == '[') in_class = 1;
        else if (c == ']') in_class = 0;
        else if (c == '/' && !in_class) { p->pos++; break; }
        else if (c == '\n' || c == '\r') perr(p, "unterminated regular expression");
        p->pos++;
    }
    int flags = 0;
    while (p->pos < p->len && is_id_part((uint8_t)p->src[p->pos])) {
        char c = p->src[p->pos];
        int bit;
        switch (c) {
        case 'g': bit = 1; break;
        case 'i': bit = 2; break;
        case 'm': bit = 4; break;
        case 's': bit = 8; break;
        case 'u': bit = 16; break;
        case 'y': bit = 32; break;
        case 'd': bit = 64; break;
        case 'v': bit = 128; break;
        default: perr(p, "invalid regular expression flags");
        }
        if (flags & bit) perr(p, "invalid regular expression flags");
        flags |= bit;
        p->pos++;
    }
    p->tok.type = T_REG;
    p->tok.re_src = p->src + start + 1;
    p->tok.re_len = p->pos - start - 1;
    while (p->tok.re_len > 0 && p->tok.re_src[p->tok.re_len - 1] != '/') p->tok.re_len--;
    p->tok.re_flags = flags;
    p->tok.pos = start;
}

static void next_token(Parse *p) {
    int nl = 0;
    for (;;) {
        if (p->pos >= p->len) { p->tok.type = T_EOF_; p->tok.pos = p->len; p->tok.nl = nl; return; }
        uint8_t c = p->src[p->pos];
        if (c == ' ' || c == '\t' || c == '\v' || c == '\f' || c == '\r') { p->pos++; continue; }
        if (c == '\n') { nl = 1; p->pos++; continue; }
        if (c == '/' && p->pos + 1 < p->len && p->src[p->pos + 1] == '/') {
            while (p->pos < p->len && p->src[p->pos] != '\n') p->pos++;
            continue;
        }
        if (c == '/' && p->pos + 1 < p->len && p->src[p->pos + 1] == '*') {
            p->pos += 2;
            while (p->pos < p->len && !(p->src[p->pos] == '*' && p->pos + 1 < p->len && p->src[p->pos + 1] == '/')) { if (p->src[p->pos] == '\n') nl = 1; p->pos++; }
            if (p->pos >= p->len) perr(p, "unexpected end of comment");
            p->pos += 2;
            continue;
        }
        break;
    }
    if (c == '<' && p->pos + 3 < p->len && p->src[p->pos+1] == '!' && p->src[p->pos+2] == '-' && p->src[p->pos+3] == '-') {
        while (p->pos < p->len && p->src[p->pos] != '\n') p->pos++;
        return next_token(p);
    }
    if (c == '-' && nl && p->pos + 2 < p->len && p->src[p->pos+1] == '-' && p->src[p->pos+2] == '>') {
        while (p->pos < p->len && p->src[p->pos] != '\n') p->pos++;
        return next_token(p);
    }
    p->tok.nl = nl;
    p->tok.pos = p->pos;
    p->tok.ident_kw = 0;
    if (isdigit(c)) { scan_number(p); return; }
    if (c == '.' && p->pos + 1 < p->len && isdigit(p->src[p->pos+1])) { scan_number(p); return; }
    if (is_id_start(c)) {
        int start = p->pos;
        while (p->pos < p->len) {
            uint32_t cp; int n = js_utf8_decode((const uint8_t *)p->src + p->pos, p->len - p->pos, &cp);
            if (n < 0) break;
            if (!is_id_part(cp)) break;
            p->pos += n;
        }
        int l = p->pos - start;
        int kw = kw_lookup(p->src + start, l);
        p->tok.type = kw ? kw : T_IDENT;
        p->tok.str = js_string_n(p->src + start, l);
        p->tok.ident_kw = kw ? 1 : 0;
        if (kw) p->tok.ident_kw = 1;
        return;
    }
    if (c == '"' || c == '\'') { scan_string(p, c); return; }
    if (c == '`') { scan_template(p); return; }
    if (c == '/' && regex_allowed(p)) { scan_regex(p); return; }
    /* multi-char operators */
    int t = 0;
    switch (c) {
    case '*': if (p->pos+1 < p->len && p->src[p->pos+1] == '*') { if (p->pos+2 < p->len && p->src[p->pos+2]=='=') { t = OP_POWA; p->pos += 3; } else { t = OP_POW; p->pos += 2; } } else if (p->pos+1 < p->len && p->src[p->pos+1]=='=') { t = OP_MULA; p->pos += 2; } else t = '*'; break;
    case '+': if (p->pos+1<p->len && p->src[p->pos+1]=='+') { t = OP_INCR; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_ADDA; p->pos += 2; } else t = '+'; break;
    case '-': if (p->pos+1<p->len && p->src[p->pos+1]=='-') { t = OP_DECR; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_SUBA; p->pos += 2; } else t = '-'; break;
    case '/': if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_DIVA; p->pos += 2; } else t = '/'; break;
    case '%': if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_MODA; p->pos += 2; } else t = '%'; break;
    case '&': if (p->pos+1<p->len && p->src[p->pos+1]=='&') { t = OP_ANDAND; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_ANDA; p->pos += 2; } else t = '&'; break;
    case '|': if (p->pos+1<p->len && p->src[p->pos+1]=='|') { t = OP_OROR; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_ORA; p->pos += 2; } else t = '|'; break;
    case '^': if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_XORA; p->pos += 2; } else t = '^'; break;
    case '=': if (p->pos+2<p->len && p->src[p->pos+1]=='=' && p->src[p->pos+2]=='=') { t = OP_STREQ; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_EQ; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='>') { t = OP_ARROW; p->pos += 2; }
              else t = '='; break;
    case '!': if (p->pos+2<p->len && p->src[p->pos+1]=='=' && p->src[p->pos+2]=='=') { t = OP_STRNE; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_NE; p->pos += 2; }
              else t = '!'; break;
    case '<': if (p->pos+2<p->len && p->src[p->pos+1]=='<' && p->src[p->pos+2]=='=') { t = OP_SHLA; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='<') { t = OP_SHL; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_LE; p->pos += 2; }
              else t = '<'; break;
    case '>': if (p->pos+3<p->len && p->src[p->pos+1]=='>' && p->src[p->pos+2]=='>' && p->src[p->pos+3]=='=') { t = OP_USHRA; p->pos += 4; }
              else if (p->pos+2<p->len && p->src[p->pos+1]=='>' && p->src[p->pos+2]=='>') { t = OP_USHR; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='>' && p->src[p->pos+2]=='=') { t = OP_SHRA; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='>') { t = OP_SHR; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_GE; p->pos += 2; }
              else t = '>'; break;
    case '?': if (p->pos+2<p->len && p->src[p->pos+1]=='?' && p->src[p->pos+2]=='=') { t = OP_NULLISH; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='?') { t = OP_NULLISH; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='.') { t = OP_QDOT; p->pos += 2; }
              else t = '?'; break;
    case '.': if (p->pos+2<p->len && p->src[p->pos+1]=='.' && p->src[p->pos+2]=='.') { t = OP_ELLIPSIS; p->pos += 3; }
              else t = '.'; break;
    default: t = c; p->pos++; break;
    }
    p->tok.type = t;
}
CEOF
echo ok

function.arguments:
{"command": "cat > src/parse.c <<'CEOF'
#include "internal.h"
#include <ctype.h>
#include <stdarg.h>

/* token types */
#define T_EOF_ 0
#define T_NUM 1
#define T_STR 2
#define T_BIG 3
#define T_REG 4
#define T_IDENT 5
#define T_TMPL 6      /* template literal (no substitution) */
#define T_TMPLSTART 7 /* `...${ */
#define T_TMPLMID 8   /* }...${ */
#define T_TMPLEND 9   /* }...` */
#define KW 300
enum {
    K_VAR = KW, K_LET, K_CONST, K_FUNCTION, K_IF, K_ELSE, K_DO, K_WHILE, K_FOR,
    K_BREAK, K_CONTINUE, K_RETURN, K_THROW, K_TRY, K_CATCH, K_FINALLY, K_SWITCH,
    K_CASE, K_DEFAULT, K_CLASS, K_EXTENDS, K_SUPER, K_NEW, K_DELETE, K_TYPEOF,
    K_VOID, K_IN, K_INSTANCEOF, K_THIS, K_NULL, K_TRUE, K_FALSE, K_YIELD, K_AWAIT,
    K_ASYNC, K_IMPORT, K_EXPORT, K_FROM, K_AS, K_OF, K_STATIC, K_GET, K_SET,
    K_DEBUGGER, K_WITH, K_TARGET, K_ENUM
};
/* operators >= 256 */
enum {
    OP_POW = 256, OP_POWA, OP_ADDA, OP_SUBA, OP_MULA, OP_DIVA, OP_MODA, OP_ANDA,
    OP_ORA, OP_XORA, OP_SHLA, OP_SHRA, OP_USHRA, OP_EQ, OP_STREQ, OP_NE, OP_STRNE,
    OP_LE, OP_GE, OP_ANDAND, OP_OROR, OP_NULLISH, OP_INCR, OP_DECR, OP_SHL, OP_SHR,
    OP_USHR, OP_ARROW, OP_ELLIPSIS, OP_QDOT
};

typedef struct {
    int type;
    JSValue str;
    double num;
    int is_big;
    int pos;
    int nl;
    int re_flags;
    const char *re_src;
    int re_len;
    int ident_kw;
} Tok;

typedef struct {
    const char *src;
    int len, pos;
    Tok tok;
    Tok save;
    int has_save;
    int in_module, strict;
    int allow_in, allow_yield, allow_await, allow_default;
    SrcInfo *si;
    const char *filename;
    int depth;
    int no_in;
    int repl_wrap;
} Parse;

static void perr(Parse *p, const char *fmt, ...);

/* ------------------------------- lexer ----------------------------------- */
static int is_id_start(uint32_t c) {
    return c == '$' || c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
        (c >= 0x80 && !(c >= 0xd800 && c < 0xe000)) || c == 0xa2 || c == 0xb5;
}
static int is_id_part(uint32_t c) { return is_id_start(c) || (c >= '0' && c <= '9'); }

static const struct { const char *s; int t; } keywords[] = {
    { "var", K_VAR }, { "let", K_LET }, { "const", K_CONST }, { "function", K_FUNCTION },
    { "if", K_IF }, { "else", K_ELSE }, { "do", K_DO }, { "while", K_WHILE }, { "for", K_FOR },
    { "break", K_BREAK }, { "continue", K_CONTINUE }, { "return", K_RETURN },
    { "throw", K_THROW }, { "try", K_TRY }, { "catch", K_CATCH }, { "finally", K_FINALLY },
    { "switch", K_SWITCH }, { "case", K_CASE }, { "default", K_DEFAULT }, { "class", K_CLASS },
    { "extends", K_EXTENDS }, { "super", K_SUPER }, { "new", K_NEW }, { "delete", K_DELETE },
    { "typeof", K_TYPEOF }, { "void", K_VOID }, { "in", K_IN }, { "instanceof", K_INSTANCEOF },
    { "this", K_THIS }, { "null", K_NULL }, { "true", K_TRUE }, { "false", K_FALSE },
    { "yield", K_YIELD }, { "await", K_AWAIT }, { "async", K_ASYNC }, { "import", K_IMPORT },
    { "export", K_EXPORT }, { "from", K_FROM }, { "as", K_AS }, { "of", K_OF },
    { "static", K_STATIC }, { "get", K_GET }, { "set", K_SET }, { "debugger", K_DEBUGGER },
    { "with", K_WITH }, { "enum", K_ENUM },
    { NULL, 0 }
};
static int kw_lookup(const char *s, int n) {
    char buf[32];
    if (n > 31) return 0;
    memcpy(buf, s, n); buf[n] = 0;
    for (int i = 0; keywords[i].s; i++)
        if (strcmp(keywords[i].s, buf) == 0) return keywords[i].t;
    return 0;
}

static void scan_string(Parse *p, int quote) {
    Buf b; buf_init(&b, 32);
    int start = p->pos;
    p->pos++; /* skip quote */
    int units = 0;
    uint16_t u16[1024];
    for (;;) {
        if (p->pos >= p->len) perr(p, "unexpected end of string");
        uint8_t c = p->src[p->pos];
        if (c == quote) { p->pos++; break; }
        if (c == '\n' || c == '\r') perr(p, "unexpected end of string");
        if (c != '\\') {
            uint32_t cp; int n = js_utf8_decode((const uint8_t *)p->src + p->pos, p->len - p->pos, &cp);
            if (n < 0) { cp = c; n = 1; }
            if (cp >= 0x10000) { u16[units++] = (uint16_t)(0xd800 + ((cp - 0x10000) >> 10)); u16[units++] = (uint16_t)(0xdc00 + ((cp - 0x10000) & 0x3ff)); }
            else u16[units++] = (uint16_t)cp;
            if (units > 1000) { for (int i = 0; i < units; i++) { uint8_t t[4]; int l = js_utf8_encode(t, u16[i]); buf_put(&b, t, l); } units = 0; }
            p->pos += n;
            continue;
        }
        p->pos++;
        if (p->pos >= p->len) perr(p, "unexpected end of string");
        uint8_t e = p->src[p->pos++];
        uint32_t cp = 0;
        switch (e) {
        case 'n': cp = '\n'; break;
        case 'r': cp = '\r'; break;
        case 't': cp = '\t'; break;
        case 'b': cp = '\b'; break;
        case 'v': cp = 0x0b; break;
        case 'f': cp = 0x0c; break;
        case '0': if (p->pos < p->len && p->src[p->pos] >= '0' && p->src[p->pos] <= '9') { p->pos--; cp = 0; } else cp = 0; break;
        case '\n': while (p->pos < p->len && (p->src[p->pos] == '\r')) p->pos++; continue;
        case '\r': continue;
        case 'x': {
            if (p->pos + 2 > p->len) perr(p, "invalid escape sequence");
            int v = 0;
            for (int i = 0; i < 2; i++) { uint8_t c2 = p->src[p->pos + i]; int d = isxdigit(c2) ? (isdigit(c2) ? c2 - '0' : tolower(c2) - 'a' + 10) : -1; if (d < 0) perr(p, "invalid escape sequence"); v = v * 16 + d; }
            p->pos += 2; cp = v; break;
        }
        case 'u': {
            if (p->pos < p->len && p->src[p->pos] == '{') {
                p->pos++;
                int v = 0, any = 0;
                while (p->pos < p->len && p->src[p->pos] != '}') {
                    uint8_t c2 = p->src[p->pos];
                    int d = isxdigit(c2) ? (isdigit(c2) ? c2 - '0' : tolower(c2) - 'a' + 10) : -1;
                    if (d < 0) perr(p, "invalid unicode escape");
                    v = v * 16 + d; if (v > 0x10ffff) perr(p, "unicode escape out of range");
                    any = 1; p->pos++;
                }
                if (!any) perr(p, "invalid unicode escape");
                p->pos++;
                cp = v;
            } else {
                if (p->pos + 4 > p->len) perr(p, "invalid unicode escape");
                int v = 0;
                for (int i = 0; i < 4; i++) { uint8_t c2 = p->src[p->pos + i]; int d = isxdigit(c2) ? (isdigit(c2) ? c2 - '0' : tolower(c2) - 'a' + 10) : -1; if (d < 0) perr(p, "invalid unicode escape"); v = v * 16 + d; }
                p->pos += 4; cp = v;
            }
            break;
        }
        default:
            if (e >= '0' && e <= '7') {
                int v = e - '0';
                for (int i = 0; i < 2 && p->pos < p->len && p->src[p->pos] >= '0' && p->src[p->pos] <= '7'; i++) { v = v * 8 + (p->src[p->pos] - '0'); p->pos++; }
                if (p->strict && v != 0) perr(p, "octal escape sequences are not allowed in strict mode");
                cp = v;
            } else if (e >= 0x80) {
                uint32_t c2; int n = js_utf8_decode((const uint8_t *)p->src + p->pos - 1, p->len - p->pos + 1, &c2);
                if (n < 0) cp = e; else { p->pos += n - 1; cp = c2; }
            } else cp = e;
            break;
        }
        if (cp >= 0x10000) { u16[units++] = (uint16_t)(0xd800 + ((cp - 0x10000) >> 10)); u16[units++] = (uint16_t)(0xdc00 + ((cp - 0x10000) & 0x3ff)); }
        else u16[units++] = (uint16_t)cp;
        if (units > 1000) { for (int i = 0; i < units; i++) { uint8_t t[4]; int l = js_utf8_encode(t, u16[i]); buf_put(&b, t, l); } units = 0; }
    }
    for (int i = 0; i < units; i++) { uint8_t t[4]; int l = js_utf8_encode(t, u16[i]); buf_put(&b, t, l); }
    (void)start;
    p->tok.type = T_STR;
    int bl = b.len;
    /* count code units */
    int units2 = 0, i = 0;
    while (i < bl) { uint32_t cp; int n = js_utf8_decode(b.b + i, bl - i, &cp); if (n < 0) { n = 1; cp = b.b[i]; } units2 += cp >= 0x10000 ? 2 : 1; i += n; }
    p->tok.str = js_atom_buf(b.b, bl, units2);
}

static int scan_number(Parse *p) {
    int start = p->pos;
    double val = 0;
    int base = 10;
    int is_big = 0;
    if (p->pos + 1 < p->len && p->src[p->pos] == '0' &&
        (p->src[p->pos + 1] == 'x' || p->src[p->pos + 1] == 'X')) { base = 16; p->pos += 2; }
    else if (p->pos + 1 < p->len && p->src[p->pos] == '0' &&
        (p->src[p->pos + 1] == 'b' || p->src[p->pos + 1] == 'B')) { base = 2; p->pos += 2; }
    else if (p->pos + 1 < p->len && p->src[p->pos] == '0' &&
        (p->src[p->pos + 1] == 'o' || p->src[p->pos + 1] == 'O')) { base = 8; p->pos += 2; }
    else if (p->pos + 1 < p->len && p->src[p->pos] == '0' &&
        p->src[p->pos + 1] >= '0' && p->src[p->pos + 1] <= '9') { base = 8; p->pos++; }
    if (base != 10) {
        uint64_t hi = 0; int exp2 = 0, nd = 0;
        int big = 0;
        for (;;) {
            uint8_t c = p->pos < p->len ? p->src[p->pos] : 0;
            int d;
            if (c == '_') { p->pos++; continue; }
            if (c == 'n') { if (!nd) perr(p, "invalid number literal"); big = 1; p->pos++; break; }
            if (c >= '0' && c <= '9') d = c - '0';
            else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
            else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
            else break;
            if (d >= base) perr(p, "invalid number literal");
            if (!big && hi > (0x7fffffffffffffffULL - d) / (uint64_t)base) big = 1;
            if (!big) { hi = hi * base + d; nd++; }
            p->pos++;
        }
        if (!nd) perr(p, "invalid number literal");
        if (big) {
            /* build the digit string and parse as bigint */
            char tmp[2048]; int tl = 0;
            tmp[tl++] = '0';
            if (base == 16) tmp[tl++] = 'x'; else if (base == 8) tmp[tl++] = 'o'; else tmp[tl++] = 'b';
            for (int i = start + 2; i < p->pos; i++) if (p->src[i] != 'n' && p->src[i] != '_') tmp[tl++] = p->src[i];
            tmp[tl] = 0;
            int ok;
            JSBigInt *bb = bi_from_string(str_val(js_string_n(tmp, tl)), base == 16 ? 16 : base == 8 ? 8 : 2, &ok);
            if (!ok) perr(p, "invalid number literal");
            JSValue v; v.u.p = bb; v.tag = T_BIG;
            p->tok.type = T_BIG; p->tok.str = v; p->tok.pos = start;
            return 1;
        }
        val = ldexp((double)hi, exp2);
        p->tok.type = T_NUM; p->tok.num = val; p->tok.pos = start;
        return 1;
    }
    /* decimal */
    int hasdot = 0, hasexp = 0;
    int dstart = p->pos;
    for (;;) {
        uint8_t c = p->pos < p->len ? p->src[p->pos] : 0;
        if (c == '_') { p->pos++; continue; }
        if (c >= '0' && c <= '9') { p->pos++; continue; }
        if (c == '.' && !hasdot && !hasexp) { hasdot = 1; p->pos++; continue; }
        if ((c == 'e' || c == 'E') && !hasexp) {
            hasexp = 1; p->pos++;
            if (p->pos < p->len && (p->src[p->pos] == '+' || p->src[p->pos] == '-')) p->pos++;
            if (p->pos >= p->len || !isdigit((unsigned char)p->src[p->pos])) perr(p, "invalid number literal");
            continue;
        }
        if (c == 'n') {
            if (hasdot || hasexp) perr(p, "invalid number literal");
            if (p->pos == dstart) perr(p, "invalid number literal");
            is_big = 1; p->pos++; break;
        }
        break;
    }
    if (p->pos == dstart) perr(p, "invalid number literal");
    if (is_big) {
        char tmp[4096]; int tl = 0;
        for (int i = dstart; i < p->pos; i++) if (p->src[i] != '_') tmp[tl++] = p->src[i];
        tmp[tl] = 0;
        int ok;
        JSBigInt *bb = bi_from_string(str_val(js_string_n(tmp, tl)), 10, &ok);
        if (!ok) perr(p, "invalid number literal");
        JSValue v; v.u.p = bb; v.tag = T_BIG;
        p->tok.type = T_BIG; p->tok.str = v; p->tok.pos = start;
        return 1;
    }
    char tmp[512];
    int tl = p->pos - dstart;
    if (tl > 500) tl = 500;
    memcpy(tmp, p->src + dstart, tl);
    tmp[tl] = 0;
    for (int i = 0; i < tl; i++) if (tmp[i] == '_') { memmove(tmp + i, tmp + i + 1, tl - i); tl--; i--; }
    tmp[tl] = 0;
    val = strtod(tmp, NULL);
    /* check that the token ends properly */
    uint8_t c = p->pos < p->len ? p->src[p->pos] : 0;
    if (is_id_start(c)) perr(p, "invalid number literal");
    p->tok.type = T_NUM; p->tok.num = val; p->tok.pos = start;
    return 1;
}

static int regex_allowed(Parse *p) {
    /* determine if a '/' starts a regex based on the previous token */
    int t = p->tok.type;
    if (t == T_NUM || t == T_STR || t == T_BIG || t == T_IDENT || t == T_TMPL || t == T_TMPLEND) return 0;
    if (t == ')' || t == ']' || t == '}') return 0;
    if (t == K_THIS || t == K_TRUE || t == K_FALSE || t == K_NULL) return 0;
    if (t == K_SUPER) return 0;
    return 1;
}

static void scan_regex(Parse *p) {
    int start = p->pos;
    p->pos++; /* skip / */
    int in_class = 0;
    for (;;) {
        if (p->pos >= p->len) perr(p, "unterminated regular expression");
        uint8_t c = p->src[p->pos];
        if (c == '\\') { p->pos += 2; continue; }
        if (c == '[') in_class = 1;
        else if (c == ']') in_class = 0;
        else if (c == '/' && !in_class) { p->pos++; break; }
        else if (c == '\n' || c == '\r') perr(p, "unterminated regular expression");
        p->pos++;
    }
    int flags = 0;
    while (p->pos < p->len && is_id_part((uint8_t)p->src[p->pos])) {
        char c = p->src[p->pos];
        int bit;
        switch (c) {
        case 'g': bit = 1; break;
        case 'i': bit = 2; break;
        case 'm': bit = 4; break;
        case 's': bit = 8; break;
        case 'u': bit = 16; break;
        case 'y': bit = 32; break;
        case 'd': bit = 64; break;
        case 'v': bit = 128; break;
        default: perr(p, "invalid regular expression flags");
        }
        if (flags & bit) perr(p, "invalid regular expression flags");
        flags |= bit;
        p->pos++;
    }
    p->tok.type = T_REG;
    p->tok.re_src = p->src + start + 1;
    p->tok.re_len = p->pos - start - 1;
    while (p->tok.re_len > 0 && p->tok.re_src[p->tok.re_len - 1] != '/') p->tok.re_len--;
    p->tok.re_flags = flags;
    p->tok.pos = start;
}

static void next_token(Parse *p) {
    int nl = 0;
    for (;;) {
        if (p->pos >= p->len) { p->tok.type = T_EOF_; p->tok.pos = p->len; p->tok.nl = nl; return; }
        uint8_t c = p->src[p->pos];
        if (c == ' ' || c == '\t' || c == '\v' || c == '\f' || c == '\r') { p->pos++; continue; }
        if (c == '\n') { nl = 1; p->pos++; continue; }
        if (c == '/' && p->pos + 1 < p->len && p->src[p->pos + 1] == '/') {
            while (p->pos < p->len && p->src[p->pos] != '\n') p->pos++;
            continue;
        }
        if (c == '/' && p->pos + 1 < p->len && p->src[p->pos + 1] == '*') {
            p->pos += 2;
            while (p->pos < p->len && !(p->src[p->pos] == '*' && p->pos + 1 < p->len && p->src[p->pos + 1] == '/')) { if (p->src[p->pos] == '\n') nl = 1; p->pos++; }
            if (p->pos >= p->len) perr(p, "unexpected end of comment");
            p->pos += 2;
            continue;
        }
        break;
    }
    if (c == '<' && p->pos + 3 < p->len && p->src[p->pos+1] == '!' && p->src[p->pos+2] == '-' && p->src[p->pos+3] == '-') {
        while (p->pos < p->len && p->src[p->pos] != '\n') p->pos++;
        return next_token(p);
    }
    if (c == '-' && nl && p->pos + 2 < p->len && p->src[p->pos+1] == '-' && p->src[p->pos+2] == '>') {
        while (p->pos < p->len && p->src[p->pos] != '\n') p->pos++;
        return next_token(p);
    }
    p->tok.nl = nl;
    p->tok.pos = p->pos;
    p->tok.ident_kw = 0;
    if (isdigit(c)) { scan_number(p); return; }
    if (c == '.' && p->pos + 1 < p->len && isdigit(p->src[p->pos+1])) { scan_number(p); return; }
    if (is_id_start(c)) {
        int start = p->pos;
        while (p->pos < p->len) {
            uint32_t cp; int n = js_utf8_decode((const uint8_t *)p->src + p->pos, p->len - p->pos, &cp);
            if (n < 0) break;
            if (!is_id_part(cp)) break;
            p->pos += n;
        }
        int l = p->pos - start;
        int kw = kw_lookup(p->src + start, l);
        p->tok.type = kw ? kw : T_IDENT;
        p->tok.str = js_string_n(p->src + start, l);
        p->tok.ident_kw = kw ? 1 : 0;
        if (kw) p->tok.ident_kw = 1;
        return;
    }
    if (c == '"' || c == '\'') { scan_string(p, c); return; }
    if (c == '`') { scan_template(p); return; }
    if (c == '/' && regex_allowed(p)) { scan_regex(p); return; }
    /* multi-char operators */
    int t = 0;
    switch (c) {
    case '*': if (p->pos+1 < p->len && p->src[p->pos+1] == '*') { if (p->pos+2 < p->len && p->src[p->pos+2]=='=') { t = OP_POWA; p->pos += 3; } else { t = OP_POW; p->pos += 2; } } else if (p->pos+1 < p->len && p->src[p->pos+1]=='=') { t = OP_MULA; p->pos += 2; } else t = '*'; break;
    case '+': if (p->pos+1<p->len && p->src[p->pos+1]=='+') { t = OP_INCR; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_ADDA; p->pos += 2; } else t = '+'; break;
    case '-': if (p->pos+1<p->len && p->src[p->pos+1]=='-') { t = OP_DECR; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_SUBA; p->pos += 2; } else t = '-'; break;
    case '/': if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_DIVA; p->pos += 2; } else t = '/'; break;
    case '%': if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_MODA; p->pos += 2; } else t = '%'; break;
    case '&': if (p->pos+1<p->len && p->src[p->pos+1]=='&') { t = OP_ANDAND; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_ANDA; p->pos += 2; } else t = '&'; break;
    case '|': if (p->pos+1<p->len && p->src[p->pos+1]=='|') { t = OP_OROR; p->pos += 2; } else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_ORA; p->pos += 2; } else t = '|'; break;
    case '^': if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_XORA; p->pos += 2; } else t = '^'; break;
    case '=': if (p->pos+2<p->len && p->src[p->pos+1]=='=' && p->src[p->pos+2]=='=') { t = OP_STREQ; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_EQ; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='>') { t = OP_ARROW; p->pos += 2; }
              else t = '='; break;
    case '!': if (p->pos+2<p->len && p->src[p->pos+1]=='=' && p->src[p->pos+2]=='=') { t = OP_STRNE; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_NE; p->pos += 2; }
              else t = '!'; break;
    case '<': if (p->pos+2<p->len && p->src[p->pos+1]=='<' && p->src[p->pos+2]=='=') { t = OP_SHLA; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='<') { t = OP_SHL; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_LE; p->pos += 2; }
              else t = '<'; break;
    case '>': if (p->pos+3<p->len && p->src[p->pos+1]=='>' && p->src[p->pos+2]=='>' && p->src[p->pos+3]=='=') { t = OP_USHRA; p->pos += 4; }
              else if (p->pos+2<p->len && p->src[p->pos+1]=='>' && p->src[p->pos+2]=='>') { t = OP_USHR; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='>' && p->src[p->pos+2]=='=') { t = OP_SHRA; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='>') { t = OP_SHR; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='=') { t = OP_GE; p->pos += 2; }
              else t = '>'; break;
    case '?': if (p->pos+2<p->len && p->src[p->pos+1]=='?' && p->src[p->pos+2]=='=') { t = OP_NULLISH; p->pos += 3; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='?') { t = OP_NULLISH; p->pos += 2; }
              else if (p->pos+1<p->len && p->src[p->pos+1]=='.') { t = OP_QDOT; p->pos += 2; }
              else t = '?'; break;
    case '.': if (p->pos+2<p->len && p->src[p->pos+1]=='.' && p->src[p->pos+2]=='.') { t = OP_ELLIPSIS; p->pos += 3; }
              else t = '.'; break;
    default: t = c; p->pos++; break;
    }
    p->tok.type = t;
}
CEOF
echo ok"}

