static jmp_buf tent_jb;
static int tent_active;

static void perr(Parse *p, const char *fmt, ...) {
    char buf[512];
    va_list ap; va_start(ap, fmt);
    vsnprintf(buf, sizeof buf, fmt, ap);
    va_end(ap);
    if (tent_active) longjmp(tent_jb, 1);
    int pos = p->tok.pos;
    js_throw_error(ERR_SYNTAX, "%s", buf);
    (void)pos;
}
static void perr_at(Parse *p, int pos, const char *fmt, ...) {
    char buf[512];
    va_list ap; va_start(ap, fmt);
    vsnprintf(buf, sizeof buf, fmt, ap);
    va_end(ap);
    if (tent_active) longjmp(tent_jb, 1);
    (void)pos;
    js_throw_error(ERR_SYNTAX, "%s", buf);
}

static Ast *mk(Parse *p, int kind) {
    Ast *n = js_malloc(sizeof(Ast));
    n->kind = kind; n->pos = p->tok.pos; n->flags = 0; n->nk = 0; n->kcap = 0;
    n->k = NULL; n->v = js_undef(); n->num = 0; n->i = 0; n->n2 = 0;
    return n;
}
static void addk(Ast *n, Ast *k) {
    if (n->nk == n->kcap) {
        int nc = n->kcap ? n->kcap * 2 : 4;
        Ast **na = js_malloc(nc * sizeof(void *));
        if (n->nk) memcpy(na, n->k, n->nk * sizeof(void *));
        n->k = na; n->kcap = nc;
    }
    n->k[n->nk++] = k;
}
static void addkv(Ast *n, Ast *k, int idx) { (void)idx; addk(n, k); }

typedef struct { int pos; Tok tok; } PState;
static PState pstate(Parse *p) { PState s; s.pos = p->pos; s.tok = p->tok; return s; }
static void pload(Parse *p, PState s) { p->pos = s.pos; p->tok = s.tok; }
static void pnext(Parse *p) { next_token(p); }

static int is(Parse *p, int t) { return p->tok.type == t; }
static void accept(Parse *p, int t) { if (!is(p, t)) perr(p, "unexpected token"); pnext(p); }
static int eat(Parse *p, int t) { if (is(p, t)) { pnext(p); return 1; } return 0; }
static void expect(Parse *p, int t) {
    if (!is(p, t)) {
        char buf[8];
        if (t == T_IDENT) strcpy(buf, "identifier");
        else if (t < 256) { buf[0] = (char)t; buf[1] = 0; }
        else strcpy(buf, "token");
        perr(p, "expecting '%s'", buf);
    }
    pnext(p);
}
static const char *tok_str(Parse *p) {
    static char buf[64];
    switch (p->tok.type) {
    case T_EOF_: return "";
    case T_NUM: snprintf(buf, sizeof buf, "%g", p->tok.num); return buf;
    case T_STR: case T_IDENT: return (const char *)str_val(p->tok.str)->buf;
    case T_BIG: return "bigint";
    case T_REG: return "regular expression literal";
    default:
        if (p->tok.type >= KW) {
            for (int i = 0; keywords[i].s; i++) if (keywords[i].t == p->tok.type) return keywords[i].s;
            return "keyword";
        }
        if (p->tok.type >= 256) {
            switch (p->tok.type) {
            case OP_POW: return "**"; case OP_POWA: return "**="; case OP_ADDA: return "+=";
            case OP_SUBA: return "-="; case OP_MULA: return "*="; case OP_DIVA: return "/=";
            case OP_MODA: return "%="; case OP_ANDA: return "&="; case OP_ORA: return "|=";
            case OP_XORA: return "^="; case OP_SHLA: return "<<="; case OP_SHRA: return ">>=";
            case OP_USHRA: return ">>>="; case OP_EQ: return "=="; case OP_STREQ: return "===";
            case OP_NE: return "!="; case OP_STRNE: return "!=="; case OP_LE: return "<=";
            case OP_GE: return ">="; case OP_ANDAND: return "&&"; case OP_OROR: return "||";
            case OP_NULLISH: return "??"; case OP_INCR: return "++"; case OP_DECR: return "--";
            case OP_SHL: return "<<"; case OP_SHR: return ">>"; case OP_USHR: return ">>>";
            case OP_ARROW: return "=>"; case OP_ELLIPSIS: return "..."; case OP_QDOT: return "?.";
            }
            return "token";
        }
        buf[0] = (char)p->tok.type; buf[1] = 0;
        return buf;
    }
}

/* --------------------------- template scanning ---------------------------- */
static void scan_template(Parse *p) {
    int start = p->pos;
    p->pos++; /* skip ` */
    Buf b; buf_init(&b, 32);
    int type = T_TMPL;
    int units = 0;
    uint16_t u16[1024];
#define FLUSH() do { for (int i = 0; i < units; i++) { uint8_t t[4]; int l = js_utf8_encode(t, u16[i]); buf_put(&b, t, l); } units = 0; } while (0)
    for (;;) {
        if (p->pos >= p->len) perr(p, "unexpected end of string");
        uint8_t c = p->src[p->pos];
        if (c == '`') { p->pos++; break; }
        if (c == '\\' && p->pos + 1 < p->len) {
            p->pos++;
            uint8_t e = p->src[p->pos++];
            uint32_t cp = 0;
            switch (e) {
            case 'n': cp = '\n'; break; case 'r': cp = '\r'; break; case 't': cp = '\t'; break;
            case 'b': cp = '\b'; break; case 'v': cp = 0x0b; break; case 'f': cp = 0x0c; break;
            case '0': cp = 0; break;
            case 'x': { int v = 0; for (int i = 0; i < 2; i++) { uint8_t c2 = p->src[p->pos + i]; int d = isxdigit(c2) ? (isdigit(c2) ? c2 - '0' : tolower(c2) - 'a' + 10) : -1; if (d < 0) perr(p, "invalid escape sequence"); v = v * 16 + d; } p->pos += 2; cp = v; break; }
            case 'u': {
                if (p->src[p->pos] == '{') { p->pos++; int v = 0; while (p->src[p->pos] != '}') { uint8_t c2 = p->src[p->pos]; int d = isxdigit(c2) ? (isdigit(c2) ? c2 - '0' : tolower(c2) - 'a' + 10) : -1; if (d < 0) perr(p, "invalid unicode escape"); v = v * 16 + d; p->pos++; } p->pos++; cp = v; }
                else { int v = 0; for (int i = 0; i < 4; i++) { uint8_t c2 = p->src[p->pos + i]; int d = isxdigit(c2) ? (isdigit(c2) ? c2 - '0' : tolower(c2) - 'a' + 10) : -1; if (d < 0) perr(p, "invalid unicode escape"); v = v * 16 + d; } p->pos += 4; cp = v; }
                break;
            }
            case '\n': case '\r': continue;
            default: cp = e; break;
            }
            if (cp >= 0x10000) { u16[units++] = (uint16_t)(0xd800 + ((cp - 0x10000) >> 10)); u16[units++] = (uint16_t)(0xdc00 + ((cp - 0x10000) & 0x3ff)); }
            else u16[units++] = (uint16_t)cp;
            if (units > 1000) FLUSH();
            continue;
        }
        if (c == '$' && p->pos + 1 < p->len && p->src[p->pos + 1] == '{') {
            p->pos += 2;
            type = T_TMPLSTART;
            break;
        }
        if (c == '\n' || c == '\r') { u16[units++] = (uint16_t)c; if (c == '\r' && p->pos + 1 < p->len && p->src[p->pos+1] == '\n') p->pos++; p->pos++; continue; }
        uint32_t cp; int n = js_utf8_decode((const uint8_t *)p->src + p->pos, p->len - p->pos, &cp);
        if (n < 0) { cp = c; n = 1; }
        if (cp >= 0x10000) { u16[units++] = (uint16_t)(0xd800 + ((cp - 0x10000) >> 10)); u16[units++] = (uint16_t)(0xdc00 + ((cp - 0x10000) & 0x3ff)); }
        else u16[units++] = (uint16_t)cp;
        p->pos += n;
        if (units > 1000) FLUSH();
    }
    FLUSH();
    p->tok.type = type;
    int bl = b.len;
    int units2 = 0, i = 0;
    while (i < bl) { uint32_t cp; int n = js_utf8_decode(b.b + i, bl - i, &cp); if (n < 0) { n = 1; cp = b.b[i]; } units2 += cp >= 0x10000 ? 2 : 1; i += n; }
    p->tok.str = js_atom_buf(b.b, bl, units2);
    p->tok.re_src = p->src + start;
    p->tok.re_len = p->pos - start;
}
CEOF
echo ok"}

