static Ast *parse_property_name(Parse *p, int *is_computed) {
    *is_computed = 0;
    if (is(p, '[')) { pnext(p); *is_computed = 1; Ast *e = parse_assign_expr(p); expect(p, ']'); return e; }
    if (is(p, T_STR)) { Ast *n = mk(p, N_STR); n->v = p->tok.str; pnext(p); return n; }
    if (is(p, T_NUM)) { Ast *n = mk(p, N_NUM); n->num = p->tok.num; n->v = js_num_to_string(p->tok.num); pnext(p); return n; }
    if (is(p, T_BIG)) { Ast *n = mk(p, N_BIG); n->v = p->tok.str; pnext(p); return n; }
    if (is(p, T_IDENT) || (p->tok.type >= KW && p->tok.type != K_IN && p->tok.type != K_INSTANCEOF)) {
        Ast *n = mk(p, N_STR); n->v = ident_name(p); pnext(p); return n;
    }
    perr(p, "property name expected");
    return NULL;
}

static Ast *parse_func_body(Parse *p, int is_gen, int is_async) {
    Ast *body = mk(p, N_BLOCK);
    int oy = p->allow_yield, oa = p->allow_await;
    p->allow_yield = is_gen;
    p->allow_await = is_async;
    expect(p, '{');
    Ast *st = parse_statements(p);
    addk(body, st);
    expect(p, '}');
    p->allow_yield = oy; p->allow_await = oa;
    return body;
}

static Ast *parse_formal_params(Parse *p) {
    expect(p, '(');
    Ast *l = parse_binding_list(p, ')');
    expect(p, ')');
    return l;
}

static Ast *parse_func_expr(Parse *p, int is_async, int is_gen) {
    if (eat(p, '*')) is_gen = 1;
    Ast *n = mk(p, N_FUNC);
    n->flags = (is_gen ? F_GEN : 0) | (is_async ? F_ASYNC : 0);
    JSValue name = js_undef();
    if (is(p, T_IDENT) || is_simple_ident(p)) { name = ident_name(p); pnext(p); }
    n->v = name;
    Ast *params = parse_formal_params(p);
    Ast *body = parse_func_body(p, is_gen, is_async);
    addk(n, params);
    addk(n, body);
    return n;
}

static Ast *parse_method(Parse *p, int flags) {
    int is_gen = 0, is_async = 0, kind = 0;
    if (eat(p, '*')) is_gen = 1;
    else if (is(p, K_ASYNC)) {
        PState s = pstate(p);
        pnext(p);
        if (is(p, '*') || is(p, T_IDENT) || is(p, T_STR) || is(p, T_NUM) || is(p, '[')) is_async = 1;
        else pload(p, s);
    }
    int computed;
    Ast *name = parse_property_name(p, &computed);
    Ast *n;
    if (is(p, '(')) {
        n = mk(p, N_OBJMETHOD);
        n->flags = flags | (is_gen ? F_GEN : 0) | (is_async ? F_ASYNC : 0);
        Ast *params = parse_formal_params(p);
        Ast *body = parse_func_body(p, is_gen, is_async);
        addk(n, name);
        addk(n, params);
        addk(n, body);
        n->i = computed;
        return n;
    }
    /* field */
    n = mk(p, N_OBJPROP);
    n->flags = flags | F_FIELD;
    addk(n, name);
    if (eat(p, '=')) addk(n, parse_assign_expr(p));
    return n;
}

static Ast *parse_obj_literal(Parse *p) {
    Ast *n = mk(p, N_OBJECT);
    expect(p, '{');
    while (!is(p, '}') && !is(p, T_EOF_)) {
        if (eat(p, ',')) continue;
        if (is(p, OP_ELLIPSIS)) {
            pnext(p);
            Ast *s = mk(p, N_SPREAD);
            addk(s, parse_assign_expr(p));
            addk(n, s);
            continue;
        }
        int is_async = 0, is_gen = 0, acc = 0;
        int flags = 0;
        PState s = pstate(p);
        if (is(p, K_GET)) { pnext(p); if (is(p, '(') || is(p, '=') || is(p, ';') || is(p, ',') || is(p, '}') || is(p, ':')) { pload(p, s); } else acc = 1; }
        else if (is(p, K_SET)) { pnext(p); if (is(p, '(') || is(p, '=') || is(p, ';') || is(p, ',') || is(p, '}') || is(p, ':')) { pload(p, s); } else acc = 2; }
        else if (is(p, '*')) { pnext(p); is_gen = 1; }
        else if (is(p, K_ASYNC)) { pnext(p); if (is(p, '*') || is(p, T_IDENT) || is(p, T_STR) || is(p, T_NUM) || is(p, '[')) is_async = 1; else pload(p, s); }
        int computed;
        Ast *name = parse_property_name(p, &computed);
        if (acc == 1 || acc == 2) {
            Ast *m = mk(p, N_OBJMETHOD);
            m->flags = (acc == 1 ? F_GETTER : F_SETTER) | F_METHOD;
            addk(m, name);
            Ast *params = parse_formal_params(p);
            Ast *body = parse_func_body(p, 0, 0);
            addk(m, params); addk(m, body);
            m->i = computed;
            addk(n, m);
        } else if (is(p, '(')) {
            Ast *m = mk(p, N_OBJMETHOD);
            m->flags = F_METHOD | (is_gen ? F_GEN : 0) | (is_async ? F_ASYNC : 0);
            addk(m, name);
            Ast *params = parse_formal_params(p);
            Ast *body = parse_func_body(p, is_gen, is_async);
            addk(m, params); addk(m, body);
            m->i = computed;
            addk(n, m);
        } else {
            Ast *pr = mk(p, N_OBJPROP);
            addk(pr, name);
            if (eat(p, ':')) addk(pr, parse_assign_expr(p));
            else {
                if (name->kind != N_STR) perr(p, "unexpected token in expression: '%s'", tok_str(p));
                Ast *id = mk(p, N_IDENT); id->v = name->v; id->pos = name->pos;
                addk(pr, id);
            }
            pr->i = computed;
            addk(n, pr);
        }
        if (!eat(p, ',')) break;
    }
    expect(p, '}');
    return n;
}

static Ast *parse_class_expr(Parse *p, JSValue name) {
    Ast *n = mk(p, N_CLASS);
    n->v = name;
    if (is(p, K_EXTENDS)) {
        pnext(p);
        int oy = p->allow_yield, oa = p->allow_await;
        p->allow_yield = 0; p->allow_await = 0;
        addk(n, parse_unary(p));
        p->allow_yield = oy; p->allow_await = oa;
    } else addk(n, NULL);
    expect(p, '{');
    Ast *body = mk(p, N_ARRAY);
    while (!is(p, '}') && !is(p, T_EOF_)) {
        if (eat(p, ';')) continue;
        int flags = 0;
        if (is(p, K_STATIC)) {
            PState s = pstate(p);
            pnext(p);
            if (is(p, '(') || is(p, '=') || is(p, ';') || is(p, '}')) { pload(p, s); }
            else flags |= F_STATIC;
        }
        int acc = 0, is_gen = 0, is_async = 0;
        PState s = pstate(p);
        if (is(p, K_GET)) { pnext(p); if (is(p, '(') || is(p, '=') || is(p, ';') || is(p, '}') || is(p, ',')) pload(p, s); else acc = 1; }
        else if (is(p, K_SET)) { pnext(p); if (is(p, '(') || is(p, '=') || is(p, ';') || is(p, '}') || is(p, ',')) pload(p, s); else acc = 2; }
        else if (is(p, '*')) { pnext(p); is_gen = 1; }
        else if (is(p, K_ASYNC)) { pnext(p); if (is(p, '*') || is(p, T_IDENT) || is(p, T_STR) || is(p, T_NUM) || is(p, '[')) is_async = 1; else pload(p, s); }
        int computed;
        Ast *name2 = parse_property_name(p, &computed);
        if (acc) {
            Ast *m = mk(p, N_OBJMETHOD);
            m->flags = flags | (acc == 1 ? F_GETTER : F_SETTER) | F_METHOD;
            addk(m, name2);
            Ast *params = parse_formal_params(p);
            Ast *body = parse_func_body(p, 0, 0);
            addk(m, params); addk(m, body);
            m->i = computed;
            addk(body, m);
            continue;
        }
        if (is(p, '(')) {
            Ast *m = mk(p, N_OBJMETHOD);
            m->flags = flags | F_METHOD | (is_gen ? F_GEN : 0) | (is_async ? F_ASYNC : 0);
            addk(m, name2);
            Ast *params = parse_formal_params(p);
            Ast *body2 = parse_func_body(p, is_gen, is_async);
            addk(m, params); addk(m, body2);
            m->i = computed;
            addk(body, m);
            continue;
        }
        /* field */
        Ast *f = mk(p, N_OBJPROP);
        f->flags = flags | F_FIELD;
        addk(f, name2);
        if (eat(p, '=')) addk(f, parse_assign_expr(p));
        addk(body, f);
        if (!eat(p, ';')) {
            if (!p->tok.nl && !is(p, '}') && !is(p, T_EOF_)) perr(p, "expecting ';'");
        }
    }
    expect(p, '}');
    addk(n, body);
    return n;
}
