static Ast *parse_property_name(Parse *p, int *is_computed) {
    *is_computed = 0;
    if (is(p, '[')) { pnext(p); *is_computed = 1; Ast *e = parse_assign_expr(p); expect(p, ']'); return e; }
    if (is(p, T_STR)) { Ast *n = mk(p, N_STR); n->v = p->tok.str; pnext(p); return n; }
    if (is(p, T_NUM)) { Ast *n = mk(p, N_NUM); n->num = p->tok.num; n->v = js_num_to_string(p->tok.num); pnext(p); return n; }
    if (is(p, T_BIG)) { Ast *n = mk(p, N_BIG); n->v = p->tok.str; pnext(p); return n; }
    if (is(p, T_IDENT) || (p->tok.type >= KW && p->tok.type != K_IN && p->tok.type != K_INSTANCEOF)) {
        Ast *n = mk(p, N_STR); n->v = ident_name(p); pnext(p); return n;
    }
    perr(p, "property name expected");
    return NULL;
}

static Ast *parse_func_body(Parse *p, int is_gen, int is_async) {
    Ast *body = mk(p, N_BLOCK);
    int oy = p->allow_yield, oa = p->allow_await;
    p->allow_yield = is_gen;
    p->allow_await = is_async;
    expect(p, '{');
    Ast *st = parse_statements(p);
    addk(body, st);
    expect(p, '}');
    p->allow_yield = oy; p->allow_await = oa;
    return body;
}

static Ast *parse_formal_params(Parse *p) {
    expect(p, '(');
    Ast *l = parse_binding_list(p, ')');
    expect(p, ')');
    return l;
}

static Ast *parse_func_expr(Parse *p, int is_async, int is_gen) {
    if (eat(p, '*')) is_gen = 1;
    Ast *n = mk(p, N_FUNC);
    n->flags = (is_gen ? F_GEN : 0) | (is_async ? F_ASYNC : 0);
    JSValue name = js_undef();
    if (is(p, T_IDENT) || is_simple_ident(p)) { name = ident_name(p); pnext(p); }
    n->v = name;
    Ast *params = parse_formal_params(p);
    Ast *body = parse_func_body(p, is_gen, is_async);
    addk(n, params);
    addk(n, body);
    return n;
}

static Ast *parse_method(Parse *p, int flags) {
    int is_gen = 0, is_async = 0, kind = 0;
    if (eat(p, '*')) is_gen = 1;
    else if (is(p, K_ASYNC)) {
        PState s = pstate(p);
        pnext(p);
        if (is(p, '*') || is(p, T_IDENT) || is(p, T_STR) || is(p, T_NUM) || is(p, '[')) is_async = 1;
        else pload(p, s);
    }
    int computed;
    Ast *name = parse_property_name(p, &computed);
    Ast *n;
    if (is(p, '(')) {
        n = mk(p, N_OBJMETHOD);
        n->flags = flags | (is_gen ? F_GEN : 0) | (is_async ? F_ASYNC : 0);
        Ast *params = parse_formal_params(p);
        Ast *body = parse_func_body(p, is_gen, is_async);
        addk(n, name);
        addk(n, params);
        addk(n, body);
        n->i = computed;
        return n;
    }
    /* field */
    n = mk(p, N_OBJPROP);
    n->flags = flags | F_FIELD;
    addk(n, name);
    if (eat(p, '=')) addk(n, parse_assign_expr(p));
    return n;
