static Ast *parse_obj_literal(Parse *p) {
    Ast *n = mk(p, N_OBJECT);
    expect(p, '{');
    while (!is(p, '}') && !is(p, T_EOF_)) {
        if (eat(p, ',')) continue;
        if (is(p, OP_ELLIPSIS)) {
            pnext(p);
            Ast *s = mk(p, N_SPREAD);
            addk(s, parse_assign_expr(p));
            addk(n, s);
            continue;
        }
        int is_async = 0, is_gen = 0, acc = 0;
