static Ast *parse_arguments(Parse *p) {
    Ast *args = mk(p, N_ARRAY);
    expect(p, '(');
    while (!is(p, ')') && !is(p, T_EOF_)) {
        if (is(p, OP_ELLIPSIS)) { pnext(p); Ast *s = mk(p, N_SPREAD); addk(s, parse_assign_expr(p)); addk(args, s); }
        else addk(args, parse_assign_expr(p));
        if (!eat(p, ',')) break;
    }
    expect(p, ')');
    return args;
}

static Ast *parse_member_tail(Parse *p, Ast *obj, int allow_call) {
    int opt = 0;
    for (;;) {
        int t = p->tok.type;
        if (t == '.') {
            Ast *n = mk(p, N_MEMBER);
            n->pos = p->tok.pos;
            pnext(p);
            if (!is_simple_ident(p) && !(p->tok.type >= KW)) perr(p, "property name expected");
            if (p->tok.type == T_IDENT || p->tok.type >= KW) { n->v = ident_name(p); pnext(p); }
            else perr(p, "property name expected");
            addk(n, obj);
            if (opt) n->flags |= F_OPT;
            obj = n;
        } else if (t == '[') {
            Ast *n = mk(p, N_MEMBER);
            n->pos = p->tok.pos;
            n->flags |= F_COMPUTED;
            pnext(p);
            addk(n, obj);
            addk(n, parse_expr(p));
            expect(p, ']');
            if (opt) n->flags |= F_OPT;
            obj = n;
        } else if (t == OP_QDOT) {
            opt = 1;
            pnext(p);
            if (is(p, '(')) {
                Ast *n = mk(p, N_CALL);
                n->flags = F_OPT;
                n->pos = p->tok.pos;
                addk(n, obj);
                addk(n, parse_arguments(p));
                obj = n;
            } else if (is(p, '[')) {
                Ast *n = mk(p, N_MEMBER);
                n->pos = p->tok.pos;
                n->flags = F_COMPUTED | F_OPT;
                pnext(p);
                addk(n, obj);
                addk(n, parse_expr(p));
                expect(p, ']');
                obj = n;
            } else {
                if (!is_simple_ident(p) && !(p->tok.type >= KW)) perr(p, "property name expected");
                Ast *n = mk(p, N_MEMBER);
                n->pos = p->tok.pos;
                n->flags = F_OPT;
                n->v = ident_name(p);
                pnext(p);
                addk(n, obj);
                obj = n;
            }
        } else if (t == '(' && allow_call) {
            Ast *n = mk(p, N_CALL);
            n->pos = p->tok.pos;
            addk(n, obj);
            addk(n, parse_arguments(p));
            if (opt) n->flags |= F_OPT;
            obj = n;
        } else if ((t == T_TMPL || t == T_TMPLSTART) && p->tok.nl == 0) {
            /* tagged template */
            Ast *n = mk(p, N_TAGGED);
            Ast *tmpl;
            {
                Ast *tn = mk(p, N_TEMPLATE);
                Ast *parts = mk(p, N_ARRAY), *exprs = mk(p, N_ARRAY), *raws = mk(p, N_ARRAY);
                for (;;) {
                    Ast *part = mk(p, N_STR); part->v = p->tok.str;
                    Ast *raw = mk(p, N_STR); raw->v = js_string_n(p->tok.re_src, p->tok.re_len);
                    addk(parts, part); addk(raws, raw);
                    if (p->tok.type == T_TMPL) { pnext(p); break; }
                    pnext(p);
                    addk(exprs, parse_expr(p));
                    expect(p, '}');
                }
                addk(tn, parts); addk(tn, exprs); addk(tn, raws);
                tmpl = tn;
            }
            addk(n, obj);
            addk(n, tmpl);
            obj = n;
        } else break;
    }
    return obj;
}

static Ast *parse_postfix(Parse *p) {
    Ast *e = parse_primary(p);
    e = parse_member_tail(p, e, 1);
    while ((is(p, OP_INCR) || is(p, OP_DECR)) && !p->tok.nl) {
        Ast *n = mk(p, N_UPDATE);
        n->pos = p->tok.pos;
        n->i = is(p, OP_INCR) ? 1 : 2;
        addk(n, e);
        pnext(p);
        e = n;
    }
    return e;
}

static Ast *parse_unary(Parse *p) {
    int t = p->tok.type;
    switch (t) {
    case K_DELETE: case K_VOID: case K_TYPEOF: case '+': case '-': case '~': case '!': {
        Ast *n = mk(p, N_UNOP);
        n->pos = p->tok.pos;
        int op;
        switch (t) {
        case K_DELETE: op = 6; break;
        case K_VOID: op = 5; break;
        case K_TYPEOF: op = 4; break;
        case '+': op = 1; break;
        case '-': op = 0; break;
        case '~': op = 2; break;
        default: op = 3; break;
        }
        n->i = op;
        pnext(p);
        addk(n, parse_unary(p));
        return n;
    }
    case OP_INCR: case OP_DECR: {
        Ast *n = mk(p, N_UPDATE);
        n->pos = p->tok.pos;
        n->i = (t == OP_INCR ? 1 : 2) | 4;
        pnext(p);
        addk(n, parse_unary(p));
        return n;
    }
    case K_AWAIT:
        if (p->allow_await) {
            Ast *n = mk(p, N_AWAIT);
            n->pos = p->tok.pos;
            pnext(p);
            addk(n, parse_unary(p));
            return n;
        }
        break;
    case K_YIELD:
        if (p->allow_yield) {
            Ast *n = mk(p, N_YIELD);
            n->pos = p->tok.pos;
            pnext(p);
            if (is(p, '*') && !p->tok.nl) { n->flags |= F_YSTAR; pnext(p); addk(n, parse_assign_expr(p)); return n; }
            if (p->tok.nl || is(p, ')') || is(p, ']') || is(p, '}') || is(p, ',') || is(p, ';') || is(p, ':') ||
                is(p, T_EOF_)) return n;
            addk(n, parse_assign_expr(p));
            return n;
        }
        break;
    }
    return parse_postfix(p);
}

static int binop_prec(int t, int *op, int *right) {
    *right = 0;
    switch (t) {
    case OP_POW: *op = 4; return 1;
    case '*': *op = 1; return 2;
    case '/': *op = 2; return 2;
    case '%': *op = 3; return 2;
    case '+': *op = 100; return 3;
    case '-': *op = 0; return 3;
    case OP_SHL: *op = 5; return 4;
    case OP_SHR: *op = 6; return 4;
    case OP_USHR: *op = 7; return 4;
    case '<': *op = 20; return 5;
    case '>': *op = 21; return 5;
    case OP_LE: *op = 22; return 5;
    case OP_GE: *op = 23; return 5;
    case K_IN: if (!p_allow_in_flag) return 0; *op = 11; return 5;
    case K_INSTANCEOF: *op = 12; return 5;
    case OP_EQ: *op = 14; return 6;
    case OP_NE: *op = 15; return 6;
    case OP_STREQ: *op = 16; return 6;
    case OP_STRNE: *op = 17; return 6;
    case '&': *op = 8; return 7;
    case '^': *op = 10; return 8;
    case '|': *op = 9; return 9;
    case OP_ANDAND: *op = 30; return 10;
    case OP_OROR: *op = 31; return 11;
    case OP_NULLISH: *op = 32; *right = 1; return 12;
    }
    return 0;
}
int p_allow_in_flag = 1;

static Ast *parse_binary(Parse *p, int minprec) {
    Ast *left = parse_unary(p);
    for (;;) {
        int op, right;
        int prec = binop_prec(p->tok.type, &op, &right);
        if (!prec || prec < minprec) break;
        if (p->tok.type == K_IN) { if (!p->allow_in) break; }
        int pos = p->tok.pos;
        pnext(p);
        Ast *r = parse_binary(p, right ? prec : prec + 1);
        Ast *n = mk(p, op >= 30 ? N_LOGOP : N_BINOP);
        n->i = op;
        n->pos = pos;
        addk(n, left);
        addk(n, r);
        left = n;
    }
    return left;
}

static Ast *parse_cond(Parse *p) {
    Ast *e = parse_binary(p, 1);
    if (is(p, '?')) {
        Ast *n = mk(p, N_COND);
        n->pos = p->tok.pos;
        pnext(p);
        int oi = p->allow_in;
        p->allow_in = 1;
        addk(n, e);
        addk(n, parse_assign_expr(p));
        expect(p, ':');
        addk(n, parse_assign_expr(p));
        p->allow_in = oi;
        return n;
    }
    return e;
}

static Ast *to_pattern(Ast *n) {
    if (!n) return n;
    if (n->kind == N_IDENT || n->kind == N_MEMBER) return n;
    if (n->kind == N_ARRAY) {
        Ast *r = mk_of(n, N_ARRPAT);
        for (int i = 0; i < n->nk; i++) {
            Ast *e = n->k[i];
            if (e->kind == N_HOLE) { addk(r, e); continue; }
            if (e->kind == N_SPREAD) { Ast *s = mk_of(n, N_SPREAD); addk(s, to_pattern(e->k[0])); addk(r, s); continue; }
            if (e->kind == N_ASSIGN) { Ast *d = mk_of(n, N_DEFAULT); addk(d, to_pattern(e->k[0])); addk(d, e->k[1]); addk(r, d); continue; }
            addk(r, to_pattern(e));
        }
        return r;
    }
    if (n->kind == N_OBJECT) {
        Ast *r = mk_of(n, N_OBJPAT);
        for (int i = 0; i < n->nk; i++) {
            Ast *e = n->k[i];
            if (e->kind == N_SPREAD) { Ast *s = mk_of(n, N_SPREAD); addk(s, to_pattern(e->k[0])); addk(r, s); continue; }
            Ast *key = e->k[0];
            Ast *val = e->k[1];
            Ast *tgt;
            if (val->kind == N_ASSIGN) { Ast *d = mk_of(n, N_DEFAULT); addk(d, to_pattern(val->k[0])); addk(d, val->k[1]); tgt = d; }
            else tgt = to_pattern(val);
            Ast *pr = mk_of(n, N_PAIR);
            addk(pr, key);
            addk(pr, tgt);
            addk(r, pr);
        }
        return r;
    }
    return n;
}

static Ast *parse_assign_expr(Parse *p) {
    /* arrow functions */
    if (is(p, '(')) {
        Ast *params; int is_async = 0;
        if (try_arrow(p, &params, &is_async)) {
            pnext(p);
            return build_arrow(p, params, is_async, 0);
        }
    } else if (is_simple_ident(p) && p->tok.type != K_ASYNC) {
        PState s = pstate(p);
        pnext(p);
        if (is(p, OP_ARROW)) {
            pload(p, s);
            Ast *params = mk(p, N_ARRAY);
            Ast *b = mk(p, N_IDENT); b->v = ident_name(p);
            addk(params, b);
            pnext(p);
            return build_arrow(p, params, 0, 0);
        }
        pload(p, s);
    } else if (is(p, K_ASYNC)) {
        PState s = pstate(p);
        pnext(p);
        if (is(p, K_FUNCTION)) {
            pnext(p);
            Ast *f = parse_func_expr(p, 1, 0);
            return f;
        }
        pload(p, s);
        Ast *params; int is_async = 0;
        if (try_arrow(p, &params, &is_async)) {
            pnext(p);
            return build_arrow(p, params, is_async, 0);
        }
        pload(p, s);
    }
    Ast *e = parse_cond(p);
    if (is_assign_op(p->tok.type)) {
        int op = assign_op_bin(p->tok.type);
        if (p->tok.type == '=') op = -1;
        int pos = p->tok.pos;
        Ast *target;
        if (e->kind == N_ARRAY || e->kind == N_OBJECT) target = to_pattern(e);
