            if (e->kind == N_ASSIGN) { Ast *d = mk_of(n, N_DEFAULT); addk(d, to_pattern(e->k[0])); addk(d, e->k[1]); addk(r, d); continue; }
            addk(r, to_pattern(e));
        }
        return r;
    }
    if (n->kind == N_OBJECT) {
        Ast *r = mk_of(n, N_OBJPAT);
        for (int i = 0; i < n->nk; i++) {
            Ast *e = n->k[i];
            if (e->kind == N_SPREAD) { Ast *s = mk_of(n, N_SPREAD); addk(s, to_pattern(e->k[0])); addk(r, s); continue; }
            Ast *key = e->k[0];
            Ast *val = e->k[1];
            Ast *tgt;
            if (val->kind == N_ASSIGN) { Ast *d = mk_of(n, N_DEFAULT); addk(d, to_pattern(val->k[0])); addk(d, val->k[1]); tgt = d; }
            else tgt = to_pattern(val);
            Ast *pr = mk_of(n, N_PAIR);
            addk(pr, key);
            addk(pr, tgt);
            addk(r, pr);
        }
        return r;
    }
    return n;
}

static Ast *parse_assign_expr(Parse *p) {
    /* arrow functions */
    if (is(p, '(')) {
        Ast *params; int is_async = 0;
        if (try_arrow(p, &params, &is_async)) {
            pnext(p);
            return build_arrow(p, params, is_async, 0);
        }
    } else if (is_simple_ident(p) && p->tok.type != K_ASYNC) {
        PState s = pstate(p);
        pnext(p);
        if (is(p, OP_ARROW)) {
            pload(p, s);
            Ast *params = mk(p, N_ARRAY);
            Ast *b = mk(p, N_IDENT); b->v = ident_name(p);
            addk(params, b);
            pnext(p);
            return build_arrow(p, params, 0, 0);
        }
        pload(p, s);
    } else if (is(p, K_ASYNC)) {
        PState s = pstate(p);
        pnext(p);
        if (is(p, K_FUNCTION)) {
            pnext(p);
            Ast *f = parse_func_expr(p, 1, 0);
            return f;
        }
        pload(p, s);
        Ast *params; int is_async = 0;
        if (try_arrow(p, &params, &is_async)) {
            pnext(p);
            return build_arrow(p, params, is_async, 0);
        }
        pload(p, s);
    }
    Ast *e = parse_cond(p);
    if (is_assign_op(p->tok.type)) {
        int op = assign_op_bin(p->tok.type);
        if (p->tok.type == '=') op = -1;
        int pos = p->tok.pos;
        Ast *target;
        if (e->kind == N_ARRAY || e->kind == N_OBJECT) target = to_pattern(e);
        else target = e;
        if (target->kind != N_IDENT && target->kind != N_MEMBER && target->kind != N_ARRPAT &&
            target->kind != N_OBJPAT) perr(p, "invalid assignment left-hand side");
        pnext(p);
        int oi = p->allow_in;
        p->allow_in = 1;
        Ast *val = parse_assign_expr(p);
        p->allow_in = oi;
        Ast *n = mk(p, N_ASSIGN);
        n->pos = pos;
        n->i = op;
        addk(n, target);
        addk(n, val);
        return n;
    }
    return e;
}

static Ast *parse_expr(Parse *p) {
    Ast *e = parse_assign_expr(p);
    while (is(p, ',')) {
        int pos = p->tok.pos;
        pnext(p);
        Ast *n;
        if (e->kind == N_SEQ) n = e;
        else { n = mk(p, N_SEQ); n->pos = pos; addk(n, e); }
        addk(n, parse_assign_expr(p));
        e = n;
    }
    return e;
}
