static Ast *mk_of(Ast *n, int kind) {
    Ast *r = js_malloc(sizeof(Ast));
    r->kind = kind; r->pos = n->pos; r->flags = 0; r->nk = 0; r->kcap = 0;
    r->k = NULL; r->v = js_undef(); r->num = 0; r->i = 0; r->n2 = 0; r->x = NULL;
    return r;
}

static Ast *build_arrow(Parse *p, Ast *params, int is_async, int is_gen) {
    Ast *n = mk(p, N_ARROW);
    n->flags = F_ARROW | (is_async ? F_ASYNC : 0) | (is_gen ? F_GEN : 0);
    addk(n, params);
    if (is(p, '{')) {
        pnext(p);
        Ast *body = mk(p, N_BLOCK);
        int oy = p->allow_yield, oa = p->allow_await;
        p->allow_yield = is_gen;
        p->allow_await = is_async;
        addk(body, parse_statements(p));
        expect(p, '}');
        p->allow_yield = oy; p->allow_await = oa;
        addk(n, body);
        n->i = 1;
    } else {
        int oy = p->allow_yield, oa = p->allow_await;
        p->allow_yield = is_gen;
        p->allow_await = is_async;
        Ast *e = parse_assign_expr(p);
        Ast *body = mk(p, N_BLOCK);
        Ast *st = mk(p, N_RETURN); addk(st, e);
        Ast *list = mk(p, N_PROG); addk(list, st);
        addk(body, list);
        addk(n, body);
        n->i = 0;
        p->allow_yield = oy; p->allow_await = oa;
    }
    return n;
}

/* ------------------------------ statements -------------------------------- */
static Ast *parse_var_decl_stmt(Parse *p, int kind, int no_init) {
    Ast *n = mk(p, N_VARDECL);
    n->flags = kind;
    pnext(p);
    for (;;) {
        Ast *tgt = parse_binding(p);
        Ast *d = mk(p, N_DECL);
        addk(d, tgt);
        if (!no_init && is(p, '=')) { pnext(p); addk(d, parse_assign_expr(p)); }
        addk(n, d);
        if (!eat(p, ',')) break;
    }
    return n;
}

static Ast *parse_for_stmt(Parse *p) {
    Ast *n = mk(p, N_FOR);
    expect(p, '(');
    int oi = p->allow_in;
    p->allow_in = 0;
    Ast *init = NULL;
    if (is(p, ';')) { }
    else if (is(p, K_VAR) || is(p, K_LET) || is(p, K_CONST)) {
        int kind = p->tok.type == K_VAR ? 0 : p->tok.type == K_LET ? F_LET : F_CONST;
        PState s = pstate(p);
        pnext(p);
        Ast *tgt = parse_binding(p);
        if (is(p, K_OF) || is(p, K_IN)) {
            p->allow_in = oi;
            Ast *d = mk(p, N_DECL); addk(d, tgt);
            Ast *vd = mk(p, N_VARDECL);
            vd->flags = kind;
            addk(vd, d);
            if (is(p, K_OF)) {
                pnext(p);
                Ast *f = mk(p, N_FOROF);
                if (p->tok.type == K_AWAIT && 0) { }
                addk(f, vd);
                addk(f, parse_assign_expr(p));
                expect(p, ')');
                addk(f, parse_statement(p));
                p->allow_in = oi;
                return f;
            } else {
                pnext(p);
                Ast *f = mk(p, N_FORIN);
                addk(f, vd);
                addk(f, parse_expr(p));
                expect(p, ')');
                addk(f, parse_statement(p));
                p->allow_in = oi;
                return f;
            }
        }
        pload(p, s);
        init = parse_var_decl_stmt(p, kind, 0);
    } else if (is(p, K_ASYNC)) {
        PState s = pstate(p);
        pnext(p);
        if (is(p, K_AWAIT)) {
            pnext(p);
            if (is(p, K_FOR)) { }
            /* await for-of */
            if (is(p, '(')) { }
            pload(p, s);
            pnext(p); /* async */
            pnext(p); /* await */
            pnext(p); /* ( */
            p->allow_in = 0;
            int kind = 0;
            Ast *tgt;
            if (is(p, K_VAR) || is(p, K_LET) || is(p, K_CONST)) { kind = p->tok.type == K_VAR ? 0 : p->tok.type == K_LET ? F_LET : F_CONST; pnext(p); tgt = parse_binding(p); }
            else tgt = parse_binding(p);
            Ast *d = mk(p, N_DECL); addk(d, tgt);
            Ast *vd = mk(p, N_VARDECL); vd->flags = kind; addk(vd, d);
            if (!is(p, K_OF)) perr(p, "expecting 'of'");
            pnext(p);
            Ast *f = mk(p, N_FOROF);
            f->flags = F_ASYNC;
            addk(f, vd);
            addk(f, parse_assign_expr(p));
            expect(p, ')');
            addk(f, parse_statement(p));
            p->allow_in = oi;
            return f;
        }
        pload(p, s);
        init = parse_expr(p);
    } else {
        init = parse_expr(p);
        if (is(p, K_OF) || is(p, K_IN)) {
            p->allow_in = oi;
            Ast *f;
            if (is(p, K_OF)) { pnext(p); f = mk(p, N_FOROF); }
            else { pnext(p); f = mk(p, N_FORIN); }
            addk(f, init);
            addk(f, parse_expr(p));
            expect(p, ')');
            addk(f, parse_statement(p));
            p->allow_in = oi;
            return f;
        }
    }
    p->allow_in = oi;
    expect(p, ';');
    Ast *cond = NULL, *step = NULL;
    if (!is(p, ';')) cond = parse_expr(p);
    expect(p, ';');
    if (!is(p, ')')) step = parse_expr(p);
    expect(p, ')');
    addk(n, init ? init : mk(p, N_EMPTY));
    addk(n, cond ? cond : mk(p, N_EMPTY));
    addk(n, step ? step : mk(p, N_EMPTY));
    addk(n, parse_statement(p));
    return n;
}

static Ast *parse_statement(Parse *p) {
    switch (p->tok.type) {
    case '{': {
        Ast *n = mk(p, N_BLOCK);
        pnext(p);
        addk(n, parse_statements(p));
        expect(p, '}');
        return n;
    }
    case ';': { Ast *n = mk(p, N_EMPTY); pnext(p); return n; }
    case K_VAR: return parse_var_decl_stmt(p, 0, 0);
    case K_LET: {
        PState s = pstate(p);
        pnext(p);
        if (is(p, T_IDENT) || is(p, '[') || is(p, '{')) { pload(p, s); return parse_var_decl_stmt(p, F_LET, 0); }
        pload(p, s);
        break;
    }
    case K_CONST: return parse_var_decl_stmt(p, F_CONST, 0);
    case K_FUNCTION: {
        pnext(p);
        Ast *n = mk(p, N_FUNC);
        n->flags = F_HASNAME;
        if (eat(p, '*')) n->flags |= F_GEN;
        if (is_simple_ident(p)) { n->v = ident_name(p); pnext(p); }
        else perr(p, "function name expected");
        Ast *params = parse_formal_params(p);
        Ast *body = parse_func_body(p, (n->flags & F_GEN) != 0, 0);
        addk(n, params); addk(n, body);
        return n;
    }
    case K_ASYNC: {
        PState s = pstate(p);
        pnext(p);
        if (is(p, K_FUNCTION)) {
            pnext(p);
            Ast *n = mk(p, N_FUNC);
            n->flags = F_HASNAME | F_ASYNC;
            if (eat(p, '*')) n->flags |= F_GEN;
            if (is_simple_ident(p)) { n->v = ident_name(p); pnext(p); }
            else perr(p, "function name expected");
            Ast *params = parse_formal_params(p);
            Ast *body = parse_func_body(p, (n->flags & F_GEN) != 0, 1);
            addk(n, params); addk(n, body);
            return n;
        }
        pload(p, s);
        break;
    }
    case K_CLASS: {
        pnext(p);
        JSValue name = js_undef();
        if (is(p, T_IDENT)) { name = ident_name(p); pnext(p); }
        Ast *n = parse_class_expr(p, name);
        n->flags |= F_HASNAME;
        return n;
    }
    case K_IF: {
        Ast *n = mk(p, N_IF);
        pnext(p);
        expect(p, '(');
        addk(n, parse_expr(p));
        expect(p, ')');
        addk(n, parse_statement(p));
        if (is(p, K_ELSE)) { pnext(p); addk(n, parse_statement(p)); }
        return n;
    }
    case K_DO: {
        Ast *n = mk(p, N_DO);
        pnext(p);
        addk(n, parse_statement(p));
        if (!is(p, K_WHILE)) perr(p, "expecting 'while'");
        pnext(p);
        expect(p, '(');
        addk(n, parse_expr(p));
        expect(p, ')');
        eat(p, ';');
        return n;
    }
    case K_WHILE: {
        Ast *n = mk(p, N_WHILE);
        pnext(p);
        expect(p, '(');
        addk(n, parse_expr(p));
        expect(p, ')');
        addk(n, parse_statement(p));
        return n;
    }
    case K_FOR: return parse_for_stmt(p);
    case K_BREAK: case K_CONTINUE: {
        Ast *n = mk(p, p->tok.type == K_BREAK ? N_BREAK : N_CONTINUE);
        pnext(p);
        if (is(p, T_IDENT) && !p->tok.nl) { n->v = ident_name(p); pnext(p); }
        return n;
    }
    case K_RETURN: {
        Ast *n = mk(p, N_RETURN);
        pnext(p);
        if (!p->tok.nl && !is(p, ';') && !is(p, '}') && !is(p, T_EOF_)) addk(n, parse_expr(p));
