    }
    case K_THROW: {
        Ast *n = mk(p, N_THROW);
        pnext(p);
        if (p->tok.nl) perr(p, "newline not allowed after throw");
        addk(n, parse_expr(p));
        return n;
    }
    case K_TRY: {
        Ast *n = mk(p, N_TRY);
        pnext(p);
        addk(n, parse_statement(p));
        if (is(p, K_CATCH)) {
            pnext(p);
            Ast *c = mk(p, N_CATCH);
            if (eat(p, '(')) {
                Ast *b = parse_binding(p);
                addk(c, b);
                expect(p, ')');
            }
            addk(c, parse_statement(p));
            addk(n, c);
        }
