        pnext(p);
        if (!is(p, T_STR)) perr(p, "string expected");
        Ast *mname = mk(p, N_STR); mname->v = p->tok.str;
        addk(n, mname);
        addk(n, clauses);
        return n;
    }
    case K_EXPORT: {
        if (!p->in_module) perr(p, "export declaration only allowed at toplevel of module");
        Ast *n = mk(p, N_EXPORT);
        pnext(p);
        if (is(p, K_DEFAULT)) {
            pnext(p);
            n->flags |= F_EXPORTDEF;
            if (is(p, K_FUNCTION)) {
                pnext(p);
                Ast *f = mk(p, N_FUNC);
                f->flags = F_HASNAME;
                if (eat(p, '*')) f->flags |= F_GEN;
                if (is_simple_ident(p)) { f->v = ident_name(p); pnext(p); }
                Ast *params = parse_formal_params(p);
                Ast *body = parse_func_body(p, (f->flags & F_GEN) != 0, 0);
                addk(f, params); addk(f, body);
                f->flags |= F_DEFAULT;
                addk(n, f);
                return n;
            }
            if (is(p, K_CLASS)) {
                pnext(p);
                JSValue name = js_undef();
                if (is(p, T_IDENT)) { name = ident_name(p); pnext(p); }
                Ast *c = parse_class_expr(p, name);
                c->flags |= F_HASNAME | F_DEFAULT;
                addk(n, c);
                return n;
            }
            if (is(p, K_ASYNC)) {
                PState s = pstate(p);
                pnext(p);
                if (is(p, K_FUNCTION)) { pnext(p); Ast *f = mk(p, N_FUNC); f->flags = F_HASNAME | F_ASYNC; if (eat(p,'*')) f->flags |= F_GEN; if (is_simple_ident(p)) { f->v = ident_name(p); pnext(p); } Ast *params = parse_formal_params(p); Ast *body = parse_func_body(p, (f->flags&F_GEN)!=0, 1); addk(f, params); addk(f, body); f->flags |= F_DEFAULT; addk(n, f); return n; }
