                Ast *e = mk(p, N_SPREAD);
                e->v = ident_name(p);
                pnext(p);
                Ast *clauses = mk(p, N_ARRAY);
                addk(clauses, e);
                addk(n, clauses);
            } else addk(n, mk(p, N_EMPTY));
            if (!is(p, K_FROM)) perr(p, "expecting 'from'");
            pnext(p);
            if (!is(p, T_STR)) perr(p, "string expected");
