            Ast *f = mk(p, N_FUNC);
            f->flags = F_HASNAME;
            if (eat(p, '*')) f->flags |= F_GEN;
            if (is_simple_ident(p)) { f->v = ident_name(p); pnext(p); }
            else perr(p, "function name expected");
