                f->flags = F_HASNAME | F_ASYNC;
                if (eat(p, '*')) f->flags |= F_GEN;
                if (is_simple_ident(p)) { f->v = ident_name(p); pnext(p); }
                Ast *params = parse_formal_params(p);
                Ast *body = parse_func_body(p, (f->flags & F_GEN) != 0, 1);
                addk(f, params); addk(f, body);
                Ast *clauses = mk(p, N_ARRAY);
                addk(n, clauses); addk(n, f);
                return n;
            }
            pload(p, s);
        }
        Ast *clauses = mk(p, N_ARRAY);
        expect(p, '{');
        while (!is(p, '}') && !is(p, T_EOF_)) {
            if (eat(p, ',')) continue;
            if (!is_simple_ident(p) && !(p->tok.type >= KW)) perr(p, "identifier expected");
            JSValue in = ident_name(p);
            pnext(p);
            JSValue out = in;
            if (is(p, K_AS)) { pnext(p); if (!is_simple_ident(p) && !(p->tok.type >= KW)) perr(p, "identifier expected"); out = ident_name(p); pnext(p); }
            Ast *e = mk(p, N_PAIR);
            Ast *l = mk(p, N_STR); l->v = out;
            Ast *r = mk(p, N_IDENT); r->v = in;
            addk(e, l); addk(e, r);
            addk(clauses, e);
            if (!eat(p, ',')) break;
        }
        expect(p, '}');
        addk(n, clauses);
        addk(n, NULL);
