            pnext(p);
            pnext(p);
            addk(n, parse_statement(p));
            return n;
        }
        pload(p, s);
        break;
    }
    }
    Ast *n = mk(p, N_EXPRSTMT);
    addk(n, parse_expr(p));
    return n;
}

static Ast *parse_statements(Parse *p) {
    Ast *prog = mk(p, N_PROG);
    while (!is(p, '}') && !is(p, T_EOF_)) {
        if (eat(p, ';')) continue;
        Ast *st = parse_statement(p);
        addk(prog, st);
        if (eat(p, ';')) continue;
        if (is(p, '}') || is(p, T_EOF_)) break;
        if (p->tok.nl) continue;
        if (is(p, ')') || is(p, ']')) break;
        perr(p, "expecting ';'");
    }
    return prog;
}

Ast *js_parse(const char *src, int len, int is_module, int strict, const char *filename) {
    Parse *p = js_malloc(sizeof(Parse));
    memset(p, 0, sizeof(Parse));
    p->src = src; p->len = len; p->pos = 0;
    p->in_module = is_module;
    p->strict = strict;
    p->allow_in = 1;
    p->allow_yield = 0;
    p->allow_await = is_module;
    p->si = js_make_src(src, len);
    p->filename = filename;
    next_token(p);
    Ast *prog = mk(p, N_PROG);
    prog->x = p->si;
    addk(prog, parse_statements(p));
    prog->i = strict;
    return prog;
}
int node_is_expr_stmt(Ast *n) { return n->kind == N_EXPRSTMT; }
