static void bind_params(Ast *params, Env *env, int argc, JSValue *argv, int pos) {
    for (int i = 0; i < params->nk; i++) {
        Ast *pt = params->k[i];
        if (pt->kind == N_SPREAD) {
            JSObject *arr = js_new_array_obj();
            for (int j = i; j < argc; j++) js_array_push(arr, argv[j]);
            JSValue av; av.u.p = arr; av.tag = T_OBJ;
            js_bind_pattern(pt->k[0], av, env, 1, pos);
            break;
        }
        JSValue v = i < argc ? argv[i] : js_undef();
        if (pt->kind == N_DEFAULT) {
            if (i >= argc) {
                JSValue d = eval_expr(pt->k[1], env);
                js_bind_pattern(pt->k[0], d, env, 1, pos);
                continue;
            }
            js_bind_pattern(pt->k[0], v, env, 1, pos);
            continue;
        }
        js_bind_pattern(pt, v, env, 1, pos);
    }
}

/* ---------------------- destructuring ------------------------------------ */
void js_bind_pattern(Ast *pat, JSValue val, Env *env, int decl, int pos) {
    switch (pat->kind) {
    case N_IDENT: {
        JSValue key = pat->v;
        if (decl) env_define(env, key, val, P_E);
        else {
            if (!env_set(env, key, val, pos)) { }
        }
        break;
    }
    case N_ARRPAT: {
        JSValue it = js_get_iterator(val, pos);
        int idx = 0;
        int done = 0;
        int fast = 0;
        JSObject *arr = NULL;
        if (val.tag == T_OBJ && obj_of(val)->cls == O_ARRAY) { arr = obj_of(val); fast = 1; }
        for (int i = 0; i < pat->nk; i++) {
            Ast *e = pat->k[i];
            if (e->kind == N_HOLE) { idx++; continue; }
            JSValue v = js_undef();
            if (e->kind == N_SPREAD) {
                JSObject *rest = js_new_array_obj();
                if (fast) {
                    for (int j = idx; j < arr->alen; j++) {
                        JSValue x = js_array_get(arr, j);
                        if (x.tag == T_HOLE) continue;
                        js_array_push(rest, x);
                    }
                } else {
                    while (!done) {
                        JSValue nx = js_iterator_next(it, &done, pos);
                        if (done) break;
                        js_array_push(rest, nx);
                    }
                }
                JSValue rv; rv.u.p = rest; rv.tag = T_OBJ;
                js_bind_pattern(e->k[0], rv, env, decl, pos);
                break;
            }
            if (fast) {
                v = idx < arr->alen ? js_array_get(arr, idx) : js_undef();
                if (v.tag == T_HOLE) v = js_undef();
                idx++;
            } else {
                JSValue nx = js_iterator_next(it, &done, pos);
                if (!done) v = nx;
                idx++;
            }
            if (e->kind == N_DEFAULT) {
                if (!fast && done) { }
                if (v.tag == T_UNDEF) v = eval_expr(e->k[1], env);
                js_bind_pattern(e->k[0], v, env, decl, pos);
            } else {
                js_bind_pattern(e, v, env, decl, pos);
            }
        }
        break;
    }
    case N_OBJPAT: {
        JSObject *o = NULL;
        JSValue ov = js_to_object(val);
        o = obj_of(ov);
        int rest_done = 0;
        for (int i = 0; i < pat->nk; i++) {
            Ast *e = pat->k[i];
            if (e->kind == N_SPREAD) {
                /* rest object: all own enumerable props not already bound */
                JSObject *rest = js_new_object(O_OBJECT);
                JSValue names = js_object_keys_val(ov, 0, 1);
                JSObject *names_o = obj_of(names);
                for (int j = 0; j < js_get_length(names_o, pos); j++) {
                    JSValue k = js_array_get(names_o, j);
                    if (obj_find_prop(o, k)) {
                        /* check if it was bound in this pattern */
                        int used = 0;
                        for (int q = 0; q < i; q++) {
                            Ast *pe = pat->k[q];
                            if (pe->kind != N_PAIR) continue;
                            Ast *pk = pe->k[0];
                            if (pk->kind == N_STR && pk->v.tag == T_STR && str_equal(str_val(pk->v), str_val(k))) { used = 1; break; }
                            if (pk->kind == N_NUM) { }
                        }
                        if (used) continue;
                    }
                    obj_add_prop(rest, k, obj_get_prop(o, k, pos), P_W | P_E | P_C);
                }
                JSValue rv; rv.u.p = rest; rv.tag = T_OBJ;
                js_bind_pattern(e->k[0], rv, env, decl, pos);
                rest_done = 1;
                break;
            }
            Ast *key = e->k[0];
            JSValue k;
            if (key->kind == N_KEY) {
                if (key->flags & F_COMPUTED) k = js_to_property_key(eval_expr(key->k[0], env));
                else k = key->v;
            } else if (key->kind == N_STR) k = key->v;
            else if (key->kind == N_NUM) k = js_num_to_string(key->num);
            else k = js_undef();
            JSValue v = js_get_prop_impl(ov, k, pos, 0, 0);
            Ast *tgt = e->k[1];
            if (tgt->kind == N_DEFAULT) {
                if (v.tag == T_UNDEF) v = eval_expr(tgt->k[1], env);
                js_bind_pattern(tgt->k[0], v, env, decl, pos);
            } else js_bind_pattern(tgt, v, env, decl, pos);
        }
        (void)rest_done;
        break;
    }
    default:
        break;
    }
}
