/* ------------------------------ iterators -------------------------------- */
JSValue js_get_iterator(JSValue obj, int pos) {
    if (obj.tag != T_OBJ && obj.tag != T_STR && !js_is_number(obj.tag))
        js_throw_error(ERR_TYPE, "value is not iterable");
    JSValue m = js_get_prop(obj, ctx->sym_iter, pos, 0);
    if (m.tag != T_OBJ || obj_of(m)->cls != O_FUNCTION)
        js_throw_error(ERR_TYPE, "value is not iterable");
    JSValue args[1]; args[0] = obj;
    return js_call(m, obj, 0, NULL, pos);
}
JSValue js_iterator_next(JSValue it, int *done, int pos) {
    JSValue r = js_call_method(it, "next", 0, NULL, pos);
    if (r.tag != T_OBJ) js_throw_error(ERR_TYPE, "iterator is not an object");
    JSObject *o = obj_of(r);
    JSValue d = obj_get_prop(o, js_atom("done"), pos);
    *done = js_to_boolean(d);
    if (*done) return js_undef();
    return obj_get_prop(o, js_atom("value"), pos);
}

/* ---------------------------- function calls ------------------------------ */
static JSValue eval_call_args(Ast *args, Env *env, int *argc_out, JSValue **argv_out, int pos) {
    JSValue *argv = js_malloc(sizeof(JSValue) * (args->nk + 1));
    int argc = 0;
    for (int i = 0; i < args->nk; i++) {
        Ast *a = args->k[i];
        if (a->kind == N_SPREAD) {
            JSValue v = eval_expr(a->k[0], env);
            JSValue it = js_get_iterator(v, pos);
            int done = 0;
            while (!done) {
                JSValue nx = js_iterator_next(it, &done, pos);
                if (done) break;
                argv[argc++] = nx;
            }
        } else argv[argc++] = eval_expr(a, env);
    }
    *argc_out = argc;
    *argv_out = argv;
    return js_undef();
}

static int depth_check(int pos) {
    if (++ctx->depth > ctx->max_depth) {
        ctx->depth--;
        js_throw_error(ERR_INTERNAL, "stack overflow");
    }
    return 0;
}

JSValue js_call_function(Func *f, JSValue this_val, int argc, JSValue *argv, int pos) {
    if (f->is_gen) {
        return js_make_generator(f, this_val, argc, argv);
    }
    if (f->is_async) {
        return js_run_coroutine(f, this_val, argc, argv);
    }
    depth_check(pos);
    JSValue r = run_body(f, this_val, argc, argv);
    ctx->depth--;
    return r;
}

static JSValue run_body(Func *f, JSValue this_val, int argc, JSValue *argv) {
    Env *env = env_new(f->env, 0);
    env->is_func = 1;
    Env *saved_fe = cur_func_env;
    Env *saved_ce = ctx->cur_env;
    JSValue saved_this = cur_this;
    JSObject *saved_home = cur_home;
    JSValue saved_nt = cur_new_target;
    int saved_strict = ctx->strict_default;
    ctx->cur_env = env;
    cur_func_env = env;
    cur_this = this_val;
    cur_home = f->home;
    cur_new_target = cur_new_target;
    ctx->strict_default = f->strict;
    /* bind parameters */
    bind_params(f->node->k[0], env, argc, argv, 0);
    /* arguments object */
    if (!f->is_arrow) {
        JSObject *args_obj = js_get_argument_obj(f, argc, argv, env);
        JSValue av; av.u.p = args_obj; av.tag = T_OBJ;
        env_define(env, js_atom("arguments"), av, P_E);
    }
    /* hoist var and function declarations */
    hoist_vars(f->node->k[1], env);
    Env *saved_ce2 = ctx->cur_env;
    JSValue ret = js_undef();
    JS_TRY
        Flow fl = exec_stmt(f->node->k[1]->k[0], env);
        if (fl.kind == FL_RET) ret = fl.val;
    JS_CATCH
        ctx->cur_env = saved_ce2;
        ctx->frame_top = (void *)frame_top_get()->prev;
        ctx->strict_default = saved_strict;
        cur_func_env = saved_fe;
        ctx->cur_env = saved_ce;
        cur_this = saved_this;
        cur_home = saved_home;
        cur_new_target = saved_nt;
        js_rethrow();
    JS_END
    ctx->strict_default = saved_strict;
    cur_func_env = saved_fe;
    ctx->cur_env = saved_ce;
    cur_this = saved_this;
    cur_home = saved_home;
    cur_new_target = saved_nt;
    return ret;
}

JSValue js_run_func_body(Func *f, JSValue this_val, int argc, JSValue *argv, int pos) {
    (void)pos;
    return run_body(f, this_val, argc, argv);
}

/* construct */
JSValue js_construct_val(JSValue ctor, int argc, JSValue *argv, int pos, JSValue new_target);

JSValue js_new_object_class(JSObject *ctor, int argc, JSValue *argv, int pos) {
    Func *f = (Func *)ctor;
    if (f->is_native) {
        JSObject *o = js_malloc(sizeof(JSObject));
        o->cls = f->native_cls;
        o->extensible = 1;
        JSValue pv = obj_get_prop((JSValue){ .u.p = ctor, .tag = T_OBJ }, js_atom("prototype"), pos);
        o->proto = pv.tag == T_OBJ ? obj_of(pv) : ctx->obj_proto;
        JSValue ov; ov.u.p = o; ov.tag = T_OBJ;
        js_call((JSValue){ .u.p = ctor, .tag = T_OBJ }, ov, argc, argv, pos);
        return o;
    }
    JSValue cv; cv.u.p = ctor; cv.tag = T_OBJ;
    return js_construct_val(cv, argc, argv, pos, cv);
}

JSValue js_construct(JSValue ctor, int argc, JSValue *argv, int pos) {
    return js_construct_val(ctor, argc, argv, pos, ctor);
}

JSValue js_construct_val(JSValue ctor, int argc, JSValue *argv, int pos, JSValue new_target) {
    if (ctor.tag != T_OBJ || obj_of(ctor)->cls != O_FUNCTION)
        js_throw_error(ERR_TYPE, "not a function");
    Func *f = (Func *)obj_of(ctor);
    if (f->is_native) {
