        if (nm->kind == N_STR) key = nm->v;
        else if (nm->kind == N_NUM) key = js_num_to_string(nm->num);
        else key = js_to_property_key(eval_expr(nm->k[0], env));
        JSValue val = js_undef();
        if (m->nk > 1) val = eval_expr(m->k[1], env);
        if (m->flags & F_STATIC) {
            JSValue k = js_to_property_key(key);
            obj_add_prop(cobj, k, val, P_W | P_E | P_C);
        } else {
            obj_add_prop(cproto, key, val, P_W | P_E | P_C);
        }
    }
    return cv;
}

/* ------------------------------ expressions ------------------------------- */
static JSValue eval_expr(Ast *n, Env *env) {
    switch (n->kind) {
    case N_NUM: return js_from_double(n->num);
    case N_BIG: return n->v;
    case N_STR: return n->v;
    case N_BOOL: return js_bool((int)n->i);
    case N_NULL: return js_null();
    case N_UNDEF: return js_undef();
    case N_EMPTY: case N_HOLE: return js_undef();
    case N_REGEX: return js_regexp_new(n->v, js_undef(), n->pos);
    case N_IDENT: {
        Env *own = NULL;
        JSValue *v = env_find(env, n->v, &own);
        if (v) return *v;
        if (own) return obj_get_prop(own->obj, n->v, n->pos);
        js_throw_error(ERR_REF, "'%s' is not defined", str_val(n->v)->buf);
        return js_undef();
    }
    case N_THIS: return cur_this;
    case N_NEWTARGET: return cur_new_target;
    case N_IMPORTMETA: {
        JSValue mv = env_get_quiet(env, js_atom("import.meta"));
        if (mv.tag == T_UNDEF) mv = env_get_quiet(ctx->global_lex, js_atom("import.meta"));
        return mv;
    }
    case N_DYNAMICIMPORT: {
        JSValue spec = js_to_string_v(eval_expr(n->k[0], env));
        return js_load_module((const char *)str_val(spec)->buf, n->pos);
    }
    case N_THIS2: return js_undef();
    case N_MEMBER: case N_SUPERPROP: {
        JSValue obj;
        if (n->kind == N_SUPERPROP) {
            obj = (JSValue){ .u.p = cur_home ? obj_get_prop((JSValue){ .u.p = cur_home, .tag = T_OBJ }, js_atom("__proto__"), 0).u.p : NULL, .tag = T_OBJ };
            JSObject *home = cur_home;
            if (home) {
                JSValue hv; hv.u.p = home; hv.tag = T_OBJ;
                JSValue hp = js_get_prototype_of(hv, n->pos);
                JSValue ctor = js_get_prop(hp, js_atom("constructor"), n->pos);
                if (ctor.tag == T_OBJ) {
                    JSValue cp = obj_get_prop(obj_of(ctor), js_atom("prototype"), n->pos);
                    if (cp.tag == T_OBJ) obj = cp;
                }
            }
            if (obj.u.p == NULL) { obj = js_undef(); }
        } else {
            obj = eval_expr(n->k[0], env);
        }
        if ((n->flags & F_OPT) && (obj.tag == T_UNDEF || obj.tag == T_NULL)) return js_undef();
        JSValue key;
        if (n->flags & F_COMPUTED) key = js_to_property_key(eval_expr(n->k[1], env));
        else key = n->v;
        return js_get_prop_impl(obj, key, n->pos, (n->flags & F_OPT) != 0, !(n->flags & F_COMPUTED));
    }
    case N_CALL: {
        Ast *c = n->k[0];
        JSValue callee, this_val = js_undef();
        if (c->kind == N_MEMBER) {
            JSValue obj = eval_expr(c->k[0], env);
            if ((n->flags & F_OPT) && (obj.tag == T_UNDEF || obj.tag == T_NULL)) return js_undef();
            JSValue key;
            if (c->flags & F_COMPUTED) key = js_to_property_key(eval_expr(c->k[1], env));
            else key = c->v;
            callee = js_get_prop_impl(obj, key, c->pos, (c->flags & F_OPT) != 0, !(c->flags & F_COMPUTED));
            this_val = obj;
        } else if (c->kind == N_SUPERPROP) {
            JSValue obj = eval_expr(c, env);
            callee = obj;
            this_val = cur_this;
        } else {
            callee = eval_expr(c, env);
        }
        int argc;
        JSValue *argv;
        eval_call_args(n->k[1], env, &argc, &argv, n->pos);
        return js_call(callee, this_val, argc, argv, n->pos);
    }
    case N_NEW: {
        JSValue callee = eval_expr(n->k[0], env);
        int argc;
        JSValue *argv;
        eval_call_args(n->k[1], env, &argc, &argv, n->pos);
        return js_construct(callee, argc, argv, n->pos);
    }
    case N_FUNC: case N_ARROW:
        return js_create_function(n, env);
    case N_CLASS:
        return eval_class(n, env, n->v);
    case N_OBJECT: {
        JSObject *o = js_new_object(O_OBJECT);
        JSValue ov; ov.u.p = o; ov.tag = T_OBJ;
        for (int i = 0; i < n->nk; i++) {
            Ast *e = n->k[i];
            if (e->kind == N_SPREAD) {
                JSValue v = eval_expr(e->k[0], env);
                if (v.tag == T_UNDEF || v.tag == T_NULL) continue;
                JSObject *src = obj_of(js_to_object(v));
                for (Prop *p = src->props; p; p = p->next) {
                    if (!(p->flags & P_E)) continue;
                    if (p->flags & P_ACC) {
                        Prop *np = obj_find_prop(o, p->key);
                        if (!np) np = obj_add_prop(o, p->key, js_undef(), P_ACC | P_E | P_C);
                        if (p->getter) np->getter = (Func *)p->getter;
                        if (p->setter) np->setter = (Func *)p->setter;
                        continue;
                    }
                    JSValue k = p->key;
                    if (js_is_valid_array_index(k)) k = js_to_string_v(k);
                    JSValue val = js_get_prop((JSValue){ .u.p = src, .tag = T_OBJ }, p->key, 0, 0);
                    if (js_is_valid_array_index(k)) { int64_t idx = key_to_index_val(k); js_array_set(o, idx, val); }
                    else obj_add_prop(o, k, val, P_W | P_E | P_C);
                }
                continue;
            }
            Ast *key = e->k[0];
            JSValue kv;
            if (key->kind == N_STR) kv = key->v;
            else if (key->kind == N_NUM) kv = js_num_to_string(key->num);
            else kv = js_to_property_key(eval_expr(key->k[0], env));
            if (e->kind == N_OBJMETHOD) {
                int fl = (e->flags & F_GEN ? F_GEN : 0) | (e->flags & F_ASYNC ? F_ASYNC : 0) |
                    (e->flags & F_GETTER ? F_GETTER : 0) | (e->flags & F_SETTER ? F_SETTER : 0) | F_METHOD;
                char nbuf[128];
                const char *nstr = kv.tag == T_STR ? (const char *)str_val(kv)->buf : "";
                if (e->flags & F_GETTER) snprintf(nbuf, sizeof nbuf, "get %s", nstr);
                else if (e->flags & F_SETTER) snprintf(nbuf, sizeof nbuf, "set %s", nstr);
                else snprintf(nbuf, sizeof nbuf, "%s", nstr);
                Func *f = js_new_func_obj(e, env, js_string(nbuf), fl, NULL);
                f->home = o;
                JSValue fv; fv.u.p = f; fv.tag = T_OBJ;
                if (e->flags & (F_GETTER | F_SETTER)) {
                    Prop *p = obj_find_prop(o, kv);
                    if (!p) p = obj_add_prop(o, kv, js_undef(), P_ACC | P_E | P_C);
                    if (e->flags & F_GETTER) p->getter = f; else p->setter = f;
                } else obj_add_prop(o, kv, fv, P_W | P_E | P_C);
            } else {
                JSValue val = eval_expr(e->k[1], env);
                if (js_is_valid_array_index(kv)) { int64_t idx = key_to_index_val(kv); js_array_set(o, idx, val); }
                else obj_add_prop(o, kv, val, P_W | P_E | P_C);
            }
        }
        return ov;
    }
    case N_ARRAY: {
        JSObject *a = js_new_array_obj();
        JSValue av; av.u.p = a; av.tag = T_OBJ;
        for (int i = 0; i < n->nk; i++) {
            Ast *e = n->k[i];
            if (e->kind == N_HOLE) { if (a->arr_len + 1 > a->alen) a->alen = a->arr_len + 1; a->arr_len++; continue; }
            if (e->kind == N_SPREAD) {
                JSValue v = eval_expr(e->k[0], env);
                JSObject *src = NULL;
                int fast = 0;
                if (v.tag == T_OBJ && obj_of(v)->cls == O_ARRAY) { src = obj_of(v); fast = 1; }
                if (fast) {
                    for (int64_t j = 0; j < src->alen; j++) {
                        JSValue x = js_array_get(src, j);
                        if (x.tag == T_HOLE) continue;
                        js_array_push(a, x);
                    }
                } else {
                    JSValue it = js_get_iterator(v, n->pos);
                    int done = 0;
                    while (!done) {
                        JSValue nx = js_iterator_next(it, &done, n->pos);
                        if (done) break;
                        js_array_push(a, nx);
                    }
                }
                continue;
            }
            js_array_push(a, eval_expr(e, env));
        }
        return av;
    }
    case N_TEMPLATE: {
        Ast *parts = n->k[0], *exprs = n->k[1];
        JSValue r = parts->k[0]->v;
        for (int i = 0; i < exprs->nk; i++) {
            JSValue v = eval_expr(exprs->k[i], env);
            if (v.tag == T_SYM) js_throw_error(ERR_TYPE, "cannot convert symbol to string");
            JSValue sv = js_to_string_v(v);
            r = js_str_concat(str_val(r), str_val(sv));
            if (i + 1 < parts->nk) r = js_str_concat(str_val(r), str_val(parts->k[i+1]->v));
        }
        return r;
    }
    case N_TAGGED: {
        JSValue tag = eval_expr(n->k[0], env);
        Ast *tmpl = n->k[1];
        Ast *parts = tmpl->k[0], *exprs = tmpl->k[1], *raws = tmpl->k[2];
        JSObject *strings = js_new_array_obj();
        JSObject *raw = js_new_array_obj();
        for (int i = 0; i < parts->nk; i++) { js_array_push(strings, parts->k[i]->v); js_array_push(raw, raws->k[i]->v); }
        obj_add_prop(raw, js_atom("raw"), (JSValue){ .u.p = raw, .tag = T_OBJ }, P_W | P_E | P_C);
        JSValue sv; sv.u.p = strings; sv.tag = T_OBJ;
        JSValue rv; rv.u.p = raw; rv.tag = T_OBJ;
        JSValue *argv = js_malloc((exprs->nk + 1) * sizeof(JSValue));
        argv[0] = sv;
        for (int i = 0; i < exprs->nk; i++) argv[i+1] = eval_expr(exprs->k[i], env);
        return js_call(tag, js_undef(), exprs->nk + 1, argv, n->pos);
    }
    case N_SEQ: {
        JSValue v = js_undef();
        for (int i = 0; i < n->nk; i++) v = eval_expr(n->k[i], env);
        return v;
    }
    case N_COND: {
        JSValue c = eval_expr(n->k[0], env);
        return js_to_boolean(c) ? eval_expr(n->k[1], env) : eval_expr(n->k[2], env);
    }
    case N_LOGOP: {
        JSValue l = eval_expr(n->k[0], env);
        int op = (int)n->i;
        if (op == 30) { if (!js_to_boolean(l)) return l; return eval_expr(n->k[1], env); }
        if (op == 31) { if (js_to_boolean(l)) return l; return eval_expr(n->k[1], env); }
        if (l.tag == T_UNDEF || l.tag == T_NULL) return eval_expr(n->k[1], env);
        return l;
    }
    case N_BINOP: {
        JSValue a = eval_expr(n->k[0], env);
        JSValue b = eval_expr(n->k[1], env);
        int op = (int)n->i;
        if (op == 100) return js_add(a, b, n->pos);
        if (op >= 20 && op <= 23) return js_compare(a, b, op - 20, n->pos);
        if (op == 14) return js_bool(js_loose_eq(a, b, n->pos));
        if (op == 15) return js_bool(!js_loose_eq(a, b, n->pos));
        if (op == 16) return js_bool(js_strict_eq(a, b));
        if (op == 17) return js_bool(!js_strict_eq(a, b));
        return js_binop(a, b, op, n->pos);
    }
    case N_UNOP: {
        JSValue a = eval_expr(n->k[0], env);
        return js_unary(a, (int)n->i, n->pos);
    }
    case N_AWAIT: {
        JSValue v = eval_expr(n->k[0], env);
        return await_value(v, n->pos);
    }
    case N_YIELD: {
        JSValue v = n->nk ? eval_expr(n->k[0], env) : js_undef();
        return yield_value(v, (n->flags & F_YSTAR) != 0, n->pos);
    }
    case N_UPDATE: {
        Ast *t = n->k[0];
        int pre = (n->i & 4) != 0;
        int inc = (n->i & 3) == 1;
        JSValue old;
        if (t->kind == N_IDENT) {
            old = env_get(env, t->v, t->pos);
        } else if (t->kind == N_MEMBER) {
            JSValue obj = eval_expr(t->k[0], env);
            JSValue key = (t->flags & F_COMPUTED) ? js_to_property_key(eval_expr(t->k[1], env)) : t->v;
            old = js_get_prop_impl(obj, key, t->pos, 0, !(t->flags & F_COMPUTED));
            JSValue nv = js_from_double(js_to_number(old) + (inc ? 1 : -1));
            js_set_prop(obj, key, nv, t->pos);
            return pre ? nv : old;
        } else {
            old = eval_expr(t, env);
            js_throw_error(ERR_TYPE, "invalid operand");
        }
        JSValue nv = js_from_double(js_to_number(old) + (inc ? 1 : -1));
        if (!env_set(env, t->v, nv, t->pos)) { }
        return pre ? nv : old;
    }
    case N_ASSIGN: return eval_assign(n, env);
    case N_SPREAD: return js_undef();
    case N_SUPERCALL: return js_undef();
    default:
        return js_undef();
    }
}
