#include "internal.h"
#include <math.h>
#include <stdarg.h>

/* ------------------------------ helpers ---------------------------------- */
static JSValue num_arg(int argc, JSValue *argv, int i) {
    if (i < argc) return js_to_number_v(argv[i]);
    return js_float(NAN);
}
static int64_t to_index_arg(JSValue v, int64_t def) {
    double d = js_to_number(v);
    if (isnan(d)) return def;
    if (d < 0) return (int64_t)d;
    return (int64_t)d;
}
static int64_t clamp_index(int64_t i, int64_t len) {
    if (i < 0) { i += len; if (i < 0) i = 0; }
    if (i > len) i = len;
    return i;
}
static JSObject *arr_of(JSValue v, int pos) {
    if (v.tag != T_OBJ) js_throw_error(ERR_TYPE, "not an object");
    return obj_of(v);
}

JSValue js_get_argument_obj(Func *f, int argc, JSValue *argv, Env *env) {
    (void)env;
    JSObject *a = js_malloc(sizeof(JSObject));
    a->cls = O_ARGUMENTS;
    a->proto = ctx->obj_proto;
    a->extensible = 1;
    for (int i = 0; i < argc; i++) js_array_set(a, i, argv[i]);
    a->alen = argc;
    obj_add_prop(a, js_atom("length"), js_int(argc), P_W | P_E | P_C);
    obj_add_prop(a, js_atom("callee"), js_func_val(f), P_W | P_C);
    return (JSValue){ .u.p = a, .tag = T_OBJ };
}

/* ------------------------------ console ---------------------------------- */
static JSValue js_console_log_impl(int argc, JSValue *argv, FILE *f) {
    for (int i = 0; i < argc; i++) {
        if (i) fprintf(f, " ");
        if (argv[i].tag == T_STR && argc == 1) {
            JSString *s = str_val(argv[i]);
            fwrite(s->buf, 1, s->blen, f);
        } else {
            JSValue v = js_inspect_str(argv[i], 0);
            JSString *s = str_val(v);
            fwrite(s->buf, 1, s->blen, f);
        }
    }
    fprintf(f, "\n");
    return js_undef();
}
JSValue js_console_log(int argc, JSValue *argv, FILE *f) { return js_console_log_impl(argc, argv, f); }

static JSValue js_console_log_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
    return js_console_log_impl(argc, argv, stdout);
}

/* ------------------------------- Object ---------------------------------- */
static JSValue js_object_ctor(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)opaque;
    if (this_val.tag == T_OBJ && obj_of(this_val)->cls == O_GLOBAL) {
        /* called as a function */
        if (argc == 0 || argv[0].tag == T_UNDEF || argv[0].tag == T_NULL) {
            JSObject *o = js_new_object(O_OBJECT);
            return (JSValue){ .u.p = o, .tag = T_OBJ };
        }
        return js_to_object(argv[0]);
    }
    JSObject *o = obj_of(this_val);
    if (argc > 0 && argv[0].tag == T_OBJ) {
        /* copy own enumerable props */
        JSObject *src = obj_of(argv[0]);
        for (Prop *p = src->props; p; p = p->next) {
            if (!(p->flags & P_E)) continue;
            obj_add_prop(o, p->key, p->val, p->flags);
        }
    }
    return js_undef();
}
static JSValue js_object_create_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
    JSObject *proto = ctx->obj_proto;
    if (argc > 0) {
        if (argv[0].tag == T_OBJ) proto = obj_of(argv[0]);
        else if (argv[0].tag != T_NULL) js_throw_error(ERR_TYPE, "not a prototype");
    }
    JSObject *o = js_new_object(O_OBJECT);
    o->proto = proto;
    JSValue ov; ov.u.p = o; ov.tag = T_OBJ;
    if (argc > 1 && argv[1].tag == T_OBJ) js_object_define_properties(ov, argv[1], 0);
    return ov;
}
static JSValue js_object_keys_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
