    (void)this_val; (void)opaque;
    JSValue o = js_to_object(argc ? argv[0] : js_undef());
    JSValue d = argc > 1 ? argv[1] : js_undef();
    return js_object_define_properties(o, d, 0);
}
static JSValue js_object_values_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
