/* -------------------------------- Symbol --------------------------------- */
static JSValue js_symbol_ctor(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
    if (argc && argv[0].tag == T_SYM) js_throw_error(ERR_TYPE, "cannot convert a Symbol wrapper object to a symbol");
    JSValue desc = js_undef();
    if (argc && argv[0].tag != T_UNDEF) desc = js_to_string_v(argv[0]);
    JSObject *o = js_malloc(sizeof(JSObject));
    o->cls = O_SYMBOL;
    o->proto = ctx->sym_proto;
    o->extensible = 1;
