#include "internal.h"
#include <math.h>
#include <ctype.h>
#include <wchar.h>
#include <locale.h>

/* ------------------------- own property enumeration ----------------------- */
typedef struct { JSValue *k; int n, cap; } KeyList;
static void kl_push(KeyList *l, JSValue k) {
    if (l->n == l->cap) { int nc = l->cap ? l->cap * 2 : 8; JSValue *na = js_malloc(nc * sizeof(JSValue)); if (l->n) memcpy(na, l->k, l->n * sizeof(JSValue)); l->k = na; l->cap = nc; }
    l->k[l->n++] = k;
}
static int idx_key_val(JSValue k) {
    if (k.tag == T_INT) return (int)k.u.i;
    double d = 0;
    if (k.tag == T_STR) js_str_to_number((const char *)str_val(k)->buf, str_val(k)->blen, &d);
    return (int)d;
}
static int is_idx(JSValue k) {
    if (k.tag == T_INT) return k.u.i >= 0;
    if (k.tag == T_STR) {
        JSString *s = str_val(k);
        if (!s->len) return 0;
        for (int i = 0; i < s->len; i++) { uint16_t c = str_unit(s, i); if (c < '0' || c > '9') return 0; }
        return 1;
    }
    return 0;
}
static int kl_find(KeyList *l, JSValue k) {
    for (int i = 0; i < l->n; i++) if (l->k[i].tag == k.tag && l->k[i].u.p == k.u.p) return i;
    return -1;
}
static void collect_keys(JSObject *o, KeyList *l, int symbols, int enum_only) {
    if (o->cls == O_ARRAY) {
        for (int i = 0; i < o->arr_len; i++) {
            if (o->arr[i].tag == T_HOLE) continue;
            char k[24]; int n = snprintf(k, sizeof k, "%d", i);
            kl_push(l, js_atom_buf((const uint8_t *)k, n, n));
        }
    }
    for (Prop *p = o->props; p; p = p->next) {
        if (enum_only && !(p->flags & P_E)) continue;
        if (symbols && p->key.tag != T_SYM) continue;
        if (!symbols && p->key.tag == T_SYM) continue;
        if (kl_find(l, p->key) >= 0) continue;
        kl_push(l, p->key);
    }
    /* sort integer keys first */
    int i = 0;
    for (int a = 0; a < l->n; a++) {
        if (is_idx(l->k[a])) { JSValue t = l->k[a]; memmove(l->k + i + 1, l->k + i, (a - i) * sizeof(JSValue)); l->k[i++] = t; }
    }
    /* sort the integer keys ascending */
    for (int a = 0; a < i; a++)
        for (int b = a + 1; b < i; b++)
            if (idx_key_val(l->k[b]) < idx_key_val(l->k[a])) { JSValue t = l->k[a]; l->k[a] = l->k[b]; l->k[b] = t; }
}
static JSValue keys_to_array(KeyList *l) {
    JSObject *a = js_new_array_obj();
    for (int i = 0; i < l->n; i++) js_array_push(a, l->k[i].tag == T_INT ? js_int_to_string(l->k[i].u.i) : l->k[i]);
    return (JSValue){ .u.p = a, .tag = T_OBJ };
}
JSValue js_object_keys_val(JSValue o, int symbols, int enum_only) {
    if (o.tag != T_OBJ) o = js_to_object(o);
    KeyList l = { 0 };
    collect_keys(obj_of(o), &l, symbols, enum_only);
    return keys_to_array(&l);
}
static JSValue own_prop_desc(JSObject *o, JSValue k) {
    Prop *p = obj_find_prop(o, k);
    JSObject *d = js_new_object(O_OBJECT);
    JSValue dv; dv.u.p = d; dv.tag = T_OBJ;
    obj_add_prop(d, js_atom("configurable"), js_bool(p->flags & P_C), P_W | P_E | P_C);
    obj_add_prop(d, js_atom("enumerable"), js_bool(p->flags & P_E), P_W | P_E | P_C);
