    int argc;
    JSValue promise;
    int is_async;
    int gen_state;
    struct Coro *next;
} Coro;

typedef struct Job {
    struct Job *next;
    int kind;          /* 0 = call fn, 1 = resolve promise, 2 = promise reaction */
    JSValue fn, arg;
    JSValue promise, val;
    JSValue on_ful, on_rej;
    int is_reject;
    Coro *coro;
} Job;

static Job *job_head, *job_tail;
static Coro *coro_head;

static void job_push(Job *j) {
    j->next = NULL;
    if (job_tail) job_tail->next = j; else job_head = j;
    job_tail = j;
}

/* ------------------------------- promises --------------------------------- */
typedef struct {
    int state;          /* 0 pending, 1 fulfilled, 2 rejected */
    JSValue result;
    int handled;
    JSValue *reac;
    int nr, rcap;
} PData;

static PData *pdata(JSValue p) { return (PData *)obj_of(p)->extra; }

static JSValue promise_obj(void) {
    JSObject *o = js_malloc(sizeof(JSObject));
    o->cls = O_PROMISE;
    o->proto = ctx->promise_proto;
    o->extensible = 1;
    PData *d = js_malloc(sizeof(PData));
    d->state = 0;
    d->result = js_undef();
