    return v;
}
static void promise_add_reaction(JSValue p, JSValue on_ful, JSValue on_rej) {
    PData *d = pdata(p);
    if (d->nr + 2 > d->rcap) {
        int nc = d->rcap ? d->rcap * 2 : 8;
        JSValue *na = js_malloc(nc * sizeof(JSValue));
        if (d->nr) memcpy(na, d->reac, d->nr * sizeof(JSValue));
