        ReNode *g = re_new(RE_GROUP);
        g->group = capturing ? ++r->ngroups : 0;
        g->body = re_parse_alt(r);
        if (r->pos < r->len && r->p[r->pos] == ')') r->pos++;
        else r->err = 1;
        return g;
    }
    case '[': return re_parse_class(r);
    case '\\': {
        uint32_t e; int n2;
        if (r->pos >= r->len) return NULL;
        e = rp_next(r, &n2);
        ReNode *nd;
        switch (e) {
        case 'd': nd = re_new(RE_CLASS); add_range(nd, '0', '9'); return nd;
        case 'D': nd = re_new(RE_CLASS); nd->negate = 1; add_range(nd, '0', '9'); return nd;
        case 'w': nd = re_new(RE_CLASS); add_range(nd, 'a', 'z'); add_range(nd, 'A', 'Z'); add_range(nd, '0', '9'); add_range(nd, '_', '_'); return nd;
        case 'W': nd = re_new(RE_CLASS); nd->negate = 1; add_range(nd, 'a', 'z'); add_range(nd, 'A', 'Z'); add_range(nd, '0', '9'); add_range(nd, '_', '_'); return nd;
        case 's': nd = re_new(RE_CLASS); add_range(nd, ' ', ' '); add_range(nd, '\t', '\r'); add_range(nd, 0xa0, 0xa0); add_range(nd, 0x2028, 0x2029); add_range(nd, 0x2000, 0x200a); add_range(nd, 0xfeff, 0xfeff); return nd;
        case 'S': nd = re_new(RE_CLASS); nd->negate = 1; add_range(nd, ' ', ' '); add_range(nd, '\t', '\r'); add_range(nd, 0xa0, 0xa0); add_range(nd, 0x2028, 0x2029); add_range(nd, 0x2000, 0x200a); add_range(nd, 0xfeff, 0xfeff); return nd;
        case 'b': return re_new(RE_WORDB);
        case 'B': return re_new(RE_NWORDB);
        case 'n': nd = re_new(RE_CHAR); nd->cp = '\n'; return nd;
        case 'r': nd = re_new(RE_CHAR); nd->cp = '\r'; return nd;
        case 't': nd = re_new(RE_CHAR); nd->cp = '\t'; return nd;
        case 'v': nd = re_new(RE_CHAR); nd->cp = 0x0b; return nd;
        case 'f': nd = re_new(RE_CHAR); nd->cp = 0x0c; return nd;
        case '0': nd = re_new(RE_CHAR); nd->cp = 0; return nd;
        case 'x': { uint32_t v = 0; for (int i = 0; i < 2 && r->pos < r->len; i++) { char h = r->p[r->pos]; int d = isxdigit((unsigned char)h) ? (isdigit((unsigned char)h) ? h - '0' : tolower((unsigned char)h) - 'a' + 10) : -1; if (d < 0) break; v = v * 16 + d; r->pos++; } nd = re_new(RE_CHAR); nd->cp = v; return nd; }
        case 'u': {
            uint32_t v = 0;
            if (r->pos < r->len && r->p[r->pos] == '{') {
                r->pos++;
                while (r->pos < r->len && r->p[r->pos] != '}') { char h = r->p[r->pos++]; int d = isxdigit((unsigned char)h) ? (isdigit((unsigned char)h) ? h - '0' : tolower((unsigned char)h) - 'a' + 10) : -1; if (d >= 0) v = v * 16 + d; }
                if (r->pos < r->len) r->pos++;
            } else for (int i = 0; i < 4 && r->pos < r->len; i++) { char h = r->p[r->pos]; int d = isxdigit((unsigned char)h) ? (isdigit((unsigned char)h) ? h - '0' : tolower((unsigned char)h) - 'a' + 10) : -1; if (d < 0) break; v = v * 16 + d; r->pos++; }
            nd = re_new(RE_CHAR); nd->cp = v; return nd;
        }
        default:
            if (e >= '1' && e <= '9') {
                nd = re_new(RE_BACKREF);
                nd->backref = e - '0';
                while (r->pos < r->len && is_digit_c((uint8_t)r->p[r->pos])) {
                    int v = nd->backref * 10 + (r->p[r->pos] - '0');
                    if (v > r->ngroups) break;
                    nd->backref = v;
                    r->pos++;
                }
                return nd;
            }
            nd = re_new(RE_CHAR); nd->cp = e; return nd;
        }
    }
    case '*': case '+': case '?': case ')': case '|':
        r->pos -= n;
        return NULL;
    case '{': {
        /* could be a quantifier start: treat as literal if not a valid quantifier */
        int save = r->pos;
        int mn = 0, mx = -1, ok = 0;
        while (r->pos < r->len && is_digit_c((uint8_t)r->p[r->pos])) { mn = mn * 10 + (r->p[r->pos] - '0'); r->pos++; }
        if (r->pos < r->len && r->p[r->pos] == ',') {
            r->pos++;
            if (r->pos < r->len && is_digit_c((uint8_t)r->p[r->pos])) { mx = 0; while (r->pos < r->len && is_digit_c((uint8_t)r->p[r->pos])) { mx = mx * 10 + (r->p[r->pos] - '0'); r->pos++; } }
            else mx = -1;
        } else mx = mn;
        if (r->pos < r->len && r->p[r->pos] == '}') { ok = 1; r->pos++; }
        if (!ok) { r->pos = save; }
        else { r->pos = save; }
        nd2:
        nd = re_new(RE_CHAR); nd->cp = '{'; return nd;
    }
    case ']': case '}':
        nd = re_new(RE_CHAR); nd->cp = c; return nd;
    default:
        nd = re_new(RE_CHAR); nd->cp = c; return nd;
    }
}

static ReNode *re_parse_term(RP *r) {
    ReNode *a = re_parse_atom(r);
    if (!a) return NULL;
    if (r->pos < r->len) {
        char c = r->p[r->pos];
        int mn = 0, mx = -1;
        int have = 0;
        if (c == '*') { mn = 0; mx = -1; have = 1; r->pos++; }
        else if (c == '+') { mn = 1; mx = -1; have = 1; r->pos++; }
        else if (c == '?') { mn = 0; mx = 1; have = 1; r->pos++; }
        else if (c == '{') {
            int save = r->pos;
            r->pos++;
            mn = 0; mx = -1;
            while (r->pos < r->len && is_digit_c((uint8_t)r->p[r->pos])) { mn = mn * 10 + (r->p[r->pos] - '0'); r->pos++; }
            if (r->pos < r->len && r->p[r->pos] == ',') {
                r->pos++;
                if (r->pos < r->len && is_digit_c((uint8_t)r->p[r->pos])) { mx = 0; while (r->pos < r->len && is_digit_c((uint8_t)r->p[r->pos])) { mx = mx * 10 + (r->p[r->pos] - '0'); r->pos++; } }
            } else mx = mn;
            if (r->pos < r->len && r->p[r->pos] == '}') { have = 1; r->pos++; }
            else r->pos = save;
        }
        if (have) {
            ReNode *rep = re_new(RE_REPEAT);
            rep->body = a;
            rep->min = mn;
            rep->max = mx;
            rep->greedy = 1;
            if (r->pos < r->len && r->p[r->pos] == '?') { rep->greedy = 0; r->pos++; }
            return rep;
        }
    }
    return a;
}
static ReNode *re_parse_seq(RP *r) {
    ReNode *first = NULL, *last = NULL;
    for (;;) {
        if (r->pos >= r->len) break;
        if (r->p[r->pos] == '|' || r->p[r->pos] == ')') break;
        ReNode *t = re_parse_term(r);
        if (!t) break;
        if (!first) first = last = t;
        else { last->alt = t; last = t; }
    }
    if (!first) return re_new(RE_EMPTY);
    /* chain via alt field as next pointer */
    ReNode *seq = re_new(RE_CAT);
    int cnt = 0;
    for (ReNode *t = first; t; t = t->alt) cnt++;
    seq->kids = js_malloc(cnt * sizeof(void*));
    seq->nk = cnt;
    int i = 0;
    for (ReNode *t = first; t; t = t->alt) seq->kids[i++] = t;
    return seq;
}
static ReNode *re_parse_alt(RP *r) {
    ReNode *first = re_parse_seq(r);
    if (r->pos < r->len && r->p[r->pos] == '|') {
        r->pos++;
        ReNode *rest = re_parse_alt(r);
        ReNode *a = re_new(RE_ALT);
        a->kids = js_malloc(2 * sizeof(void*));
        a->nk = 2;
        a->kids[0] = first;
        a->kids[1] = rest;
        return a;
    }
    return first;
}

ReNode *re_compile(const char *src, int len, int flags, int *ngroups, int *err) {
    RP r;
    r.p = src; r.pos = 0; r.len = len; r.ngroups = 0; r.flags = flags; r.err = 0;
    ReNode *root = re_parse_alt(&r);
    if (r.pos < len) r.err = 1;
    if (r.err) { *err = 1; return NULL; }
    *ngroups = r.ngroups;
    return root;
}

/* ------------------------------ matching ---------------------------------- */
static int re_unit_at(ReState *s, int pos, uint32_t *cp) {
    if (pos >= s->input->len) return 0;
    *cp = str_unit(s->input, pos);
    return 1;
}
static int cp_eq(ReState *s, uint32_t a, uint32_t b) {
    if (a == b) return 1;
    if (s->ignore_case) {
        uint32_t la = a >= 'A' && a <= 'Z' ? a + 32 : a;
        uint32_t lb = b >= 'A' && b <= 'Z' ? b + 32 : b;
        if (la == lb) return 1;
        if (a >= 0xe0 && a <= 0xfe) { if (b == a - 0x20) return 1; }
        if (a >= 0xc0 && a <= 0xde) { if (b == a + 0x20) return 1; }
        if (b >= 0xe0 && b <= 0xfe) { if (a == b - 0x20) return 1; }
        if (b >= 0xc0 && b <= 0xde) { if (a == b + 0x20) return 1; }
    }
    return 0;
}

static int re_match_seq(ReState *s, ReNode **kids, int nk, int idx, int pos, int *out);

static int re_match(ReState *s, ReNode *n, int pos, int *out) {
    if (s->backtrack_limit-- < 0) { s->failed = 1; return 0; }
    switch (n->kind) {
    case RE_EMPTY: *out = pos; return 1;
    case RE_CHAR: {
        uint32_t c;
        if (!re_unit_at(s, pos, &c)) return 0;
        int adv = c >= 0x10000 ? 2 : 1;
        if (!cp_eq(s, c, n->cp)) return 0;
        *out = pos + adv;
        return 1;
    }
    case RE_ANY: {
        uint32_t c;
        if (!re_unit_at(s, pos, &c)) return 0;
        if (!s->dotall && (c == '\n' || c == '\r' || c == 0x2028 || c == 0x2029)) return 0;
        *out = pos + (c >= 0x10000 ? 2 : 1);
        return 1;
    }
    case RE_CLASS: {
        uint32_t c;
        if (!re_unit_at(s, pos, &c)) return 0;
        int in = class_has(n, c, s->ignore_case);
        if (n->negate) in = !in;
        if (!in) return 0;
        *out = pos + (c >= 0x10000 ? 2 : 1);
        return 1;
    }
    case RE_BOL:
        if (pos == 0) { *out = pos; return 1; }
        if (s->multiline) {
            uint32_t prev;
            if (pos > 0 && re_unit_at(s, pos - 1, &prev) && (prev == '\n' || prev == '\r' || prev == 0x2028 || prev == 0x2029)) { *out = pos; return 1; }
        }
        return 0;
    case RE_EOL:
        if (pos == s->input->len) { *out = pos; return 1; }
        if (s->multiline) {
            uint32_t c;
            if (re_unit_at(s, pos, &c) && (c == '\n' || c == '\r' || c == 0x2028 || c == 0x2029)) { *out = pos; return 1; }
        }
        return 0;
    case RE_WORDB: case RE_NWORDB: {
        int before = 0, after = 0;
        if (pos > 0) { uint32_t c; if (re_unit_at(s, pos - 1, &c)) before = is_word_c(c); }
        if (pos < s->input->len) { uint32_t c; if (re_unit_at(s, pos, &c)) after = is_word_c(c); }
        int boundary = before != after;
        if ((n->kind == RE_WORDB) == boundary) { *out = pos; return 1; }
        return 0;
    }
    case RE_BACKREF: {
        int gi = n->backref;
        if (gi > s->ngroups) return 0;
        int gs = s->group_start[gi], ge = s->group_end[gi];
        if (gs < 0) { *out = pos; return 1; }
        int len = ge - gs;
        if (pos + len > s->input->len) return 0;
        for (int i = 0; i < len; i++) {
            uint32_t a = str_unit(s->input, gs + i), b = str_unit(s->input, pos + i);
            if (!cp_eq(s, a, b)) return 0;
        }
        *out = pos + len;
        return 1;
    }
    case RE_LOOKAHEAD: {
        int dummy;
        ReState save = *s;
        int ok = re_match(s, n->body, pos, &dummy);
        *s = save;
        if (n->lookahead_neg) { if (ok) return 0; *out = pos; return 1; }
        if (!ok) return 0;
        *out = pos;
        return 1;
    }
    case RE_GROUP: {
        int gi = n->group;
        int old_start = gi ? s->group_start[gi] : 0;
        int old_end = gi ? s->group_end[gi] : 0;
        int e;
        if (!re_match(s, n->body, pos, &e)) {
            if (gi) { s->group_start[gi] = old_start; s->group_end[gi] = old_end; }
            return 0;
        }
        if (gi) { s->group_start[gi] = pos; s->group_end[gi] = e; }
        *out = e;
        return 1;
    }
    case RE_CAT:
        return re_match_seq(s, n->kids, n->nk, 0, pos, out);
    case RE_ALT: {
        int e;
        if (re_match(s, n->kids[0], pos, &e)) { *out = e; return 1; }
        return re_match(s, n->kids[1], pos, out);
    }
    case RE_REPEAT: {
        /* recursive expansion */
        int count = 0;
        int max = n->max;
        /* greedy: try to match as many as possible */
        if (n->greedy) {
            /* try longer first */
            int e;
            /* iterative: match as many as possible then backtrack */
            int positions[1024];
            int np = 0;
            int p = pos;
            positions[np++] = p;
            while ((max < 0 || count < max) && np < 1024) {
                if (count < n->min) {
                    if (!re_match(s, n->body, p, &e)) { s->failed = 1; return 0; }
                    p = e;
                    count++;
                    positions[np++] = p;
                } else {
                    int save_limit = s->backtrack_limit;
                    if (!re_match(s, n->body, p, &e)) { break; }
                    if (e == p) break; /* empty match: stop */
                    p = e;
                    count++;
                    positions[np++] = p;
                    s->backtrack_limit = save_limit;
                }
            }
            if (count < n->min) { s->failed = 1; return 0; }
            for (int i = np - 1; i >= 0; i--) {
                int dummy;
                if (i < n->min) break;
                if (re_match_seq(s, NULL, 0, 0, positions[i], &dummy)) { *out = positions[i]; return 1; }
                (void)dummy;
            }
            return 0;
        } else {
            int p = pos;
            int count2 = 0;
            while (count2 < n->min) {
                int e;
                if (!re_match(s, n->body, p, &e)) { s->failed = 1; return 0; }
                if (e == p && count2 + 1 <= n->min) { break; }
                p = e;
                count2++;
            }
            if (count2 < n->min) { s->failed = 1; return 0; }
            for (;;) {
                int dummy;
                if (re_match_seq(s, NULL, 0, 0, p, &dummy)) { *out = p; return 1; }
                if (max >= 0 && count2 >= max) return 0;
                int e;
                int save_limit = s->backtrack_limit;
                if (!re_match(s, n->body, p, &e)) return 0;
                if (e == p) return 0;
                p = e;
                count2++;
                s->backtrack_limit = save_limit;
            }
        }
    }
    }
    return 0;
}

static int re_match_seq(ReState *s, ReNode **kids, int nk, int idx, int pos, int *out) {
    (void)kids; (void)nk;
    (void)idx; (void)pos; (void)out;
    return 0;
}
