#include "internal.h"
#include <math.h>

/* ------------------------- regular expressions ----------------------------- */
typedef struct ReNode ReNode;
enum { RE_CHAR, RE_CLASS, RE_ANY, RE_CAT, RE_ALT, RE_GROUP, RE_BACKREF, RE_BOL, RE_EOL,
       RE_WORDB, RE_NWORDB, RE_LOOKAHEAD, RE_REPEAT, RE_EMPTY };
struct ReNode {
    int kind;
    uint32_t cp;         /* RE_CHAR */
    uint32_t *set;       /* RE_CLASS bitmap (128 bytes = 1024 bits) */
    int nset, setcap;    /* ranges */
    ReNode **kids;
    int nk;
    int min, max;        /* RE_REPEAT */
    int greedy;
    int group;           /* RE_GROUP index (0 = non capturing) */
    int backref;         /* index */
    int negate;
    int lookahead_neg;
    ReNode *body;
    ReNode *alt;
};

typedef struct {
    ReNode *root;
    int ngroups;
    int flags;
    JSString *input;
    int pos;
    int *group_start, *group_end;
    int ngroups_alloc;
    int backtrack_limit;
    int failed;
    int multiline;
    int ignore_case;
    int dotall;
    int sticky;
    int unicode;
} ReState;

static int re_match(ReState *s, ReNode *n, int pos, int *out);

static ReNode *re_new(int kind) {
    ReNode *n = js_malloc(sizeof(ReNode));
    memset(n, 0, sizeof(ReNode));
    n->kind = kind;
    n->max = -1;
    return n;
}

typedef struct { const char *p; int pos, len; int ngroups; int flags; int err; } RP;

static uint32_t rp_next(RP *r, int *n) {
    if (r->pos >= r->len) { *n = 0; return 0; }
    uint32_t cp; int k = js_utf8_decode((const uint8_t *)r->p + r->pos, r->len - r->pos, &cp);
    if (k < 0) { cp = (uint8_t)r->p[r->pos]; k = 1; }
    r->pos += k;
    *n = k;
    return cp;
}
static void add_range(ReNode *n, uint32_t a, uint32_t b) {
    if (n->nset + 2 > n->setcap) {
        int nc = n->setcap ? n->setcap * 2 : 8;
        uint32_t *ns = js_malloc(nc * sizeof(uint32_t));
        if (n->nset) memcpy(ns, n->set, n->nset * sizeof(uint32_t));
        n->set = ns; n->setcap = nc;
    }
    n->set[n->setcap - 2 + 0] = 0; (void)0;
    n->set[n->nset++] = a;
    n->set[n->nset++] = b;
}
static int class_has(ReNode *n, uint32_t c, int ignore_case) {
    for (int i = 0; i + 1 < n->nset; i += 2)
        if (c >= n->set[i] && c <= n->set[i+1]) return 1;
    if (ignore_case) {
        uint32_t lo = c >= 'A' && c <= 'Z' ? c + 32 : c >= 'a' && c <= 'z' ? c - 32 : c;
        if (lo != c) {
            for (int i = 0; i + 1 < n->nset; i += 2)
                if (lo >= n->set[i] && lo <= n->set[i+1]) return 1;
        }
    }
    return 0;
}
static int is_digit_c(uint32_t c) { return c >= '0' && c <= '9'; }
static int is_word_c(uint32_t c) { return is_digit_c(c) || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'; }
static int is_space_c(uint32_t c) {
    switch (c) { case ' ': case '\t': case '\n': case '\r': case '\f': case 0x0b: case 0xa0: case 0x2028: case 0x2029: case 0xfeff: return 1; default: return c >= 0x2000 && c <= 0x200a; }
}

static ReNode *re_parse_alt(RP *r);

static ReNode *re_parse_class(RP *r) {
    ReNode *n = re_new(RE_CLASS);
    int neg = 0;
    if (r->pos < r->len && r->p[r->pos] == '^') { neg = 1; r->pos++; }
    n->negate = neg;
    int first = 1;
    while (r->pos < r->len && (r->p[r->pos] != ']' || first)) {
        first = 0;
        uint32_t c; int n2;
        if (r->p[r->pos] == '\\') {
            r->pos++;
            c = rp_next(r, &n2);
            switch (c) {
            case 'd': add_range(n, '0', '9'); continue;
            case 'D': { ReNode *tmp = re_new(RE_CLASS); add_range(tmp, '0', '9'); for (uint32_t q = 0; q < 0x110000; q++) if (!class_has(tmp, q, 0) && q < 0x10000) add_range(n, q, q); continue; }
            case 'w': add_range(n, 'a', 'z'); add_range(n, 'A', 'Z'); add_range(n, '0', '9'); add_range(n, '_', '_'); continue;
            case 'W': { for (uint32_t q = 0; q < 0x10000; q++) if (!is_word_c(q)) add_range(n, q, q); continue; }
            case 's': add_range(n, ' ', ' '); add_range(n, '\t', '\r'); add_range(n, 0xa0, 0xa0); add_range(n, 0x2028, 0x2029); add_range(n, 0xfeff, 0xfeff); add_range(n, 0x2000, 0x200a); continue;
            case 'S': { for (uint32_t q = 0; q < 0x10000; q++) if (!is_space_c(q)) add_range(n, q, q); continue; }
            case 'n': c = '\n'; break;
            case 'r': c = '\r'; break;
            case 't': c = '\t'; break;
            case 'b': c = '\b'; break;
            case 'v': c = 0x0b; break;
            case 'f': c = 0x0c; break;
            case '0': c = 0; break;
            case 'x': { uint32_t v = 0; for (int i = 0; i < 2 && r->pos < r->len; i++) { char h = r->p[r->pos]; int d = isxdigit((unsigned char)h) ? (isdigit((unsigned char)h) ? h - '0' : tolower((unsigned char)h) - 'a' + 10) : -1; if (d < 0) break; v = v * 16 + d; r->pos++; } c = v; break; }
            case 'u': {
                if (r->pos < r->len && r->p[r->pos] == '{') {
                    r->pos++;
                    uint32_t v = 0;
                    while (r->pos < r->len && r->p[r->pos] != '}') { char h = r->p[r->pos++]; int d = isxdigit((unsigned char)h) ? (isdigit((unsigned char)h) ? h - '0' : tolower((unsigned char)h) - 'a' + 10) : -1; if (d >= 0) v = v * 16 + d; }
                    if (r->pos < r->len) r->pos++;
                    c = v;
                } else {
                    uint32_t v = 0;
                    for (int i = 0; i < 4 && r->pos < r->len; i++) { char h = r->p[r->pos]; int d = isxdigit((unsigned char)h) ? (isdigit((unsigned char)h) ? h - '0' : tolower((unsigned char)h) - 'a' + 10) : -1; if (d < 0) break; v = v * 16 + d; r->pos++; }
                    c = v;
                }
                break;
            }
            default: break;
            }
        } else {
