static int re_unit_at(ReState *s, int pos, uint32_t *cp) {
    if (pos >= s->input->len) return 0;
    *cp = str_unit(s->input, pos);
    return 1;
}
static int cp_eq(ReState *s, uint32_t a, uint32_t b) {
