    case 'D': add_range(n, SP_NDIGIT, SP_NDIGIT); break;
    case 'w': add_range(n, SP_WORD, SP_WORD); break;
    case 'W': add_range(n, SP_NWORD, SP_NWORD); break;
    case 's': add_range(n, SP_SPACE, SP_SPACE); break;
    case 'S': add_range(n, SP_NSPACE, SP_NSPACE); break;
    }
}

static ReNode *re_parse_alt(RP *r);

static uint32_t esc_char(RP *r, uint32_t e, int *ok) {
    *ok = 1;
    switch (e) {
    case 'n': return '\n';
    case 'r': return '\r';
    case 't': return '\t';
    case 'b': return '\b';
    case 'v': return 0x0b;
    case 'f': return 0x0c;
    case '0': return 0;
    case 'x': {
        uint32_t v = 0;
        for (int i = 0; i < 2 && r->pos < r->len; i++) {
            char h = r->p[r->pos];
            int d = isxdigit((unsigned char)h) ? (isdigit((unsigned char)h) ? h - '0' : tolower((unsigned char)h) - 'a' + 10) : -1;
            if (d < 0) break;
            v = v * 16 + d; r->pos++;
        }
        return v;
    }
    case 'u': {
        uint32_t v = 0;
        if (r->pos < r->len && r->p[r->pos] == '{') {
            r->pos++;
            while (r->pos < r->len && r->p[r->pos] != '}') {
                char h = r->p[r->pos++];
                int d = isxdigit((unsigned char)h) ? (isdigit((unsigned char)h) ? h - '0' : tolower((unsigned char)h) - 'a' + 10) : -1;
                if (d >= 0) v = v * 16 + d;
            }
            if (r->pos < r->len) r->pos++;
        } else {
            for (int i = 0; i < 4 && r->pos < r->len; i++) {
                char h = r->p[r->pos];
                int d = isxdigit((unsigned char)h) ? (isdigit((unsigned char)h) ? h - '0' : tolower((unsigned char)h) - 'a' + 10) : -1;
                if (d < 0) break;
                v = v * 16 + d; r->pos++;
            }
        }
        return v;
    }
    case 'c': {
        if (r->pos < r->len) { char c = r->p[r->pos++]; return (uint32_t)(toupper((unsigned char)c)) ^ 0x40; }
        return 0;
    }
    default: *ok = 0; return e;
    }
}

static ReNode *re_parse_class(RP *r) {
    ReNode *n = re_new(RE_CLASS);
    if (r->pos < r->len && r->p[r->pos] == '^') { n->negate = 1; r->pos++; }
    int first = 1;
    while (r->pos < r->len && (r->p[r->pos] != ']' || first)) {
        first = 0;
        uint32_t c; int n2, ok;
        if (r->p[r->pos] == '\\') {
            r->pos++;
            if (r->pos >= r->len) { r->err = 1; return n; }
            c = rp_next2(r, &n2);
            add_escape_class(n, c);
            if (c == 'd' || c == 'D' || c == 'w' || c == 'W' || c == 's' || c == 'S') continue;
            c = esc_char(r, c, &ok);
        } else {
            c = rp_next2(r, &n2);
        }
        if (r->pos < r->len && r->p[r->pos] == '-' && r->pos + 1 < r->len && r->p[r->pos+1] != ']') {
            r->pos++;
            uint32_t c2; int n3, ok2;
            if (r->p[r->pos] == '\\') { r->pos++; c2 = rp_next2(r, &n3); add_escape_class(n, c2); if (c2=='d'||c2=='D'||c2=='w'||c2=='W'||c2=='s'||c2=='S') { add_range(n, c, c); continue; } c2 = esc_char(r, c2, &ok2); }
            else c2 = rp_next2(r, &n3);
            add_range(n, c, c2);
        } else add_range(n, c, c);
    }
    if (r->pos < r->len && r->p[r->pos] == ']') r->pos++;
    else r->err = 1;
    return n;
}

static ReNode *re_parse_atom(RP *r) {
    if (r->pos >= r->len) return NULL;
    uint32_t c; int n, ok;
    if (r->p[r->pos] == '\\') {
        r->pos++;
        if (r->pos >= r->len) { r->err = 1; return NULL; }
        uint32_t e = rp_next2(r, &n);
        switch (e) {
        case 'd': case 'D': case 'w': case 'W': case 's': case 'S': {
            ReNode *nd = re_new(RE_CLASS);
            add_escape_class(nd, e);
            return nd;
        }
        case 'b': return re_new(RE_WORDB);
        case 'B': return re_new(RE_NWORDB);
        default: {
            if (e >= '1' && e <= '9') {
                ReNode *nd = re_new(RE_BACKREF);
                nd->backref = e - '0';
                while (r->pos < r->len && is_digit_c((uint8_t)r->p[r->pos])) {
                    int v = nd->backref * 10 + (r->p[r->pos] - '0');
                    if (v > r->ngroups) break;
                    nd->backref = v;
                    r->pos++;
                }
                return nd;
            }
            ReNode *nd = re_new(RE_CHAR);
            nd->cp = esc_char(r, e, &ok);
            return nd;
        }
        }
    }
    c = rp_next2(r, &n);
    switch (c) {
    case '^': return re_new(RE_BOL);
    case '$': return re_new(RE_EOL);
    case '.': return re_new(RE_ANY);
    case '(': {
        int capturing = 1, neg = 0, la = 0;
        if (r->pos + 1 < r->len && r->p[r->pos] == '?') {
            if (r->p[r->pos+1] == ':') { capturing = 0; r->pos += 2; }
            else if (r->p[r->pos+1] == '=') { la = 1; neg = 0; r->pos += 2; }
            else if (r->p[r->pos+1] == '!') { la = 1; neg = 1; r->pos += 2; }
            else { r->err = 1; return NULL; }
        }
        if (la) {
            ReNode *g = re_new(RE_LOOKAHEAD);
            g->lookahead_neg = neg;
            g->body = re_parse_alt(r);
            if (r->pos < r->len && r->p[r->pos] == ')') r->pos++;
            else r->err = 1;
            return g;
        }
        ReNode *g = re_new(RE_GROUP);
        g->group = capturing ? ++r->ngroups : 0;
        g->body = re_parse_alt(r);
        if (r->pos < r->len && r->p[r->pos] == ')') r->pos++;
        else r->err = 1;
        return g;
    }
    case '[': return re_parse_class(r);
    case '*': case '+': case '?': case ')': case '|':
        r->pos -= n;
        return NULL;
    case '{': case '}': case ']': {
        ReNode *nd = re_new(RE_CHAR);
        nd->cp = c;
        return nd;
    }
    default: {
        ReNode *nd = re_new(RE_CHAR);
        nd->cp = c;
        return nd;
    }
    }
}

static ReNode *re_parse_term(RP *r) {
    ReNode *a = re_parse_atom(r);
    if (!a) return NULL;
    if (r->pos < r->len) {
        char c = r->p[r->pos];
        int mn = 0, mx = -1, have = 0;
        if (c == '*') { mn = 0; mx = -1; have = 1; r->pos++; }
        else if (c == '+') { mn = 1; mx = -1; have = 1; r->pos++; }
        else if (c == '?') { mn = 0; mx = 1; have = 1; r->pos++; }
        else if (c == '{') {
            int save = r->pos;
            r->pos++;
            mn = 0; mx = -1;
            int anyd = 0;
            while (r->pos < r->len && is_digit_c((uint8_t)r->p[r->pos])) { mn = mn * 10 + (r->p[r->pos] - '0'); r->pos++; anyd = 1; }
            if (r->pos < r->len && r->p[r->pos] == ',') {
                r->pos++;
                if (r->pos < r->len && is_digit_c((uint8_t)r->p[r->pos])) { mx = 0; while (r->pos < r->len && is_digit_c((uint8_t)r->p[r->pos])) { mx = mx * 10 + (r->p[r->pos] - '0'); r->pos++; } }
            } else { if (!anyd) { r->pos = save; return a; } mx = mn; }
            if (r->pos < r->len && r->p[r->pos] == '}') { have = 1; r->pos++; }
            else { r->pos = save; return a; }
        }
        if (have) {
            if (a->kind == RE_BOL || a->kind == RE_EOL || a->kind == RE_WORDB || a->kind == RE_NWORDB) return a;
            ReNode *rep = re_new(RE_REPEAT);
            rep->body = a;
            rep->min = mn;
            rep->max = mx;
            rep->greedy = 1;
            if (r->pos < r->len && r->p[r->pos] == '?') { rep->greedy = 0; r->pos++; }
            return rep;
        }
    }
    return a;
}
static ReNode *re_parse_seq(RP *r) {
    ReNode *first = NULL, *last = NULL;
    for (;;) {
        if (r->pos >= r->len) break;
        if (r->p[r->pos] == '|' || r->p[r->pos] == ')') break;
        ReNode *t = re_parse_term(r);
        if (!t) break;
        if (!first) first = last = t;
        else { last->link = t; last = t; }
    }
    if (!first) return re_new(RE_EMPTY);
    ReNode *seq = re_new(RE_CAT);
    for (ReNode *t = first; t; t = t->link) re_addkid(seq, t);
    return seq;
}
static ReNode *re_parse_alt(RP *r) {
    ReNode *first = re_parse_seq(r);
    if (r->pos < r->len && r->p[r->pos] == '|') {
        r->pos++;
        ReNode *rest = re_parse_alt(r);
        ReNode *a = re_new(RE_ALT);
        re_addkid(a, first);
        re_addkid(a, rest);
        return a;
    }
    return first;
}

ReNode *re_compile(const char *src, int len, int flags, int *ngroups, int *err) {
    RP r;
    r.p = src; r.pos = 0; r.len = len; r.ngroups = 0; r.err = 0;
    ReNode *root = re_parse_alt(&r);
    if (r.pos < len) r.err = 1;
    if (r.err) { *err = 1; return NULL; }
    *ngroups = r.ngroups;
    return root;
}

/* ------------------------------- matching --------------------------------- */
typedef struct Next {
    ReNode *node;
    ReNode **kids;
    int nk, idx;
    struct Next *next;
} Next;

typedef struct {
    JSString *input;
    int len;
    int *gs, *ge;
    int ngroups;
    int multiline, ignore_case, dotall, sticky, unicode;
    int budget;
} ReState;

static int m(ReState *s, ReNode *n, Next *nx, int pos, int *out);
static int m_next(ReState *s, Next *nx, int pos, int *out) {
    if (!nx) { *out = pos; return 1; }
    if (nx->node) return m(s, nx->node, nx->next, pos, out);
    /* sequence continuation */
    if (nx->idx >= nx->nk) return m_next(s, nx->next, pos, out);
    Next sub;
    sub.node = nx->kids[nx->idx];
    sub.kids = NULL;
    sub.idx = 0; sub.nk = 0;
    sub.next = nx;
    return m(s, sub.node, &sub, pos, out);
}

static int cp_eq(ReState *s, uint32_t a, uint32_t b) {
    if (a == b) return 1;
    if (s->ignore_case) {
        uint32_t la = a, lb = b;
        if (la >= 'A' && la <= 'Z') la += 32;
        if (la >= 0xc0 && la <= 0xde) la += 0x20;
        if (lb >= 'A' && lb <= 'Z') lb += 32;
        if (lb >= 0xc0 && lb <= 0xde) lb += 0x20;
        if (la == lb) return 1;
    }
    return 0;
}
static int class_has(ReNode *n, uint32_t c, int ic) {
    int in = 0;
    for (int i = 0; i + 1 < n->nset; i += 2) {
        uint32_t a = n->set[i], b = n->set[i+1];
        if (a == SP_DIGIT) { if (is_digit_c(c)) { in = 1; break; } continue; }
        if (a == SP_NDIGIT) { if (!is_digit_c(c)) { in = 1; break; } continue; }
        if (a == SP_WORD) { if (is_word_c(c)) { in = 1; break; } continue; }
        if (a == SP_NWORD) { if (!is_word_c(c)) { in = 1; break; } continue; }
        if (a == SP_SPACE) { if (is_space_c(c)) { in = 1; break; } continue; }
        if (a == SP_NSPACE) { if (!is_space_c(c)) { in = 1; break; } continue; }
        if (c >= a && c <= b) { in = 1; break; }
        if (ic) {
            uint32_t lo = c;
            if (lo >= 'A' && lo <= 'Z') lo += 32;
            if (lo >= 0xc0 && lo <= 0xde) lo += 0x20;
            if (lo != c && lo >= a && lo <= b) { in = 1; break; }
            uint32_t up = c;
            if (up >= 'a' && up <= 'z') up -= 32;
            if (up >= 0xe0 && up <= 0xfe) up -= 0x20;
            if (up != c && up >= a && up <= b) { in = 1; break; }
        }
    }
    return n->negate ? !in : in;
}

static int m(ReState *s, ReNode *n, Next *nx, int pos, int *out) {
    if (--s->budget < 0) return 0;
    switch (n->kind) {
    case RE_EMPTY: return m_next(s, nx, pos, out);
    case RE_CHAR: {
        if (pos >= s->len) return 0;
        uint32_t c = str_unit(s->input, pos);
        int adv = c >= 0x10000 ? 2 : 1;
        if (!cp_eq(s, c, n->cp)) return 0;
        return m_next(s, nx, pos + adv, out);
    }
    case RE_ANY: {
        if (pos >= s->len) return 0;
        uint32_t c = str_unit(s->input, pos);
        if (!s->dotall && (c == '\n' || c == '\r' || c == 0x2028 || c == 0x2029)) return 0;
        return m_next(s, nx, pos + (c >= 0x10000 ? 2 : 1), out);
    }
    case RE_CLASS: {
        if (pos >= s->len) return 0;
        uint32_t c = str_unit(s->input, pos);
        if (!class_has(n, c, s->ignore_case)) return 0;
        return m_next(s, nx, pos + (c >= 0x10000 ? 2 : 1), out);
    }
    case RE_BOL:
        if (pos == 0) return m_next(s, nx, pos, out);
        if (s->multiline && pos > 0) {
            uint32_t prev = str_unit(s->input, pos - 1);
            if (prev == '\n' || prev == '\r' || prev == 0x2028 || prev == 0x2029) return m_next(s, nx, pos, out);
        }
        return 0;
    case RE_EOL:
        if (pos == s->len) return m_next(s, nx, pos, out);
        if (s->multiline) {
            uint32_t c = str_unit(s->input, pos);
            if (c == '\n' || c == '\r' || c == 0x2028 || c == 0x2029) return m_next(s, nx, pos, out);
        }
        return 0;
    case RE_WORDB: case RE_NWORDB: {
        int before = 0, after = 0;
        if (pos > 0) before = is_word_c(str_unit(s->input, pos - 1));
        if (pos < s->len) after = is_word_c(str_unit(s->input, pos));
        int boundary = before != after;
        if ((n->kind == RE_WORDB) != boundary) return 0;
        return m_next(s, nx, pos, out);
    }
    case RE_BACKREF: {
        int gi = n->backref;
        if (gi > s->ngroups) return 0;
        int gs = s->gs[gi], ge = s->ge[gi];
        if (gs < 0) return m_next(s, nx, pos, out);
        int len = ge - gs;
        if (pos + len > s->len) return 0;
        for (int i = 0; i < len; i++)
            if (!cp_eq(s, str_unit(s->input, gs + i), str_unit(s->input, pos + i))) return 0;
        return m_next(s, nx, pos + len, out);
    }
    case RE_LOOKAHEAD: {
        Next empty;
        empty.node = NULL; empty.kids = NULL; empty.idx = 0; empty.nk = 0; empty.next = NULL;
        int e;
        int save_budget = s->budget;
        int ok = m(s, n->body, &empty, pos, &e);
        s->budget = save_budget;
        if (n->lookahead_neg) { if (ok) return 0; return m_next(s, nx, pos, out); }
        if (!ok) return 0;
        return m_next(s, nx, pos, out);
    }
    case RE_GROUP: {
        int gi = n->group;
        int old_s = gi ? s->gs[gi] : 0, old_e = gi ? s->ge[gi] : 0;
        int e;
        if (!m(s, n->body, nx, pos, &e)) {
            if (gi) { s->gs[gi] = old_s; s->ge[gi] = old_e; }
            return 0;
        }
        if (gi) { s->gs[gi] = pos; s->ge[gi] = e; }
        return 1;
    }
    case RE_CAT: {
        Next seq;
        seq.node = NULL;
        seq.kids = n->kids;
        seq.nk = n->nk;
        seq.idx = 0;
        seq.next = nx;
        return m_next(s, &seq, pos, out);
    }
    case RE_ALT: {
        int e;
        if (m(s, n->kids[0], nx, pos, &e)) { *out = e; return 1; }
        return m(s, n->kids[1], nx, pos, out);
    }
    case RE_REPEAT: {
        int max = n->max;
        if (n->greedy) {
            /* try to consume as many as possible, then backtrack */
            int cap = 64, cnt = 0;
            int *positions = js_malloc(cap * sizeof(int));
            positions[cnt++] = pos;
            int p = pos;
            while (max < 0 || cnt - 1 < max) {
                int e;
                int save_budget = s->budget;
                if (!m(s, n->body, NULL, p, &e)) { s->budget = save_budget; break; }
                s->budget = save_budget;
                if (e == p) break;
                p = e;
                if (cnt == cap) { int nc = cap * 2; int *np = js_malloc(nc * sizeof(int)); memcpy(np, positions, cnt * sizeof(int)); positions = np; cap = nc; }
                positions[cnt++] = p;
            }
            for (int i = cnt - 1; i >= 0; i--) {
                if (i < n->min) break;
                if (m_next(s, nx, positions[i], out)) return 1;
            }
            return 0;
        } else {
            int p = pos;
            int cnt = 0;
            while (cnt < n->min) {
                int e;
                if (!m(s, n->body, NULL, p, &e)) return 0;
                if (e == p) { /* empty match */ break; }
                p = e;
                cnt++;
            }
            if (cnt < n->min) return 0;
            for (;;) {
                if (m_next(s, nx, p, out)) return 1;
                if (max >= 0 && cnt >= max) return 0;
                int e;
                if (!m(s, n->body, NULL, p, &e)) return 0;
                if (e == p) return 0;
                p = e;
                cnt++;
            }
        }
    }
    }
    return 0;
}

/* --------------------------- RegExp object -------------------------------- */
typedef struct { ReNode *root; int ngroups; int flags; int global, sticky; JSValue source; } ReData;

static ReData *redata(JSValue re) { return (ReData *)obj_of(re)->extra; }

JSValue js_regexp_new(JSValue src, JSValue flags, int pos) {
    (void)pos;
    JSObject *o = js_malloc(sizeof(JSObject));
    o->cls = O_REGEXP;
    o->proto = ctx->regexp_proto;
    o->extensible = 1;
    ReData *d = js_malloc(sizeof(ReData));
    o->extra = d;
    JSValue v; v.u.p = o; v.tag = T_OBJ;
    JSValue sv;
    if (src.tag == T_OBJ && obj_of(src)->cls == O_REGEXP) {
        sv = js_regexp_get_source(src);
        if (flags.tag == T_UNDEF) flags = js_regexp_get_flags(src);
    } else if (src.tag == T_UNDEF) sv = js_atom("(?:)");
    else sv = js_to_string_v(src);
    JSValue fv = flags.tag == T_UNDEF ? js_atom("") : js_to_string_v(flags);
    const char *fs = (const char *)str_val(fv)->buf;
    int fl = 0;
    for (int i = 0; fs[i]; i++) {
        switch (fs[i]) {
        case 'g': fl |= 1; break;
        case 'i': fl |= 2; break;
        case 'm': fl |= 4; break;
        case 's': fl |= 8; break;
        case 'u': fl |= 16; break;
        case 'y': fl |= 32; break;
        case 'd': fl |= 64; break;
        default: js_throw_error(ERR_SYNTAX, "invalid regular expression flags");
        }
    }
    d->flags = fl;
    d->global = (fl & 1) != 0;
    d->sticky = (fl & 32) != 0;
    d->source = sv;
    int err = 0;
    d->root = re_compile((const char *)str_val(sv)->buf, str_val(sv)->blen, fl, &d->ngroups, &err);
    if (err || !d->root) {
        js_throw_error(ERR_SYNTAX, "invalid regular expression");
    }
    obj_add_prop(o, js_atom("lastIndex"), js_int(0), P_W | P_C);
    obj_add_prop(o, js_atom("source"), sv, P_W | P_C);
    obj_add_prop(o, js_atom("flags"), fv, P_W | P_C);
    obj_add_prop(o, js_atom("global"), js_bool(d->global), P_W | P_C);
    obj_add_prop(o, js_atom("ignoreCase"), js_bool((fl & 2) != 0), P_W | P_C);
    obj_add_prop(o, js_atom("multiline"), js_bool((fl & 4) != 0), P_W | P_C);
    obj_add_prop(o, js_atom("dotAll"), js_bool((fl & 8) != 0), P_W | P_C);
    obj_add_prop(o, js_atom("unicode"), js_bool((fl & 16) != 0), P_W | P_C);
    obj_add_prop(o, js_atom("sticky"), js_bool(d->sticky), P_W | P_C);
    obj_add_prop(o, ctx->sym_tostringtag, js_atom("RegExp"), P_W | P_C);
    return v;
}
JSValue js_regexp_get_source(JSValue re) { return redata(re)->source; }
JSValue js_regexp_get_flags(JSValue re) {
    JSValue f = obj_get_prop(obj_of(re), js_atom("flags"), 0);
    return f.tag == T_STR ? f : js_atom("");
}
JSValue js_regexp_get_lastindex(JSValue re) { return obj_get_prop(obj_of(re), js_atom("lastIndex"), 0); }
void js_regexp_set_lastindex(JSValue re, JSValue v) { obj_set_prop(obj_of(re), js_atom("lastIndex"), v, 0, 0); }

/* build the result array from a match */
static JSValue build_match_result(ReState *s, int start, int end) {
    JSObject *a = js_new_array_obj();
    for (int i = 0; i <= s->ngroups; i++) {
        if (i == 0) js_array_push(a, js_substring(s->input, start, end));
        else if (s->gs[i] >= 0) js_array_push(a, js_substring(s->input, s->gs[i], s->ge[i]));
        else js_array_push(a, js_undef());
    }
    obj_add_prop(a, js_atom("index"), js_int(start), P_W | P_E | P_C);
    obj_add_prop(a, js_atom("input"), (JSValue){ .u.p = (void*)s->input, .tag = T_STR }, P_W | P_E | P_C);
    obj_add_prop(a, js_atom("groups"), js_undef(), P_W | P_E | P_C);
    return (JSValue){ .u.p = a, .tag = T_OBJ };
}

JSValue js_regexp_exec(JSValue re, JSValue str, int pos, int *is_match, int *last_index_out) {
    (void)pos;
    ReData *d = redata(re);
    JSString *s = str_val(str);
    int start = 0;
    if (d->global || d->sticky) {
        JSValue li = js_regexp_get_lastindex(re);
        start = (int)js_to_number(li);
        if (start < 0) start = 0;
        if (start > s->len) {
            if (d->global) js_regexp_set_lastindex(re, js_int(0));
            if (is_match) *is_match = 0;
            return js_null();
        }
    }
    ReState st;
    memset(&st, 0, sizeof(st));
    st.input = s;
    st.len = s->len;
    st.ngroups = d->ngroups;
    st.multiline = (d->flags & 4) != 0;
    st.ignore_case = (d->flags & 2) != 0;
    st.dotall = (d->flags & 8) != 0;
    st.sticky = d->sticky;
    st.unicode = (d->flags & 16) != 0;
    st.gs = js_malloc((d->ngroups + 1) * sizeof(int));
    st.ge = js_malloc((d->ngroups + 1) * sizeof(int));
    for (int i = 0; i <= d->ngroups; i++) { st.gs[i] = -1; st.ge[i] = -1; }
    st.budget = 2000000;
    int found = 0, mstart = 0, mend = 0;
    for (int p = start; p <= s->len; p++) {
        int out;
        st.budget = 2000000;
        Next empty;
        empty.node = NULL; empty.kids = NULL; empty.idx = 0; empty.nk = 0; empty.next = NULL;
        if (m(&st, d->root, &empty, p, &out)) {
            found = 1;
            mstart = p;
            mend = out;
            break;
        }
        if (st.budget < 0) break;
        if (d->sticky) break;
    }
    if (!found) {
        if (d->global || d->sticky) js_regexp_set_lastindex(re, js_int(0));
        if (is_match) *is_match = 0;
        return js_null();
    }
    if (d->global || d->sticky) js_regexp_set_lastindex(re, js_int(mend));
    if (is_match) *is_match = 1;
    if (last_index_out) *last_index_out = mend;
    return build_match_result(&st, mstart, mend);
}
JSValue js_regexp_test(JSValue re, JSValue str, int pos) {
    int m = 0;
    js_regexp_exec(re, str, pos, &m, NULL);
    return js_bool(m);
}
