        if (a == SP_SPACE) { if (is_space_c(c)) { in = 1; break; } continue; }
        if (a == SP_NSPACE) { if (!is_space_c(c)) { in = 1; break; } continue; }
        if (c >= a && c <= b) { in = 1; break; }
        if (ic) {
            uint32_t lo = c;
            if (lo >= 'A' && lo <= 'Z') lo += 32;
            if (lo >= 0xc0 && lo <= 0xde) lo += 0x20;
            if (lo != c && lo >= a && lo <= b) { in = 1; break; }
            uint32_t up = c;
            if (up >= 'a' && up <= 'z') up -= 32;
            if (up >= 0xe0 && up <= 0xfe) up -= 0x20;
            if (up != c && up >= a && up <= b) { in = 1; break; }
        }
    }
    return n->negate ? !in : in;
}

static int m(ReState *s, ReNode *n, Next *nx, int pos, int *out) {
    if (--s->budget < 0) return 0;
    switch (n->kind) {
    case RE_EMPTY: return m_next(s, nx, pos, out);
    case RE_CHAR: {
        if (pos >= s->len) return 0;
        uint32_t c = str_unit(s->input, pos);
        int adv = c >= 0x10000 ? 2 : 1;
        if (!cp_eq(s, c, n->cp)) return 0;
        return m_next(s, nx, pos + adv, out);
    }
    case RE_ANY: {
        if (pos >= s->len) return 0;
        uint32_t c = str_unit(s->input, pos);
        if (!s->dotall && (c == '\n' || c == '\r' || c == 0x2028 || c == 0x2029)) return 0;
        return m_next(s, nx, pos + (c >= 0x10000 ? 2 : 1), out);
    }
    case RE_CLASS: {
        if (pos >= s->len) return 0;
        uint32_t c = str_unit(s->input, pos);
        if (!class_has(n, c, s->ignore_case)) return 0;
        return m_next(s, nx, pos + (c >= 0x10000 ? 2 : 1), out);
    }
    case RE_BOL:
        if (pos == 0) return m_next(s, nx, pos, out);
        if (s->multiline && pos > 0) {
            uint32_t prev = str_unit(s->input, pos - 1);
            if (prev == '\n' || prev == '\r' || prev == 0x2028 || prev == 0x2029) return m_next(s, nx, pos, out);
        }
        return 0;
    case RE_EOL:
        if (pos == s->len) return m_next(s, nx, pos, out);
        if (s->multiline) {
            uint32_t c = str_unit(s->input, pos);
            if (c == '\n' || c == '\r' || c == 0x2028 || c == 0x2029) return m_next(s, nx, pos, out);
        }
        return 0;
    case RE_WORDB: case RE_NWORDB: {
        int before = 0, after = 0;
        if (pos > 0) before = is_word_c(str_unit(s->input, pos - 1));
        if (pos < s->len) after = is_word_c(str_unit(s->input, pos));
        int boundary = before != after;
        if ((n->kind == RE_WORDB) != boundary) return 0;
        return m_next(s, nx, pos, out);
    }
    case RE_BACKREF: {
        int gi = n->backref;
        if (gi > s->ngroups) return 0;
        int gs = s->gs[gi], ge = s->ge[gi];
        if (gs < 0) return m_next(s, nx, pos, out);
        int len = ge - gs;
        if (pos + len > s->len) return 0;
        for (int i = 0; i < len; i++)
            if (!cp_eq(s, str_unit(s->input, gs + i), str_unit(s->input, pos + i))) return 0;
        return m_next(s, nx, pos + len, out);
    }
    case RE_LOOKAHEAD: {
        Next empty;
        empty.node = NULL; empty.kids = NULL; empty.idx = 0; empty.nk = 0; empty.next = NULL;
        int e;
        int save_budget = s->budget;
        int ok = m(s, n->body, &empty, pos, &e);
        s->budget = save_budget;
        if (n->lookahead_neg) { if (ok) return 0; return m_next(s, nx, pos, out); }
        if (!ok) return 0;
        return m_next(s, nx, pos, out);
    }
    case RE_GROUP: {
        int gi = n->group;
        int old_s = gi ? s->gs[gi] : 0, old_e = gi ? s->ge[gi] : 0;
        int e;
        if (!m(s, n->body, nx, pos, &e)) {
            if (gi) { s->gs[gi] = old_s; s->ge[gi] = old_e; }
            return 0;
        }
        if (gi) { s->gs[gi] = pos; s->ge[gi] = e; }
        return 1;
    }
    case RE_CAT: {
        Next seq;
        seq.node = NULL;
        seq.kids = n->kids;
        seq.nk = n->nk;
        seq.idx = 0;
        seq.next = nx;
        return m_next(s, &seq, pos, out);
    }
    case RE_ALT: {
        int e;
        if (m(s, n->kids[0], nx, pos, &e)) { *out = e; return 1; }
        return m(s, n->kids[1], nx, pos, out);
    }
    case RE_REPEAT: {
        int max = n->max;
        if (n->greedy) {
            /* try to consume as many as possible, then backtrack */
            int cap = 64, cnt = 0;
            int *positions = js_malloc(cap * sizeof(int));
            positions[cnt++] = pos;
            int p = pos;
            while (max < 0 || cnt - 1 < max) {
                int e;
                int save_budget = s->budget;
                if (!m(s, n->body, NULL, p, &e)) { s->budget = save_budget; break; }
                s->budget = save_budget;
                if (e == p) break;
                p = e;
                if (cnt == cap) { int nc = cap * 2; int *np = js_malloc(nc * sizeof(int)); memcpy(np, positions, cnt * sizeof(int)); positions = np; cap = nc; }
                positions[cnt++] = p;
            }
            for (int i = cnt - 1; i >= 0; i--) {
                if (i < n->min) break;
                if (m_next(s, nx, positions[i], out)) return 1;
            }
            return 0;
        } else {
            int p = pos;
            int cnt = 0;
            while (cnt < n->min) {
                int e;
                if (!m(s, n->body, NULL, p, &e)) return 0;
                if (e == p) { /* empty match */ break; }
                p = e;
                cnt++;
            }
            if (cnt < n->min) return 0;
            for (;;) {
                if (m_next(s, nx, p, out)) return 1;
                if (max >= 0 && cnt >= max) return 0;
                int e;
                if (!m(s, n->body, NULL, p, &e)) return 0;
                if (e == p) return 0;
                p = e;
                cnt++;
            }
        }
    }
    }
    return 0;
}

/* --------------------------- RegExp object -------------------------------- */
typedef struct { ReNode *root; int ngroups; int flags; int global, sticky; JSValue source; } ReData;

static ReData *redata(JSValue re) { return (ReData *)obj_of(re)->extra; }

JSValue js_regexp_new(JSValue src, JSValue flags, int pos) {
    (void)pos;
    JSObject *o = js_malloc(sizeof(JSObject));
    o->cls = O_REGEXP;
    o->proto = ctx->regexp_proto;
    o->extensible = 1;
    ReData *d = js_malloc(sizeof(ReData));
    o->extra = d;
    JSValue v; v.u.p = o; v.tag = T_OBJ;
    JSValue sv;
    if (src.tag == T_OBJ && obj_of(src)->cls == O_REGEXP) {
        sv = js_regexp_get_source(src);
        if (flags.tag == T_UNDEF) flags = js_regexp_get_flags(src);
    } else if (src.tag == T_UNDEF) sv = js_atom("(?:)");
    else sv = js_to_string_v(src);
    JSValue fv = flags.tag == T_UNDEF ? js_atom("") : js_to_string_v(flags);
    const char *fs = (const char *)str_val(fv)->buf;
    int fl = 0;
    for (int i = 0; fs[i]; i++) {
        switch (fs[i]) {
        case 'g': fl |= 1; break;
        case 'i': fl |= 2; break;
        case 'm': fl |= 4; break;
        case 's': fl |= 8; break;
        case 'u': fl |= 16; break;
        case 'y': fl |= 32; break;
        case 'd': fl |= 64; break;
        default: js_throw_error(ERR_SYNTAX, "invalid regular expression flags");
        }
    }
    d->flags = fl;
    d->global = (fl & 1) != 0;
    d->sticky = (fl & 32) != 0;
    d->source = sv;
    int err = 0;
    d->root = re_compile((const char *)str_val(sv)->buf, str_val(sv)->blen, fl, &d->ngroups, &err);
    if (err || !d->root) {
        js_throw_error(ERR_SYNTAX, "invalid regular expression");
    }
    obj_add_prop(o, js_atom("lastIndex"), js_int(0), P_W | P_C);
    obj_add_prop(o, js_atom("source"), sv, P_W | P_C);
    obj_add_prop(o, js_atom("flags"), fv, P_W | P_C);
    obj_add_prop(o, js_atom("global"), js_bool(d->global), P_W | P_C);
    obj_add_prop(o, js_atom("ignoreCase"), js_bool((fl & 2) != 0), P_W | P_C);
    obj_add_prop(o, js_atom("multiline"), js_bool((fl & 4) != 0), P_W | P_C);
    obj_add_prop(o, js_atom("dotAll"), js_bool((fl & 8) != 0), P_W | P_C);
    obj_add_prop(o, js_atom("unicode"), js_bool((fl & 16) != 0), P_W | P_C);
    obj_add_prop(o, js_atom("sticky"), js_bool(d->sticky), P_W | P_C);
    obj_add_prop(o, ctx->sym_tostringtag, js_atom("RegExp"), P_W | P_C);
    return v;
}
JSValue js_regexp_get_source(JSValue re) { return redata(re)->source; }
JSValue js_regexp_get_flags(JSValue re) {
    JSValue f = obj_get_prop(obj_of(re), js_atom("flags"), 0);
    return f.tag == T_STR ? f : js_atom("");
}
JSValue js_regexp_get_lastindex(JSValue re) { return obj_get_prop(obj_of(re), js_atom("lastIndex"), 0); }
void js_regexp_set_lastindex(JSValue re, JSValue v) { obj_set_prop(obj_of(re), js_atom("lastIndex"), v, 0, 0); }

/* build the result array from a match */
static JSValue build_match_result(ReState *s, int start, int end) {
    JSObject *a = js_new_array_obj();
    for (int i = 0; i <= s->ngroups; i++) {
        if (i == 0) js_array_push(a, js_substring(s->input, start, end));
        else if (s->gs[i] >= 0) js_array_push(a, js_substring(s->input, s->gs[i], s->ge[i]));
        else js_array_push(a, js_undef());
    }
    obj_add_prop(a, js_atom("index"), js_int(start), P_W | P_E | P_C);
    obj_add_prop(a, js_atom("input"), (JSValue){ .u.p = (void*)s->input, .tag = T_STR }, P_W | P_E | P_C);
    obj_add_prop(a, js_atom("groups"), js_undef(), P_W | P_E | P_C);
    return (JSValue){ .u.p = a, .tag = T_OBJ };
}

JSValue js_regexp_exec(JSValue re, JSValue str, int pos, int *is_match, int *last_index_out) {
    (void)pos;
    ReData *d = redata(re);
    JSString *s = str_val(str);
    int start = 0;
    if (d->global || d->sticky) {
        JSValue li = js_regexp_get_lastindex(re);
        start = (int)js_to_number(li);
        if (start < 0) start = 0;
        if (start > s->len) {
            if (d->global) js_regexp_set_lastindex(re, js_int(0));
            if (is_match) *is_match = 0;
            return js_null();
        }
    }
    ReState st;
    memset(&st, 0, sizeof(st));
    st.input = s;
    st.len = s->len;
    st.ngroups = d->ngroups;
    st.multiline = (d->flags & 4) != 0;
    st.ignore_case = (d->flags & 2) != 0;
    st.dotall = (d->flags & 8) != 0;
    st.sticky = d->sticky;
    st.unicode = (d->flags & 16) != 0;
    st.gs = js_malloc((d->ngroups + 1) * sizeof(int));
    st.ge = js_malloc((d->ngroups + 1) * sizeof(int));
    for (int i = 0; i <= d->ngroups; i++) { st.gs[i] = -1; st.ge[i] = -1; }
    st.budget = 2000000;
    int found = 0, mstart = 0, mend = 0;
    for (int p = start; p <= s->len; p++) {
        int out;
        st.budget = 2000000;
        Next empty;
        empty.node = NULL; empty.kids = NULL; empty.idx = 0; empty.nk = 0; empty.next = NULL;
        if (m(&st, d->root, &empty, p, &out)) {
            found = 1;
            mstart = p;
            mend = out;
            break;
        }
        if (st.budget < 0) break;
        if (d->sticky) break;
    }
    if (!found) {
        if (d->global || d->sticky) js_regexp_set_lastindex(re, js_int(0));
        if (is_match) *is_match = 0;
        return js_null();
    }
    if (d->global || d->sticky) js_regexp_set_lastindex(re, js_int(mend));
    if (is_match) *is_match = 1;
    if (last_index_out) *last_index_out = mend;
    return build_match_result(&st, mstart, mend);
}
JSValue js_regexp_test(JSValue re, JSValue str, int pos) {
    int m = 0;
    js_regexp_exec(re, str, pos, &m, NULL);
    return js_bool(m);
}
