/* ------------------------------- printf ----------------------------------- */
static int fmt_one(Buf *b, const char **pfmt, int *argi, int argc, JSValue *argv, int pos) {
    const char *f = *pfmt;
    if (*f != '%') { buf_putc(b, *f); *pfmt = f + 1; return 1; }
    f++;
    if (*f == '%') { buf_putc(b, '%'); *pfmt = f + 1; return 1; }
    /* flags */
    char spec[64];
    int si = 0;
    spec[si++] = '%';
    while (*f && strchr("-+ #0", *f)) { spec[si++] = *f++; }
    while (*f && isdigit((unsigned char)*f)) { if (si < 40) spec[si++] = *f; f++; }
    if (*f == '.') { spec[si++] = *f++; while (*f && isdigit((unsigned char)*f)) { if (si < 40) spec[si++] = *f; f++; } }
    if (*f == 'l' || *f == 'h' || *f == 'j' || *f == 'z' || *f == 't' || *f == 'L') { f++; }
    char conv = *f;
    if (!conv) { *pfmt = f; js_throw_error(ERR_TYPE, "invalid conversion specifier in format string"); }
    spec[si++] = conv;
    spec[si] = 0;
    *pfmt = f + 1;
    switch (conv) {
    case 'd': case 'i': case 'o': case 'u': case 'x': case 'X': case 'c': {
        int64_t v = (int64_t)js_to_number(*argi < argc ? argv[*argi] : js_undef());
        (*argi)++;
        char t[128];
        if (conv == 'c') {
            unsigned ch = (unsigned)v;
            if (ch < 128) { char cc = (char)ch; buf_put(b, &cc, 1); }
            else { uint8_t tmp[4]; buf_put(b, tmp, js_utf8_encode(tmp, ch)); }
        } else {
            char spec2[64];
            snprintf(spec2, sizeof spec2, "%sll%s", spec + 1 + (spec[1]=='%'?0:0), strchr("di", conv) ? conv == 'i' ? "d" : "d" : conv == 'u' ? "u" : conv == 'o' ? "o" : conv == 'x' ? "x" : "X");
            snprintf(t, sizeof t, spec2, (long long)v);
            buf_puts(b, t);
        }
        return 1;
    }
    case 'e': case 'E': case 'f': case 'F': case 'g': case 'G': case 'a': case 'A': {
        double v = js_to_number(*argi < argc ? argv[*argi] : js_undef());
        (*argi)++;
        char t[512];
        snprintf(t, sizeof t, spec, v);
        buf_puts(b, t);
        return 1;
    }
    case 's': case 'q': {
        JSValue v = *argi < argc ? argv[*argi] : js_undef();
        (*argi)++;
        JSValue sv;
        if (conv == 'q') sv = js_inspect_str(v, 0);
        else if (v.tag == T_STR) sv = v;
        else if (v.tag == T_UNDEF || v.tag == T_NULL || v.tag == T_BOOL || js_is_number(v) || v.tag == T_BIG) sv = js_to_string_v(v);
        else sv = js_object_to_string(js_is_obj(v) ? obj_of(v) : obj_of(js_to_object(v)));
        JSString *ss = str_val(sv);
        char spec2[64];
        int prec = -1, width = 0;
        /* extract width/precision */
        const char *q = spec + 1;
        char wbuf[16]; int wi = 0;
        while (*q && isdigit((unsigned char)*q)) { if (wi < 15) wbuf[wi++] = *q; q++; }
        wbuf[wi] = 0;
        if (wi) width = atoi(wbuf);
        if (*q == '.') { q++; prec = 0; while (*q && isdigit((unsigned char)*q)) { prec = prec * 10 + (*q - '0'); q++; } }
        int blen = ss->blen;
        if (prec >= 0 && prec < blen) blen = str_units_to_bytes(ss, 0, prec);
        int pad = width - blen;
        if (!(spec[1] == '-')) for (int i = 0; i < pad; i++) buf_putc(b, ' ');
        buf_put(b, ss->buf, blen);
        if (spec[1] == '-') for (int i = 0; i < pad; i++) buf_putc(b, ' ');
        return 1;
    }
    default:
        js_throw_error(ERR_TYPE, "invalid conversion specifier in format string");
    }
    return 1;
}
JSValue js_std_sprintf(const char *fmt, int argc, JSValue *argv, int pos) {
    (void)pos;
    Buf b; buf_init(&b, 64);
    const char *f = fmt;
    int argi = 0;
    while (*f) {
        if (*f == '%') {
            const char *f2 = f;
            fmt_one(&b, &f2, &argi, argc, argv, 0);
            f = f2;
        } else { buf_putc(&b, *f); f++; }
    }
    return js_atom_buf(b.b, b.len, b.len);
}
