    js_define_method(m, "setenv", js_std_setenv_fn, 2, NULL);
    js_define_method(m, "unsetenv", js_std_unsetenv_fn, 1, NULL);
    js_define_method(m, "getenviron", js_std_getenviron_fn, 0, NULL);
