/* ------------------------------ FILE methods ------------------------------- */
static JSValue js_file_write(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)opaque;
    JSObject *o = obj_of(this_val);
    FILE *f = (FILE *)o->extra;
    if (!f) js_throw_error(ERR_TYPE, "I/O error");
    for (int i = 0; i < argc; i++) {
        JSValue s = js_to_string_v(argv[i]);
        JSString *ss = str_val(s);
        fwrite(ss->buf, 1, ss->blen, f);
    }
    return js_undef();
}
static JSValue js_file_puts(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    return js_file_write(this_val, argc, argv, opaque);
}
static JSValue js_file_getline(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)argc; (void)opaque;
    JSObject *o = obj_of(this_val);
    FILE *f = (FILE *)o->extra;
    if (!f) js_throw_error(ERR_TYPE, "I/O error");
    Buf b; buf_init(&b, 64);
    int got = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\n') { got = 1; break; }
        buf_putc(&b, (uint8_t)c);
        got = 1;
    }
    if (!got && b.len == 0) return js_null();
    return js_atom_buf(b.b, b.len, b.len);
}
static JSValue js_file_read(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)opaque;
    JSObject *o = obj_of(this_val);
    FILE *f = (FILE *)o->extra;
    if (!f) js_throw_error(ERR_TYPE, "I/O error");
    int n = argc ? (int)js_to_number(argv[0]) : 1024;
    if (n < 0) n = 0;
    char *buf = js_malloc(n + 1);
    size_t rd = fread(buf, 1, n, f);
    return js_atom_buf((const uint8_t *)buf, (int)rd, (int)rd);
}
static JSValue js_file_close(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)argc; (void)argv; (void)opaque;
    JSObject *o = obj_of(this_val);
    FILE *f = (FILE *)o->extra;
    if (f) { fclose(f); o->extra = NULL; }
    return js_undef();
}
static JSValue js_file_flush(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)argc; (void)argv; (void)opaque;
    JSObject *o = obj_of(this_val);
    FILE *f = (FILE *)o->extra;
    if (f) fflush(f);
    return js_undef();
}
static JSValue js_file_seek(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)opaque;
    JSObject *o = obj_of(this_val);
    FILE *f = (FILE *)o->extra;
    if (!f) js_throw_error(ERR_TYPE, "I/O error");
    long off = argc ? (long)js_to_number(argv[0]) : 0;
    int whence = argc > 1 ? (int)js_to_number(argv[1]) : 0;
    int r = fseek(f, off, whence == 0 ? SEEK_SET : whence == 1 ? SEEK_CUR : SEEK_END);
    return js_bool(r == 0);
}
static JSValue js_file_tell(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)argc; (void)argv; (void)opaque;
    JSObject *o = obj_of(this_val);
    FILE *f = (FILE *)o->extra;
    if (!f) js_throw_error(ERR_TYPE, "I/O error");
    return js_int(ftell(f));
}
static JSValue js_file_eof(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)argc; (void)argv; (void)opaque;
    JSObject *o = obj_of(this_val);
    FILE *f = (FILE *)o->extra;
    if (!f) return js_true();
    return js_bool(feof(f) != 0);
}
static JSValue js_file_error(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)argc; (void)argv; (void)opaque;
    JSObject *o = obj_of(this_val);
    FILE *f = (FILE *)o->extra;
    if (!f) return js_true();
    return js_bool(ferror(f) != 0);
}

void js_init_std_module(void) {
    JSObject *m = js_new_object(O_OBJECT);
    m->proto = ctx->obj_proto;
    js_define_method(m, "printf", js_std_printf_fn, 1, NULL);
    js_define_method(m, "sprintf", js_std_sprintf_fn, 1, NULL);
    js_define_method(m, "puts", js_std_puts_fn, 1, NULL);
    js_define_method(m, "open", js_std_open_fn, 2, NULL);
    js_define_method(m, "exit", js_std_exit_fn, 1, NULL);
    js_define_method(m, "gc", js_std_gc_fn, 0, NULL);
    js_define_method(m, "getenv", js_std_getenv_fn, 1, NULL);
    js_define_method(m, "setenv", js_std_setenv_fn, 2, NULL);
    js_define_method(m, "unsetenv", js_std_unsetenv_fn, 1, NULL);
    js_define_method(m, "getenviron", js_std_getenviron_fn, 0, NULL);
    js_define_method(m, "strerror", js_std_strerror_fn, 1, NULL);
    js_define_method(m, "loadFile", js_std_loadfile_fn, 1, NULL);
    js_define_method(m, "readFile", js_std_readfile_fn, 1, NULL);
    js_define_method(m, "urlGet", js_std_urlget_fn, 1, NULL);
    js_define_method(m, "parseExtJSON", js_std_parseextjson_fn, 1, NULL);
    js_define_method(m, "tmpfile", js_std_tmpfile_fn, 0, NULL);
    js_define_method(m, "fdopen", js_std_fdopen_fn, 2, NULL);
    js_define_method(m, "loadScript", js_std_loadscript_fn, 1, NULL);
    js_define_method(m, "evalScript", js_std_evalscript_fn, 1, NULL);
    js_define_method(m, "__printObject", js_std_printf_fn, 1, NULL);
    obj_add_prop(m, js_atom("SEEK_SET"), js_int(0), P_W | P_E | P_C);
    obj_add_prop(m, js_atom("SEEK_CUR"), js_int(1), P_W | P_E | P_C);
    obj_add_prop(m, js_atom("SEEK_END"), js_int(2), P_W | P_E | P_C);
    obj_add_prop(m, js_atom("in"), js_std_file_obj(stdin, 0), P_W | P_E | P_C);
    obj_add_prop(m, js_atom("out"), js_std_file_obj(stdout, 0), P_W | P_E | P_C);
    obj_add_prop(m, js_atom("err"), js_std_file_obj(stderr, 0), P_W | P_E | P_C);
    obj_add_prop(m, js_atom("Error"), (JSValue){ .u.p = js_new_object(O_OBJECT), .tag = T_OBJ }, P_W | P_E | P_C);
    JSValue mv; mv.u.p = m; mv.tag = T_OBJ;
    obj_add_prop(ctx->global, js_atom("std"), mv, P_W | P_E | P_C);
    /* FILE prototype */
    file_proto = js_new_object(O_OBJECT);
    file_proto->proto = ctx->obj_proto;
    js_define_method(file_proto, "write", js_file_write, 1, NULL);
    js_define_method(file_proto, "puts", js_file_puts, 1, NULL);
    js_define_method(file_proto, "getline", js_file_getline, 0, NULL);
    js_define_method(file_proto, "read", js_file_read, 1, NULL);
    js_define_method(file_proto, "close", js_file_close, 0, NULL);
    js_define_method(file_proto, "flush", js_file_flush, 0, NULL);
    js_define_method(file_proto, "seek", js_file_seek, 2, NULL);
    js_define_method(file_proto, "tell", js_file_tell, 0, NULL);
    js_define_method(file_proto, "tello", js_file_tell, 0, NULL);
    js_define_method(file_proto, "eof", js_file_eof, 0, NULL);
    js_define_method(file_proto, "error", js_file_error, 0, NULL);
}

