static JSValue js_os_write_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
    if (argc < 3) return js_int(-1);
    int fd = (int)js_to_number(argv[0]);
    JSValue buf = js_to_string_v(argv[1]);
    int offset = argc > 2 ? (int)js_to_number(argv[2]) : 0;
    JSString *s = str_val(buf);
    int blen = s->blen - offset;
    if (blen < 0) blen = 0;
    if (blen > 0) blen = str_units_to_bytes(s, offset, blen);
    ssize_t r = write(fd, s->buf + str_unit_to_byte(s, offset), blen);
    return js_int((int)r);
}
