static JSValue js_os_readdir_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
    if (!argc) return js_null();
    JSValue p = js_to_string_v(argv[0]);
    DIR *d = opendir((const char *)str_val(p)->buf);
    if (!d) return js_null();
    JSObject *a = js_new_array_obj();
    struct dirent *de;
    while ((de = readdir(d))) {
        if (!strcmp(de->d_name, ".") || !strcmp(de->d_name, "..")) continue;
        js_array_push(a, js_string(de->d_name));
    }
    closedir(d);
    return (JSValue){ .u.p = a, .tag = T_OBJ };
}
static void add_stat(JSObject *o, struct stat *st) {
    obj_add_prop(o, js_atom("dev"), js_int((int)st->st_dev), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("ino"), js_int((int)st->st_ino), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("mode"), js_int((int)st->st_mode), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("nlink"), js_int((int)st->st_nlink), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("uid"), js_int((int)st->st_uid), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("gid"), js_int((int)st->st_gid), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("rdev"), js_int((int)st->st_rdev), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("size"), js_int((int64_t)st->st_size), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("blocks"), js_int((int)st->st_blocks), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("blksize"), js_int((int)st->st_blksize), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("atime"), js_float((double)st->st_atime), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("mtime"), js_float((double)st->st_mtime), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("ctime"), js_float((double)st->st_ctime), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("atime_ms"), js_float((double)st->st_atime * 1000.0), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("mtime_ms"), js_float((double)st->st_mtime * 1000.0), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("ctime_ms"), js_float((double)st->st_ctime * 1000.0), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("is_character_device"), js_bool(S_ISCHR(st->st_mode)), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("is_block_device"), js_bool(S_ISBLK(st->st_mode)), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("is_fifo"), js_bool(S_ISFIFO(st->st_mode)), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("is_symbolic_link"), js_bool(S_ISLNK(st->st_mode)), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("is_file"), js_bool(S_ISREG(st->st_mode)), P_W | P_E | P_C);
    obj_add_prop(o, js_atom("is_directory"), js_bool(S_ISDIR(st->st_mode)), P_W | P_E | P_C);
}
static JSValue stat_common(int argc, JSValue *argv, int follow) {
    if (!argc) return js_null();
    JSValue p = js_to_string_v(argv[0]);
    struct stat st;
    int r = follow ? stat((const char *)str_val(p)->buf, &st) : lstat((const char *)str_val(p)->buf, &st);
    if (r < 0) return js_null();
    JSObject *o = js_new_object(O_OBJECT);
    add_stat(o, &st);
    return (JSValue){ .u.p = o, .tag = T_OBJ };
}
static JSValue js_os_stat_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
    return stat_common(argc, argv, 1);
}
