static JSValue js_os_sleep_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
    double s = argc ? js_to_number(argv[0]) : 0;
    if (s > 0) {
        struct timespec ts;
        ts.tv_sec = (time_t)s;
        ts.tv_nsec = (long)((s - (double)ts.tv_sec) * 1e9);
        nanosleep(&ts, NULL);
    }
    return js_undef();
}
