{"command": "cat > src/modules.c <<'CEOF'
#include "internal.h"
#include <math.h>
#include <unistd.h>
#include <libgen.h>

static Module *cur_module;
static JSObject *ns_proto;

static Module *find_module(const char *name) {
    for (Module *m = ctx->modules; m; m = m->next)
        if (!strcmp(m->name, name)) return m;
    return NULL;
}

static void add_bind(Module *m, JSValue name, Module *src, JSValue lname) {
    if (m->nb == m->bcap) {
        int nc = m->bcap ? m->bcap * 2 : 8;
        void *nb = js_malloc(nc * sizeof(void*) * 4);
        if (m->nb) memcpy(nb, m->binds, m->nb * sizeof(void*) * 4);
        m->binds = nb; m->bcap = nc;
    }
    m->binds[m->nb].name = name;
    m->binds[m->nb].m = src;
    m->binds[m->nb].lname = lname;
    m->binds[m->nb].ptr = NULL;
    m->binds[m->nb].indirect = 0;
    m->nb++;
}

static void module_export_set(Module *m, JSValue name, JSValue val) {
    obj_add_prop(m->exports, name, val, P_W | P_E | P_C);
}
static JSValue module_export_get(Module *m, JSValue name) {
    return obj_get_prop(m->exports, name, 0);
}

static char *read_file(const char *path, int *len_out) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = js_malloc(sz + 1);
    size_t rd = fread(buf, 1, sz, f);
    fclose(f);
    *len_out = (int)rd;
    return buf;
}

static char resolved_path[4096];
static const char *resolve_path(const char *base, const char *spec) {
    if (spec[0] == '/') return spec;
    if (base) {
        const char *slash = strrchr(base, '/');
        if (slash) {
            int n = (int)(slash - base) + 1;
            if (n + strlen(spec) < (int)sizeof resolved_path) {
                memcpy(resolved_path, base, n);
                strcpy(resolved_path + n, spec);
                return resolved_path;
            }
        }
    }
    return spec;
}

static JSValue module_namespace_obj(Module *m) {
    JSObject *o = js_malloc(sizeof(JSObject));
    o->cls = O_MODULE_NS;
    o->proto = ns_proto ? ns_proto : ctx->obj_proto;
    o->extensible = 0;
    for (Prop *p = m->exports->props; p; p = p->next)
        obj_add_prop(o, p->key, p->val, P_E | P_C);
    JSValue v; v.u.p = o; v.tag = T_OBJ;
    return v;
}

static void module_eval(Module *m);

static Module *load_module(const char *path, int pos) {
    (void)pos;
    Module *m = find_module(path);
    if (m) return m;
    int len = 0;
    char *src = read_file(path, &len);
    if (!src) {
        js_throw_error(ERR_TYPE, "could not load module filename '%s'", path);
    }
    m = js_malloc(sizeof(Module));
    memset(m, 0, sizeof(Module));
    m->name = js_strdup(path);
    m->exports = js_new_object(O_OBJECT);
    m->next = ctx->modules;
    ctx->modules = m;
    Ast *prog = js_parse(src, len, 1, 0, path);
    m->prog = prog;
    m->env = env_new(ctx->global_env, 0);
    m->env->is_func = 1;
    module_eval(m);
    return m;
}

static void module_eval(Module *m) {
    if (m->evaluated) return;
    m->evaluated = 1;
    Module *saved = cur_module;
    Env *saved_env = ctx->cur_env;
    cur_module = m;
    ctx->cur_env = m->env;
    /* hoist function declarations */
    hoist_vars_pub(m->prog->k[0], m->env);
    JS_TRY
        exec_stmt_pub(m->prog->k[0], m->env);
    JS_CATCH
        ctx->cur_env = saved_env;
        cur_module = saved;
        js_rethrow();
    JS_END
    ctx->cur_env = saved_env;
    cur_module = saved;
}

JSValue js_load_module(const char *spec, int pos) {
    const char *base = ctx->filename;
    const char *path = resolve_path(base, spec);
    Module *m = load_module(path, pos);
    return module_namespace_obj(m);
}

/* --------------------------- import/export execution ---------------------- */
static void exec_import(Ast *n, Env *env) {
    JSValue modname = n->k[0]->v;
    const char *base = cur_module ? cur_module->name : ctx->filename;
    const char *path = resolve_path(base, (const char *)str_val(modname)->buf);
    Module *m = load_module(path, n->pos);
    Ast *clauses = n->k[1];
    for (int i = 0; i < clauses->nk; i++) {
        Ast *c = clauses->k[i];
        if (c->kind == N_SPREAD) {
            env_define(env, c->v, module_namespace_obj(m), P_E);
            continue;
        }
        JSValue local = c->k[0]->v;
        JSValue imported = c->k[1]->v;
        JSValue val = module_export_get(m, imported);
        if (val.tag == T_UNDEF && !obj_find_prop(m->exports, imported)) {
            js_throw_error(ERR_SYNTAX, "could not find exported name '%s' in module '%s'",
                           str_val(imported)->buf, path);
        }
        env_define(env, local, val, P_E);
    }
}

static void exec_export(Ast *n, Env *env) {
    if (!cur_module) return;
    Module *m = cur_module;
    if (n->flags & F_EXPORTDEF) {
        Ast *e = n->k[0];
        JSValue val;
        if (e->kind == N_FUNC) {
            val = js_create_function(e, env);
            if (e->v.tag == T_STR) env_define(env, e->v, val, P_E);
            module_export_set(m, js_atom("default"), val);
            return;
        }
        if (e->kind == N_CLASS) {
            val = eval_class_pub(e, env, e->v);
            if (e->v.tag == T_STR) env_define(env, e->v, val, P_E);
            module_export_set(m, js_atom("default"), val);
            return;
        }
        val = eval_expr_pub(e, env);
        module_export_set(m, js_atom("default"), val);
        return;
    }
    /* export <decl> */
    if (n->nk >= 1 && n->k[0] && n->k[0]->kind == N_VARDECL) {
        exec_stmt_pub(n->k[0], env);
        Ast *vd = n->k[0];
        for (int i = 0; i < vd->nk; i++) {
            Ast *d = vd->k[i];
            JSValue names[64];
            int nn = binding_names_pub(d->k[0], names, 64);
            for (int q = 0; q < nn; q++) {
                JSValue v = env_get_quiet(env, names[q]);
                module_export_set(m, names[q], v);
            }
        }
        return;
    }
    if (n->nk >= 3 && n->k[1] && n->k[1]->kind == N_FUNC) {
        Ast *f = n->k[1];
        JSValue val = js_create_function(f, env);
        if (f->v.tag == T_STR) env_define(env, f->v, val, P_E);
        module_export_set(m, f->v, val);
        return;
    }
    if (n->nk >= 3 && n->k[1] && n->k[1]->kind == N_CLASS) {
        Ast *c = n->k[1];
        JSValue val = eval_class_pub(c, env, c->v);
        if (c->v.tag == T_STR) env_define(env, c->v, val, P_E);
        module_export_set(m, c->v, val);
        return;
    }
    /* export { a, b as c } */
    if (n->nk >= 1 && n->k[0] && n->k[0]->kind == N_ARRAY) {
        Ast *clauses = n->k[0];
        for (int i = 0; i < clauses->nk; i++) {
            Ast *c = clauses->k[i];
            JSValue in = c->k[1]->v;
            JSValue out = c->k[0]->v;
            JSValue v = env_get_quiet(env, in);
            module_export_set(m, out, v);
        }
        return;
    }
    /* export * from "mod" */
    if (n->nk >= 2 && n->k[1] && n->k[1]->kind == N_STR) {
        JSValue modname = n->k[1]->v;
        const char *base = cur_module->name;
        const char *path = resolve_path(base, (const char *)str_val(modname)->buf);
        Module *src = load_module(path, n->pos);
        if (n->nk >= 1 && n->k[0] && n->k[0]->kind == N_ARRAY && n->k[0]->nk) {
            /* export * as ns from */
            JSValue ns = module_namespace_obj(src);
            env_define(env, n->k[0]->k[0]->v, ns, P_E);
            module_export_set(m, n->k[0]->k[0]->v, ns);
        } else {
            for (Prop *p = src->exports->props; p; p = p->next) {
                if (str_equal(str_val(p->key), str_val(js_atom("default")))) continue;
                module_export_set(m, p->key, p->val);
            }
        }
        return;
    }
}

void js_module_exec_import(Ast *n, Env *env) {
    exec_import(n, env);
}
void js_module_exec_export(Ast *n, Env *env) {
    exec_export(n, env);
}

void js_init_module_system(void) {
    ns_proto = js_new_object(O_OBJECT);
    ns_proto->proto = ctx->obj_proto;
    obj_add_prop(ns_proto, ctx->sym_tostringtag, js_atom("Module"), P_W | P_C);
}
JSObject *js_module_get(const char *name) {
    Module *m = find_module(name);
    if (!m) return NULL;
    return m->exports;
}
