    }
    return (int64_t)d;
}

static int is_module_source(const char *src, int len) {
    int i = 0;
    for (;;) {
        while (i < len && (src[i] == ' ' || src[i] == '\t' || src[i] == '\n' || src[i] == '\r')) i++;
        if (i + 1 < len && src[i] == '/' && src[i+1] == '/') {
            while (i < len && src[i] != '\n') i++;
            continue;
        }
        if (i + 1 < len && src[i] == '/' && src[i+1] == '*') {
            i += 2;
            while (i + 1 < len && !(src[i] == '*' && src[i+1] == '/')) i++;
            i += 2;
            continue;
        }
        break;
    }
    if (i + 6 <= len && !memcmp(src + i, "import", 6) && (i + 6 == len || !isalnum((unsigned char)src[i+6]))) return 1;
    if (i + 6 <= len && !memcmp(src + i, "export", 6) && (i + 6 == len || !isalnum((unsigned char)src[i+6]))) return 1;
    return 0;
}

/* -------------------------- error reporting ------------------------------- */
static void print_error(FILE *f, JSValue err) {
    JSValue s = js_error_to_string(err, 0);
    JSString *ss = str_val(s);
    fwrite(ss->buf, 1, ss->blen, f);
    JSValue st = js_get_stack_str(err);
    if (st.tag == T_STR && str_val(st)->len) {
        fprintf(f, "\n");
        JSString *s2 = str_val(st);
        fwrite(s2->buf, 1, s2->blen, f);
    }
    fprintf(f, "\n");
