/* ------------------------------ script running ---------------------------- */
static int run_source(const char *src, int len, const char *filename, int is_module, int strict) {
    ctx->filename = filename;
    ctx->cur_src = js_make_src(src, len);
    JSValue exc = js_undef();
    JS_TRY
        Ast *prog = js_parse(src, len, is_module, strict, filename);
        js_eval_program(prog, ctx->global_lex, 0);
        js_run_event_loop();
    JS_CATCH
        exc = ctx->exc;
        return handle_uncaught(exc);
    JS_END
    return 0;
}

int js_run_script_pub(const char *src, int len, const char *filename, int flags) {
