/* -------------------------------- REPL ------------------------------------ */
static const char *repl_help =
    "\\h          this help\n"
    "\\x          hexadecimal number display\n"
    "\\d         *decimal number display\n"
    "\\t          toggle timing display\n"
    "\\clear      clear the terminal\n"
    "\\q          exit\n";

static char line_buf[65536];

static void repl_eval_line(const char *line, int len) {
    /* wrap in a function to get the completion value */
    Buf b; buf_init(&b, len + 64);
    buf_puts(&b, "(function(){");
    buf_put(&b, line, len);
    buf_puts(&b, "\n})()");
    JSValue exc = js_undef();
    JS_TRY
        Ast *prog = js_parse((const char *)b.b, b.len, 0, 0, "<evalScript>");
        JSValue r = js_eval_program(prog, ctx->global_lex, 0);
        js_run_event_loop();
        JSValue s = js_inspect_str(r, 0);
        JSString *ss = str_val(s);
        fwrite(ss->buf, 1, ss->blen, stdout);
        printf("\n");
    JS_CATCH
        exc = ctx->exc;
        print_error(stdout, exc);
    JS_END
}

static void interactive(void) {
    printf("QuickJS - Type \"\\h\" for help\n");
    for (;;) {
        printf("qjs > ");
        fflush(stdout);
        if (!fgets(line_buf, sizeof line_buf, stdin)) break;
        int len = (int)strlen(line_buf);
        while (len > 0 && (line_buf[len-1] == '\n' || line_buf[len-1] == '\r')) len--;
        line_buf[len] = 0;
        if (len == 0) continue;
        if (line_buf[0] == '\\') {
            if (len >= 2 && line_buf[1] == 'h') { fputs(repl_help, stdout); continue; }
            if (len >= 2 && line_buf[1] == 'q') { break; }
            if (len >= 6 && !memcmp(line_buf, "\\clear", 6)) { printf("\033[H\033[J"); continue; }
            if (len >= 2 && line_buf[1] == 'x') { continue; }
            if (len >= 2 && line_buf[1] == 'd') { continue; }
            if (len >= 2 && line_buf[1] == 't') { continue; }
            printf("Unknown directive: %c\n", line_buf[1]);
            continue;
        }
        /* multi-line: keep reading while incomplete */
        Buf b; buf_init(&b, len + 1);
        buf_put(&b, line_buf, len);
        repl_eval_line((const char *)b.b, b.len);
    }
}

