/* ----------------------------- Proxy / Reflect ----------------------------- */
JSValue js_make_proxy(JSValue target, JSValue handler, int pos) {
    (void)pos;
    if (target.tag != T_OBJ) js_throw_error(ERR_TYPE, "not an object");
    if (handler.tag != T_OBJ) js_throw_error(ERR_TYPE, "not an object");
    JSObject *o = js_malloc(sizeof(JSObject));
    o->cls = O_PROXY;
    o->proto = obj_of(target)->proto;
    o->extensible = 1;
    JSValue *pair = js_malloc(2 * sizeof(JSValue));
    pair[0] = target;
    pair[1] = handler;
    o->extra = pair;
    return (JSValue){ .u.p = o, .tag = T_OBJ };
}

/* ------------------------------ TypedArrays ------------------------------- */
static const char *ta_names[10] = { "Int8Array", "Uint8Array", "Uint8ClampedArray", "Int16Array",
    "Uint16Array", "Int32Array", "Uint32Array", "Float32Array", "Float64Array", "BigInt64Array" };
static int ta_sizes[10] = { 1, 1, 1, 2, 2, 4, 4, 4, 8, 8 };
JSValue js_typedarray_new(int kind, JSValue arg, int pos) {
    JSObject *o = js_malloc(sizeof(JSObject));
    o->cls = O_TYPEDARRAY;
    o->proto = ctx->typedarray_proto ? ctx->typedarray_proto : ctx->obj_proto;
    o->extensible = 1;
    o->iter_kind = kind;
    int64_t len = 0;
    JSValue *data = NULL;
    if (arg.tag == T_UNDEF) len = 0;
    else if (js_is_number(arg)) {
        double d = js_to_number(arg);
        if (d < 0 || d != trunc(d)) js_throw_error(ERR_RANGE, "invalid array index");
        len = (int64_t)d;
    } else if (arg.tag == T_OBJ && obj_of(arg)->cls == O_ARRAYBUF) {
        len = (int64_t)(intptr_t)obj_of(arg)->extra / ta_sizes[kind];
    } else if (arg.tag == T_OBJ && obj_of(arg)->cls == O_TYPEDARRAY) {
        JSObject *src = obj_of(arg);
        len = src->alen;
        data = js_malloc((len + 1) * sizeof(JSValue));
        memcpy(data, src->arr, len * sizeof(JSValue));
    } else if (arg.tag == T_OBJ) {
        JSValue it = js_get_iterator(arg, pos);
        JSValue tmp = js_array_from(arg, pos);
        JSObject *to = obj_of(tmp);
        len = to->alen;
        data = js_malloc((len + 1) * sizeof(JSValue));
        for (int64_t i = 0; i < len; i++) data[i] = js_array_get(to, i);
        (void)it;
    } else if (arg.tag == T_STR) {
        JSValue tmp = js_array_from(arg, pos);
        JSObject *to = obj_of(tmp);
        len = to->alen;
        data = js_malloc((len + 1) * sizeof(JSValue));
        for (int64_t i = 0; i < len; i++) data[i] = js_array_get(to, i);
    }
    if (!data) { data = js_malloc((len + 1) * sizeof(JSValue)); for (int64_t i = 0; i < len; i++) data[i] = js_int(0); }
    o->arr = data;
    o->arr_len = (int)len;
    o->arr_cap = (int)len;
    o->alen = len;
    return (JSValue){ .u.p = o, .tag = T_OBJ };
}
static int ta_kind_from_name(const char *n) {
    for (int i = 0; i < 10; i++) if (!strcmp(n, ta_names[i])) return i;
    return -1;
}
JSValue js_arraybuffer_new(int64_t len, int pos) {
    (void)pos;
