    JSObject *o = js_malloc(sizeof(JSObject));
    o->cls = O_ARRAYBUF;
    o->proto = ctx->arraybuf_proto ? ctx->arraybuf_proto : ctx->obj_proto;
    o->extensible = 1;
    o->extra = (void *)(uintptr_t)len;
    return (JSValue){ .u.p = o, .tag = T_OBJ };
}
static JSValue js_arraybuffer_ctor(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
