static JSValue js_typedarray_ctor_generic(int kind, JSValue this_val, int argc, JSValue *argv) {
    if (this_val.tag == T_OBJ && obj_of(this_val)->cls == O_TYPEDARRAY) {
        JSValue r = js_typedarray_new(kind, argc ? argv[0] : js_undef(), 0);
        JSObject *o = obj_of(this_val);
        o->arr = obj_of(r)->arr;
        o->arr_len = obj_of(r)->arr_len;
        o->arr_cap = obj_of(r)->arr_cap;
        o->alen = obj_of(r)->alen;
        o->iter_kind = kind;
        return js_undef();
    }
    return js_typedarray_new(kind, argc ? argv[0] : js_undef(), 0);
}
