        js_throw_error(ERR_TYPE, "not a function");
    JSValue executor = argv[0];
    JSValue res = js_make_promise(0, NULL, NULL);
    JSObject *rf = js_malloc(sizeof(Func));
    memset(rf, 0, sizeof(Func));
    rf->hdr.cls = O_FUNCTION;
    rf->hdr.proto = ctx->func_proto;
    rf->is_native = 1;
    rf->cfunc = promise_resolve_function;
    rf->name = "";
    rf->is_ctor = 0;
    rf->opaque = (void *)obj_of(res);
    JSObject *jf = js_malloc(sizeof(Func));
    memset(jf, 0, sizeof(Func));
    jf->hdr.cls = O_FUNCTION;
    jf->hdr.proto = ctx->func_proto;
    jf->is_native = 1;
    jf->cfunc = promise_reject_function;
    jf->name = "";
    jf->is_ctor = 0;
    jf->opaque = (void *)obj_of(res);
    JSValue rv; rv.u.p = rf; rv.tag = T_OBJ;
    JSValue jv; jv.u.p = jf; jv.tag = T_OBJ;
    js_call(executor, js_undef(), 2, (JSValue[2]){ rv, jv }, 0);
