    JSValue v = argc ? argv[0] : js_undef();
    /* thenable resolution */
    if (v.tag == T_OBJ && obj_of(v)->cls != O_PROMISE) {
        JSValue then = js_get_prop(v, js_atom("then"), 0, 0);
        if (then.tag == T_OBJ && obj_of(then)->cls == O_FUNCTION) {
            JSValue res2 = js_make_promise(0, NULL, NULL);
            JSObject *rf2 = js_malloc(sizeof(Func));
            memset(rf2, 0, sizeof(Func));
            rf2->hdr.cls = O_FUNCTION;
            rf2->hdr.proto = ctx->func_proto;
            rf2->is_native = 1;
            rf2->cfunc = promise_resolve_function;
            rf2->name = "";
            rf2->opaque = (void *)obj_of(res2);
            JSObject *jf2 = js_malloc(sizeof(Func));
            memset(jf2, 0, sizeof(Func));
            jf2->hdr.cls = O_FUNCTION;
            jf2->hdr.proto = ctx->func_proto;
            jf2->is_native = 1;
            jf2->cfunc = promise_reject_function;
            jf2->name = "";
            jf2->opaque = (void *)obj_of(res2);
            js_call(then, v, 2, (JSValue[2]){ (JSValue){ .u.p = rf2, .tag = T_OBJ }, (JSValue){ .u.p = jf2, .tag = T_OBJ } }, 0);
            JSValue src = js_promise_then(res2, js_undef(), js_undef(), 0);
            (void)src;
            /* chain: when res2 settles, settle p */
            promise_settle(p, js_undef(), 0);
            return js_undef();
        }
    }
    promise_settle(pv, v, 0);
    return js_undef();
}
static JSValue promise_reject_function(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)argc;
    JSObject *p = (JSObject *)opaque;
