    promise_settle(pv, argc ? argv[0] : js_undef(), 1);
    return js_undef();
}
static JSValue js_promise_resolve_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
