static JSValue js_promise_withresolvers_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)argc; (void)argv; (void)opaque;
    JSValue p = js_make_promise(0, NULL, NULL);
    JSObject *o = js_new_object(O_OBJECT);
    JSValue pv; pv.u.p = p; pv.tag = T_OBJ;
    JSValue re = js_promise_resolve_fn(js_undef(), 1, (JSValue[1]){ pv }, opaque);
