/* --------------------- Map/Set/WeakMap/WeakSet methods ------------------- */
JSValue js_map_ctor_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
    return js_map_new(0, argc ? argv[0] : js_undef(), 0);
}
JSValue js_set_ctor_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
    return js_map_new(1, argc ? argv[0] : js_undef(), 0);
}
JSValue js_weakmap_ctor_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
    JSObject *o = js_malloc(sizeof(JSObject));
    o->cls = O_WEAKMAP;
    o->proto = ctx->map_proto;
    o->extensible = 1;
    o->extra = NULL;
    o->alen = 0;
    return (JSValue){ .u.p = o, .tag = T_OBJ };
}
JSValue js_weakset_ctor_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
    (void)this_val; (void)opaque;
    JSObject *o = js_malloc(sizeof(JSObject));
    o->cls = O_WEAKSET;
    o->proto = ctx->set_proto;
    o->extensible = 1;
    o->extra = NULL;
    o->alen = 0;
    return (JSValue){ .u.p = o, .tag = T_OBJ };
}
