    if (argc < 3) js_throw_error(ERR_TYPE, "not an object");
    js_set_prop(argv[0], js_to_property_key(argv[1]), argv[2], 0);
    return js_true();
}
JSValue js_reflect_has_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
