    JSObject *no = obj_of(names), *so = obj_of(syms);
    JSObject *r = js_new_array_obj();
    for (int64_t i = 0; i < no->alen; i++) js_array_push(r, js_array_get(no, i));
    for (int64_t i = 0; i < so->alen; i++) js_array_push(r, js_array_get(so, i));
    return (JSValue){ .u.p = r, .tag = T_OBJ };
}
JSValue js_reflect_delete_fn(JSValue this_val, int argc, JSValue *argv, void *opaque) {
